const CONTEXT = {
'9b:0:0': 'בסוף דף ט. שלושה תלמידי רבא באו לרב פפא אחרי פטירת רבא. כשלא נראו להם דבריו, רמזו זה לזה, ורב פפא ״חלש דעתיה״ (נפגע). עכשיו הגמרא ממשיכה: בלילה הקריאו לו בחלום את הפסוק ״ואכחיד את שלשת הרועים״ — אותו פסוק שנדרש בדף ט. על משה, אהרן ומרים. רש״י: הבין שבגלל שציערוהו, הם עלולים להיענש בשמים.',
'9b:0:1': 'למחרת, כשהתלמידים נפרדו מרב פפא, הוא אמר להם ״ליזלו רבנן בשלמא״ — לכו לשלום. רב פפא מחל להם ובירך אותם, כדי שהחלום לא יתקיים בהם. כך הוא לא נתן לפגיעה שלו לגרום להם עונש.',
'9b:1:0': 'עוד מעשה ברב פפא, שממשיך את הנושא של רגישות בין תלמיד לרב. רב שימי בר אשי היה תלמיד שלמד תמיד לפני רב פפא, והיה מקשה לו הרבה קושיות.',
'9b:1:1': 'יום אחד ראה רב שימי את רב פפא נופל על פניו בתפילה (נפילת אפיים, תחנון), ושמע אותו אומר: ״רחמנא ליצלן מכיסופא דשימי״ — שה׳ יציל אותו מהבושה שהוא מתבייש כשאינו יודע לענות לקושיות של שימי.',
'9b:1:2': 'כששמע רב שימי את התפילה, הבין שהקושיות שלו מצערות את רבו. לכן קיבל על עצמו שתיקה, ולא הקשה לרב פפא עוד. רש״י: ״קבל עליו — רב שימי שתיקותא מלהקשות עוד״. המעשה מראה כמה חשוב לא לבייש את הרב.',
'9b:2:0': 'בדף ט. אמר ר׳ יוחנן ״מטר בשביל יחיד, פרנסה בשביל רבים״. עכשיו הגמרא מוסיפה שגם ריש לקיש סובר כמותו: מטר יורד אפילו בשביל אדם יחיד. ויש לו ראיה משלו מפסוק אחר.',
'9b:2:1': 'ריש לקיש מביא פסוק מזכריה: ״שאלו מה׳ מטר בעת מלקוש, ה׳ עושה חזיזים, ומטר גשם יתן להם, לאיש עשב בשדה״. סוף הפסוק מדבר על ״איש״ אחד, ו״עשב״ אחד ב״שדה״ — סימן שהגשם יכול לרדת בשביל אדם יחיד.',
'9b:2:2': 'הדרשה מפרטת כל מילה בפסוק. ״יכול לכל״ — היינו חושבים שה׳ נותן מטר רק כשכל העולם צריך אותו (רש״י: ״יכול אין נותן מטר אא״כ הכל צריכין לו״). לכן כתוב ״לאיש״: אפילו בשביל אדם אחד.',
'9b:2:3': 'המשך הדרשה: אם ״לאיש״, אולי הגשם יורד רק כשכל השדות של אותו אדם צריכים מים (רש״י: ״אינו יורד עד שהוא צריך לכל שדותיו״). לכן כתוב ״שדה״ — אפילו בשביל שדה אחת שלו.',
'9b:2:4': 'והשלב האחרון: אם ״שדה״, אולי הגשם יורד רק כשכל השדה צריכה מים. לכן כתוב ״עשב״ — אפילו בשביל עשב אחד או ירק אחד (רש״י). תוספות: אם צריך רק לעשב אחד, הגשם יורד על אותו עשב, ולא על שאר השדה.',
'9b:3:0': 'מעשה שמראה את הדרשה ״לאיש עשב בשדה״. לרב דניאל בר קטינא הייתה גינה, וכל יום היה הולך ו״סייר״ אותה — עובר ובודק (רש״י: ״וסייר — מעיין״).',
'9b:3:1': 'בכל סיור הוא אמר על כל ערוגה (״מישרא״, רש״י: ערוגה) אם היא צריכה מים או לא. כלומר, הוא ידע בדיוק מה כל חלק בגינה צריך.',
'9b:3:2': 'והנס: ירד גשם, והשקה בדיוק את המקומות שרב דניאל אמר שצריכים מים. זה מה שהברייתא אמרה — ה׳ מוריד גשם אפילו ל״עשב״ אחד, ורק היכן שצריך.',
'9b:4:0': 'הגמרא חוזרת לפסוק של ריש לקיש, ״שאלו מה׳ מטר... ה׳ עושה חזיזים״, ושואלת: למה ״חזיזים״ בלשון רבים? (רש״י: ״ברישא בעי מאי חזיזים לשון רבים״).',
'9b:4:1': 'ר׳ יוסי בר חנינא: ״חזיזים״ ברבים, כי לכל צדיק וצדיק ה׳ עושה ״חזיז״ משלו. רש״י: לכל צדיק בעולם — כדי להוריד לו גשמים על שדותיו. זה ממשיך את הרעיון שמטר יורד גם בשביל יחיד.',
'9b:4:2': 'עכשיו הגמרא שואלת שאלה אחרת: לא למה ברבים, אלא מה הדבר עצמו שנקרא ״חזיז״ (רש״י: ״והדר בעי ומאי ניהו חזיזים״).',
'9b:4:3': 'רב יהודה עונה: חזיזים הם ״פורחות״ — סוג של עננים. מיד יסבירו מה הם.',
'9b:4:4': 'ר׳ יוחנן מוסיף: ה״פורחות״ הן סימן שגשם עומד לרדת. כך מתאים הפסוק: ״ה׳ עושה חזיזים, ומטר גשם יתן להם״ — קודם החזיזים, ואחריהם הגשם.',
'9b:4:5': 'הגמרא שואלת עוד: מה זה ״פורחות״ שרב יהודה ור׳ יוחנן הזכירו?',
'9b:4:6': 'רב פפא מסביר: ״פורחות״ הן ענן דק שנמצא מתחת לענן עבה — קרוב יותר לארץ (רש״י: ״דתותי עיבא — כלפי הארץ״). המראה הזה הוא סימן שגשם בדרך.',
'9b:5:0': 'רב יהודה נותן סימן נוסף. ״נהילא״ הוא גשם דק מאוד (רש״י: כמו ״קיטמא נהילא״ — אבק דק). אם הגשם הדק בא לפני הגשם, סימן שיבוא גשם רב שלא ייפסק מהר (רש״י: ״גשמים יורדין לרוב ואין פוסקין מהר״).',
'9b:5:1': 'ההפך: אם הגשם הדק בא אחרי הגשם הרגיל, זה סימן שהגשם עומד להיפסק (רש״י: ״אבל בא מטר תחילה ומתחילין דקין לבא — פוסקין מיד״).',
'9b:5:2': 'כדי לזכור, רב יהודה נותן סימן: ״מהולתא״ — נפה. כשמנפים קמח, קודם יוצא הקמח הדק, ובסוף נשארת הסובין הגסה (רש״י). כך גם כאן: קודם הדק, ואחר כך הגשם הרב. (בתוספות מובא פירוש הפוך, לפי דרך הניפוי של אז.)',
'9b:5:3': 'והסימן השני: ״חריא דעיזי״ — צואת עזים. בהתחלה היא יוצאת גסה, ובסוף דקה ונפסקת (רש״י, ותוספות). כך גם הגשם: אחרי הגשם הרב בא הדק, ואז הוא נפסק.',
'9b:6:0': 'עולא היה מארץ ישראל. כשהגיע לבבל ראה ״פורחות״ — הסימן למטר שר׳ יוחנן אמר. לכן אמר לאנשים לפנות את הכלים מבחוץ, כי עוד מעט יבוא גשם.',
'9b:6:1': 'אבל הגשם לא בא. הסימן שעובד בארץ ישראל לא התקיים בבבל.',
'9b:6:2': 'עולא אמר בחיוך: כמו שאנשי בבל ״משקרים״, כך גם הגשמים שלהם ״משקרים״ — מראים סימן ולא באים. זה חלק ממסורת של עולא, שהיה אוהב להשוות בין ארץ ישראל לבבל.',
'9b:7:0': 'מעשה נוסף בעולא בבבל. הוא ראה שמוכרים סל מלא תמרים בזוז אחד בלבד — זול מאוד.',
'9b:7:1': 'עולא אמר: סל מלא ״דבש״ (רש״י: תמרים, שעושים מהם דבש) בזוז — האוכל כאן כל כך זול, ובכל זאת אנשי בבל לא עוסקים בתורה? רש״י: יש להם מזונות בזול ובלי טורח, ויכולים ללמוד תמיד.',
'9b:7:2': 'אבל בלילה התמרים ״ציערו״ את עולא: הוא אכל מהן הרבה, וקיבל שלשול וכאבי בטן (רש״י: ״מצערים בשלשול״, כמו שאמרו בגיטין ע.).',
'9b:7:3': 'אחרי הלילה, עולא שינה את דבריו: זה לא סל ״דבש״ אלא סל ״סכינים״ בזוז — כי מי שאוכל הרבה תמרים סובל. ובכל זאת, אנשי בבל עוסקים בתורה. כך הוא שיבח אותם.',
'9b:8:0': 'ברייתא חדשה, על השאלה מאיפה בא הגשם. ר׳ אליעזר: כל העולם ״שותה״ ממי האוקיינוס — מים של מטה, לא של מעלה (רש״י). הראיה: ״ואד יעלה מן הארץ והשקה את כל פני האדמה״ — המים עולים מהארץ (מהים) ומשקים.',
'9b:8:1': 'ר׳ יהושע מקשה על ר׳ אליעזר: מי הים מלוחים, ותבואה לא גדלה ממים מלוחים (רש״י). איך הגשם, שמצמיח את הכל, יכול לבוא מהם?',
'9b:8:2': 'ר׳ אליעזר עונה: נכון שהם מלוחים, אבל כשהם עולים לעננים הם ״מתמתקים״ — הופכים למים מתוקים. (כך גם כתוב בפירוש שבשולי הדף: ״ואע״פ שמלוחין, מתמתקין הם בעבים״.)',
'9b:8:3': 'ר׳ יהושע חולק: העולם שותה מ״המים העליונים״ — מים שבשמים, לא מהים. הראיה: על ארץ ישראל כתוב ״למטר השמים תשתה מים״ — המים באים מהשמים.',
'9b:9:0': 'אם הגשם בא מלמעלה, כמו ר׳ יהושע, איך מסבירים את הפסוק של ר׳ אליעזר ״ואד יעלה מן הארץ״, שמשמע שהמים עולים מלמטה?',
'9b:9:1': 'ר׳ יהושע מסביר: ״ואד יעלה מן הארץ״ מדבר על העננים — הם עולים מהארץ לרקיע. שם הם פותחים את ״פיהם״ כמו נאד, ומקבלים את מי המטר מהמים העליונים. הראיה: ״יזקו מטר לאדו״ — הרקיעים יוצקים מים לעננים (רש״י).',
'9b:9:2': 'ואיך הגשם יורד? העננים מנוקבים כמו כברה (מסננת), והם ״מחשרים״ — משירים — את המים טיפה טיפה על האדמה (רש״י: ״מחשרין, כלומר משירין המים לארץ״). הראיה: ״חשרת מים עבי שחקים״.',
'9b:9:3': 'ועוד: בין כל טיפה לטיפה יש רק מרחק של חוט שערה. ובכל זאת הטיפות לא מתערבבות — כל אחת יורדת במקומה. זה נס גדול, ולכן הגמרא מיד אומרת ״ללמדך שגדול יום הגשמים״.',
'9b:10:0': 'רש״י: ״ללמדך — אקרא דלקמן קאי״ — המשפט הזה מתחבר לפסוקים שבאים אחריו. הנס של הטיפות מלמד שיום הגשמים גדול כיום בריאת העולם. דומה לזה ראינו בדף ז. ובח:, כשהגמרא שיבחה את יום הגשמים.',
'9b:10:1': 'הראיה: באיוב כתוב ״עושה גדולות עד אין חקר״, ומיד אחר כך ״הנותן מטר על פני ארץ״ — אז ה״גדולות עד אין חקר״ מדברות על הגשם. כבר בדף ב. ראינו את הפסוק הזה, כשר׳ יוחנן הסביר ״גבורות גשמים״.',
'9b:10:2': 'ובישעיה, על בריאת העולם (״בורא קצות הארץ״), כתוב ״אין חקר לתבונתו״. ״אין חקר״ נאמר על הגשם ונאמר על הבריאה — לכן יום הגשמים שקול כיום שנבראו שמים וארץ. (רש״י: את ״ואומר מכין הרים״ אין לגרוס כאן.)',
'9b:11:0': 'הגמרא שואלת: הפסוק בתהלים ״משקה הרים מעליותיו״ — ור׳ יוחנן פירש: מהעליות של הקב״ה, כלומר מהמים העליונים (רש״י). לפי מי מבין התנאים זה מתאים?',
'9b:11:1': 'התשובה הפשוטה: כר׳ יהושע, שאמר שהעולם שותה מהמים העליונים. תוספות: ״דאי כרבי אליעזר, הא אמר מימי אוקיינוס הוא שותה״.',
'9b:11:2': 'גם ר׳ אליעזר יכול להסביר את הפסוק: נכון שהמים באים מהים, אבל הם עולים לשמים לפני שהם יורדים. לכן הפסוק קורא להם ״מעליותיו״ — על שם המקום שאליו עלו.',
'9b:11:3': 'הראיה לר׳ אליעזר: בתורה כתוב (בקללות) ״אבק ועפר מן השמים יֵרד עליך״. והרי אבק ועפר באים מהאדמה, לא מהשמים! איך יתכן שכתוב ״מן השמים״?',
'9b:11:4': 'התשובה: האבק עולה לשמים ברוח, ולכן קוראים לו ״מן השמים״. אותו דבר עם מי הים של ר׳ אליעזר: הם עולים לשם, ולכן קוראים להם ״מעליותיו״. כך גם ר׳ אליעזר מסתדר עם הפסוק.',
'9b:12:0': 'ר׳ חנינא דורש את הפסוק בתהלים ״כונס כנד מי הים, נותן באוצרות תהומות״: מי גרם לאוצרות (מחסני התבואה) להתמלא ״בר״ (תבואה)? התהומות — המים של מטה (רש״י: ״תהומות — מים של מטה, כדכתיב תהומות יכסיומו״). לפי מי זה מתאים?',
'9b:12:1': 'התשובה: כר׳ אליעזר, שאמר שהעולם שותה ממי האוקיינוס. לפיו, מי התהומות הם שמשקים את התבואה וממלאים את המחסנים.',
'9b:12:2': 'ור׳ יהושע? הוא יאמר שהפסוק ״כונס כנד מי הים״ מדבר על מעשה בראשית — כשה׳ כנס את מי הים למקומם בבריאת העולם — ולא על הגשם בכל שנה. כך שתי השיטות מסתדרות עם הפסוקים.',
'9b:13:0': 'ריש לקיש, כמו ר׳ יוחנן בדף ט., סובר שמטר יורד בשביל יחיד. הברייתא מדייקת מכל מילה בפסוק: ״לאיש״, ״שדה״, ״עשב״. ומעשה רב דניאל בר קטינא מראה את זה בפועל: הגשם השקה רק את הערוגות שהיו צריכות.',
'9b:13:1': 'פורחות — ענן דק תחת ענן עבה — סימן למטר. גשם דק לפני הגשם — יבוא גשם רב (מהולתא); אחרי הגשם — הגשם נפסק (חריא דעיזי). ובבבל, לפי עולא, הסימנים ״משקרים״.',
'9b:13:2': 'ר׳ אליעזר: מהאוקיינוס, והמים מתמתקים בעננים. ר׳ יהושע: מהמים העליונים, והעננים עולים ומקבלים אותם, ומטפטפים ככברה. ״משקה הרים מעליותיו״ — כר׳ יהושע; ״כונס כנד מי הים״ — כר׳ אליעזר.',
'9a:0:0': 'בסוף דף ח: ר׳ יוחנן שאל ״מאי דכתיב עשר תעשר?״. התשובה כאן: הפסוק כופל את המילה ״עשר״ כדי לרמוז ״עשר בשביל שתתעשר״ — תן מעשר, ובזכות זה תהיה עשיר. המילים ״עשר״ ו״עושר״ דומות, והתורה מחברת ביניהן.',
'9a:0:1': 'מעשה שמראה את הדרשה הזו. ר׳ יוחנן פגש את בנו הקטן של ריש לקיש (רש״י: ריש לקיש היה נשוי לאחותו של ר׳ יוחנן, וזה היה אחרי שריש לקיש נפטר). כדרכם, ביקש מהילד לומר את הפסוק שלמד היום בבית הספר.',
'9a:0:2': 'הילד ענה שהפסוק שלו הוא ״עשר תעשר״ — בדיוק הפסוק שהגמרא דורשת עכשיו.',
'9a:0:3': 'ר׳ יוחנן בודק אם הילד מבין מה שהוא לומד: למה כתוב ״עשר״ פעמיים?',
'9a:0:4': 'הילד מסביר את הכפילות: ״עשר בשביל שתתעשר״. נותנים מעשר, וה׳ מעשיר את מי שנותן.',
'9a:0:5': 'ר׳ יוחנן שואל מניין הילד יודע שהמעשר באמת מעשיר. הוא רוצה לשמוע מקור.',
'9a:0:6': 'הילד עונה בפשטות: ״לך ותנסה״ — תן מעשר ותראה שאתה מתעשר. מכאן הדיון הבא: האם מותר בכלל לנסות את ה׳?',
'9a:1:0': 'הילד אמר ״זיל נסי״, ור׳ יוחנן מקשה: וכי מותר לנסות את הקב״ה? הרי בתורה כתוב ״לא תנסו את ה׳ אלהיכם״. אסור לעשות מצוה כדי ״לבדוק״ אם ה׳ ישלם.',
'9a:1:1': 'הילד עונה בשם ר׳ הושעיא, שהיה הרב שלו (רש״י): נכון שאסור לנסות את ה׳, אבל יש יוצא מן הכלל אחד — מעשר. במעשר מותר לנסות.',
'9a:1:2': 'המקור של ר׳ הושעיא: הנביא מלאכי. ה׳ אומר ״הביאו את כל המעשר... ובחנוני נא בזאת״ — תבחנו אותי בזה, ותראו שאפתח לכם את חלונות השמים ואשפוך ברכה. כאן ה׳ בעצמו מזמין ניסיון, ולכן במעשר מותר.',
'9a:1:3': 'הגמרא עוצרת לשאול על סוף הפסוק במלאכי: ״והריקותי לכם ברכה עד בלי די״. מה זה ״עד בלי די״?',
'9a:1:4': 'רמי בר חמא בשם רב: ״בלי״ מלשון ״בלוי״. הברכה תהיה כל כך גדולה, שהשפתיים שלכם ״יתבלו״ מרוב אמירת ״די, די״ — ועדיין היא תמשיך.',
'9a:1:5': 'ר׳ יוחנן מודה לילד: אילו הייתי מגיע בעצמי לפסוק ״ובחנוני נא בזאת״ (במלאכי), הייתי יודע את זה לבד, ולא הייתי צריך ללמוד את זה ממך ומר׳ הושעיא רבך (רש״י). כלומר — התשובה נכונה, והפסוק מפורש.',
'9a:2:0': 'מעשה שני עם אותו ילד. הוא ישב ואמר את הפסוק במשלי: ״אולת אדם תסלף דרכו ועל ה׳ יזעף לבו״. רש״י: אדם חוטא, ובגלל זה פוגעים בו צרות, ואז הוא כועס על ה׳ ושואל ״למה זה קרה לי?״.',
'9a:2:1': 'ר׳ יוחנן ישב ותמה. הכלל אצלו: כל מה שכתוב בנביאים ובכתובים יש לו רמז או ״סמך״ בתורה (רש״י: ״התורה היא יסוד הנביאים והכתובים״). איפה בתורה רמוז ״אולת אדם... ועל ה׳ יזעף לבו״?',
'9a:2:2': 'הילד מראה את הרמז בתורה: אחי יוסף מצאו את הכסף באמתחות, ואמרו בפחד ״מה זאת עשה אלהים לנו״. הם עצמם גרמו לצרה (כשמכרו את יוסף), ובכל זאת שאלו ״מה עשה לנו אלהים״ — בדיוק ״אולת אדם תסלף דרכו ועל ה׳ יזעף לבו״.',
'9a:2:3': 'ר׳ יוחנן היה זקן מאוד, וגבות עיניו כיסו את עיניו, והיו מרימים אותן במכחול של כסף (רש״י, מבבא קמא קיז.). הוא הרים את עיניו כדי לראות את הילד, מתוך התפעלות מחכמתו.',
'9a:2:4': 'אמו של הילד (אחותו של ר׳ יוחנן) באה והוציאה אותו. היא חששה: מבטו של ר׳ יוחנן היה חזק מאוד, ולפי רש״י ריש לקיש נפטר אחרי שר׳ יוחנן נתן בו את עיניו (בבא מציעא פד.). היא לא רצתה שיקרה כך גם לבן.',
'9a:3:0': 'אחרי המעשים עם הילד, הגמרא חוזרת לגשמים, ומביאה עוד מימרא של ר׳ יוחנן. רש״י: ״מטר בשביל יחיד״ — ה׳ מוריד גשם אפילו בשביל אדם אחד, למשל מי שזרע אחרי כולם וצריך גשם לשדה שלו. אבל ״פרנסה״ — שפע ושובע לכל העולם — לא באה בזכות אחד, רק בזכות רבים.',
'9a:3:1': 'הראיה למטר בשביל יחיד: בתורה כתוב ״יפתח ה׳ לך את אוצרו הטוב את השמים לתת מטר ארצך״ — ״לך״ ו״ארצך״, בלשון יחיד. ה׳ פותח את השמים אפילו בשביל אחד.',
'9a:3:2': 'והראיה לפרנסה בשביל רבים: על המן כתוב ״הנני ממטיר לכם לחם מן השמים״ — ״לכם״, בלשון רבים. רש״י: ״ממטיר לכם — לשון רבים״. מיד יקשו על זה מברייתא שבה המן בא בזכות אדם אחד — משה.',
'9a:4:0': 'ר׳ יוחנן אמר ש״פרנסה״ באה רק בזכות רבים. מקשים עליו (״מיתיבי״) מברייתא של ר׳ יוסי ברבי יהודה: שלושה ״פרנסים״ — מנהיגים שדאגו לכל צורכי העם — עמדו לישראל במדבר: משה, אהרן ומרים. הקושיה תתברר בסוף: המן בא בזכות משה לבדו.',
'9a:4:1': 'בזכות שלושת הפרנסים קיבלו ישראל במדבר שלוש מתנות: באר שנתנה מים, ענני הכבוד שהגנו עליהם, והמן שהיה לחמם. אלה כל צורכי החיים במדבר: מים, הגנה ומזון.',
'9a:4:2': 'כל מתנה בזכות אחד מהם. הבאר בזכות מרים: רש״י — ״בארה של מרים״ הוא סלע שהיה מתגלגל והולך עם ישראל ונותן מים. עמוד הענן בזכות אהרן, והמן בזכות משה רבינו. כאן כבר רואים את הקושיה: המן — פרנסה לכל ישראל — בזכות יחיד.',
'9a:5:0': 'הברייתא מוכיחה שכל מתנה תלויה בזכות של אחד: כשנפטרה מרים, הבאר נעלמה. בתורה כתוב ״ותמת שם מרים ותקבר שם״, ומיד אחר כך ״ולא היה מים לעדה״ — הסמיכות מלמדת שהמים היו בזכותה.',
'9a:5:1': 'אבל הבאר לא נעלמה לגמרי: היא חזרה בזכות שני האחים, משה ואהרן. רש״י: שכן כתוב (במדבר כ) ״ודברתם אל הסלע ונתן מימיו״ — לשון רבים, שניהם.',
'9a:6:0': 'המתנה השנייה: כשנפטר אהרן הכהן, נעלמו ענני הכבוד שהקיפו את ישראל. הראיה מהפסוק שבא אחרי פטירת אהרן: ״וישמע הכנעני מלך ערד... וילחם בישראל״.',
'9a:6:1': 'הפסוק אומר ״וישמע״ ולא אומר מה שמע. הברייתא שואלת: איזו ידיעה הגיעה אליו, שבגללה יצא למלחמה?',
'9a:6:2': 'מלך ערד שמע שאהרן נפטר ושהעננים שהגנו על ישראל נעלמו. הוא חשב שעכשיו ישראל בלי הגנה, ו״ניתנה לו רשות״ להלחם בהם. מכאן שהעננים היו בזכות אהרן.',
'9a:6:3': 'הברייתא מוסיפה: וזה הפירוש של הפסוק ״ויראו כל העדה כי גוע אהרן״. מיד ר׳ אבהו יסביר איך הפסוק הזה קשור לענני הכבוד.',
'9a:7:0': 'ר׳ אבהו מסביר את הקשר: במקום ״ויראו״ (מלשון ראייה) קוראים ״וייראו״ (מלשון יראה ופחד). כל העדה פחדו — כי ראו שהעננים נעלמו ושמלך ערד בא להלחם בהם.',
'9a:7:1': 'הדרשה נשענת על כלל של ריש לקיש: למילה ״כי״ יש ארבע משמעויות — ״אי״ (אם), ״דלמא״ (שמא), ״אלא״, ו״דהא״ (שהרי). כאן ״כי״ = ״דהא״: ״וייראו כל העדה — דהא גוע אהרן״, הם פחדו כי אהרן נפטר. רש״י: ר״ל לא בא לומר ש״כי״ הוא דווקא אחת מהן, אלא שבכל מקום אפשר לדרוש לפי העניין.',
'9a:8:0': 'הברייתא ממשיכה: אחרי שנפטרו מרים ואהרן, הבאר והענן חזרו — ושניהם בזכות משה רבינו. עכשיו כל שלוש המתנות היו בזכותו.',
'9a:8:1': 'כשנפטר משה רבינו, נעלמו כל שלוש המתנות. הראיה מזכריה: ״ואכחיד את שלשת הרועים בירח אחד״. רש״י: ״שלשת הרועים״ הם משה, אהרן ומרים, כי לא מצאנו שלושה פרנסים כאחד לישראל חוץ מהם.',
'9a:8:2': 'הברייתא מקשה על הפסוק: ״בירח אחד״? הרי הם נפטרו בשלושה חודשים שונים — מרים בניסן (רש״י: ״ויבאו... בחדש הראשון... ותמת שם מרים״), אהרן באחד לחודש החמישי, אב, ומשה בשבעה באדר.',
'9a:8:3': 'התשובה: ״ואכחיד את שלשת הרועים״ לא מדבר על הפטירות, אלא על המתנות. בחודש אדר, כשנפטר משה, נעלמו כל שלוש המתנות שניתנו על ידי שלושתם — באר, ענן ומן. וזה ״בירח אחד״.',
'9a:9:0': 'זו הקושיה על ר׳ יוחנן. הברייתא אמרה ״מן בזכות משה״, ומשה הוא יחיד. אז מצאנו פרנסה לכל ישראל בזכות יחיד — ור׳ יוחנן אמר ״פרנסה בשביל רבים״.',
'9a:9:1': 'התירוץ: משה רבינו שונה מסתם יחיד. הוא לא ביקש לעצמו — הוא ביקש פרנסה בשביל כל העם. מי שמבקש בשביל הרבים נחשב כרבים, ולכן אין זו סתירה לר׳ יוחנן. רש״י בסוף הדף: ״שאני משה רבינו, כיון דאלים וזכותיה כרבים דמי״.',
'9a:10:0': 'מעשה חדש (שקשור לסוף, כשיגיעו ל״פרנסה״ שנתנה בזכות רב פפא). שלושה חכמים — רב הונא בר מנוח, רב שמואל בר אידי, ורב חייא ממווסתניא (רש״י: שם מקום) — היו לומדים תמיד לפני רבא.',
'9a:10:1': 'כשרבא נפטר (״נח נפשיה״ — נחה נפשו), שלושת התלמידים עברו ללמוד אצל רב פפא, שהיה תלמידו של רבא.',
'9a:10:2': 'בכל פעם שרב פפא אמר להם שמועה, והיא לא התיישבה להם, הם ״רמזו זה לזה״. רש״י: ״מראין ומביטין זה לזה, דלא סלקא להו שמעתא כרבא״ — כאילו אומרים: אצל רבא זה היה אחרת.',
'9a:10:3': 'רב פפא ראה את הרמיזות ונפגע — ״חלש דעתיה״. בדף ט: נראה מה קרה בעקבות זה (״אקרויה בחלמיה...״), ואיך זה קשור לגשם ולפרנסה בשביל יחיד.',
'9a:11:0': 'הילד, בנו של ריש לקיש, למד ״עשר בשביל שתתעשר״. ר׳ יוחנן הקשה מ״לא תנסו את ה׳״, והילד ענה בשם ר׳ הושעיא: חוץ ממעשר, שבו ה׳ אומר במלאכי ״ובחנוני נא בזאת״. והברכה — ״עד בלי די״, עד שיתבלו השפתיים מלומר די.',
'9a:11:1': 'ר׳ יוחנן תמה על פסוק במשלי שאין לו רמז בתורה, והילד הראה את אחי יוסף: הם גרמו לצרה בעצמם, ושאלו ״מה זאת עשה אלהים לנו״. מכאן שהתורה היא היסוד לכל הנביאים והכתובים.',
'9a:11:2': 'ר׳ יוחנן: ״לך״ — מטר ליחיד; ״לכם״ — פרנסה לרבים. הברייתא של שלשת הפרנסים הראתה שהמן בא בזכות משה לבדו, ותירצו: משה ביקש בשביל כולם, ולכן ״כרבים דמי״.',
'8b:0:0': 'זה המשך הדברים שריש לקיש אמר בשם בר קפרא בסוף דף ח.. המילה ״עצירה״ מופיעה באשה: כשבית אבימלך לא ילדו, ״כי עצור עצר ה׳ בעד כל רחם״. ומופיעה בגשמים: ״ועצר את השמים ולא יהיה מטר״. אותה מילה מראה שהגשם דומה ללידה.',
'8b:0:1': 'המילה השנייה: ״לידה״. באשה: ״ותהר ותלד בן״. ובגשמים, בישעיה: הגשם יורד ״והרוה את הארץ והולידה והצמיחה״. הגשם ״מוליד״ את הצמחים, כמו אם שמולידה ילד.',
'8b:0:2': 'המילה השלישית: ״פקידה״. ה׳ ״פקד את שרה״ ונתן לה את יצחק. ובתהלים: ״פקדת הארץ ותשקקה״, ה׳ ״פוקד״ את הארץ ומשקה אותה. בסוף הפסוק יש ביטוי קשה, ״פלג אלהים מלא מים״, והגמרא מיד שואלת עליו.',
'8b:1:0': 'הגמרא שואלת על סוף הפסוק בתהלים: מה פירוש ״פלג אלהים מלא מים״? מה זה ה״פלג״ של ה׳ שמלא במים?',
'8b:1:1': 'התשובה מברייתא: ברקיע יש מעין ״קובה״, כיפה או חדר מקומר, והגשמים יוצאים ממנה. זה ה״פלג״, המקור של ה׳ שמלא במים ומשם יורד הגשם לארץ.',
'8b:2:0': 'הפסוק באיוב מדבר על העננים, שה׳ ״ממציא״ אותם פעם ״לשבט״, פעם ״לארצו״ ופעם ״לחסד״. ר׳ שמואל בר נחמני מסביר מה כל אחד מהם.',
'8b:2:1': 'הפירוש הראשון: ״לשבט״, כשה׳ מעניש, הגשם יורד על ההרים והגבעות, במקום שאין בו שדות ולא מועיל. ״לחסד... לארצו״: הגשם יורד דווקא על השדות והכרמים, שם צריכים אותו.',
'8b:2:2': 'פירוש שני של אותו פסוק: ״לשבט״ זה גשם שמועיל רק לעצים ולא לתבואה. ״לארצו״ זה גשם שמועיל לזרעים, לתבואה. ו״לחסד״ זה הכי טוב: גשם רב שממלא גם את הבורות, השיחין והמערות, ויש מים לשתייה כל השנה.',
'8b:3:0': 'מעשה בימי ר׳ שמואל בר נחמני, אותו אמורא שדרש ״אם לשבט אם לארצו״. באו שתי צרות יחד: ״כפנא״, רעב, ו״מותנא״, מגפה שבה אנשים נפטרים, רחמנא ליצלן.',
'8b:3:1': 'השאלה: על מה להתפלל? הם הבינו שאי אפשר לבקש רחמים על שתי צרות ביחד, ולכן צריך לבחור אחת. (מיד הגמרא תסביר מניין יודעים שאי אפשר.)',
'8b:3:2': 'ההצעה הייתה להתפלל על המגפה, כי היא הורגת מהר, ואת הרעב לסבול. נשמע הגיוני: עדיף להיות רעב מאשר שאנשים ייפטרו במגפה.',
'8b:3:3': 'ר׳ שמואל בר נחמני אומר להפך: נתפלל על הרעב. כשה׳ נותן שובע, הוא נותן אותו לחיים, כלומר לאנשים שחיים. לכן אם ה׳ יענה על התפילה ויביא שובע, ממילא גם המגפה תיעצר. כך תפילה אחת פותרת את שתי הצרות.',
'8b:3:4': 'הראיה: ״פותח את ידך ומשביע לכל חי רצון״. ה׳ משביע את ״כל חי״, כלומר השובע ניתן לחיים. מי שמקבל שובע מה׳, מקבל גם חיים.',
'8b:4:0': 'הגמרא שואלת על מה שאמרו בימי ר׳ שמואל בר נחמני: מאיפה יודעים שלא מבקשים רחמים על שתי צרות בבת אחת?',
'8b:4:1': 'הראיה מעזרא: ״ונצומה ונבקשה מאלהינו על זאת״. ״על זאת״ משמע על הדבר הזה דווקא. מכאן ש״איכא אחריתי״, היו עוד צרות, ובכל זאת התפללו רק על אחת.',
'8b:4:2': 'בארץ ישראל (״במערבא״) לומדים בשם ר׳ חגי מפסוק בדניאל: דניאל וחבריו ביקשו רחמים ״על רזא דנא״, על הסוד הזה (חלום נבוכדנצר). שוב לשון שמשמעה דבר אחד, אף שהיו עוד בקשות.',
'8b:5:0': 'מעשה: בימי ר׳ זירא השלטון גזר גזירה רעה על היהודים. וכדי שלא יתענו ויתפללו נגדה, גזרו גם שאסור לשבת בתענית.',
'8b:5:1': 'הפתרון של ר׳ זירא: נקבל עלינו את התענית עכשיו, בלב ובדיבור, ונתענה בפועל אחר כך, כשהגזירה תתבטל. כך עושים את מה שאפשר, בלי לעבור על הגזירה.',
'8b:5:2': 'שאלו את ר׳ זירא: מניין לך שקבלת תענית לבד, בלי לצום בפועל, מועילה?',
'8b:5:3': 'הראיה מדניאל: המלאך אמר לו ״מן היום הראשון אשר נתת את לבך להבין ולהתענות... נשמעו דבריך״. כבר מהיום שדניאל ״נתן את לבו להתענות״, כלומר קיבל עליו את התענית, דבריו נשמעו. מכאן שהקבלה עצמה פועלת.',
'8b:6:0': 'ר׳ יצחק אומר שגשם בערב שבת הוא סימן קללה, אפילו בשנים קשות כמו בימי אליהו הנביא, שלא ירד גשם שלוש שנים. רש״י מסביר: בערב שבת אנשים טרודים בהכנות לשבת והגשם מפריע להם.',
'8b:6:1': 'הגמרא מחברת למה שאמר רבה בר שילא: יום של גשם קשה כמו יום של דין. גם כשהגשם הוא ברכה, היום עצמו קשה לאנשים: קשה לצאת, לעבוד ולהתנייד.',
'8b:6:2': 'אמימר מוסיף: יום הגשם קשה כל כך, שאילולא העולם צריך את הגשם, היינו מבקשים רחמים שיתבטל. אבל כיוון שהעולם צריך אותו, לא מתפללים נגדו.',
'8b:7:0': 'עוד דבר של ר׳ יצחק, הפוך מהקודם: שמש בשבת היא ״צדקה לעניים״. רש״י: לעניים אין עצים להסקה ובגדים חמים, ושמש בשבת מחממת אותם.',
'8b:7:1': 'הראיה ממלאכי: ״וזרחה לכם יראי שמי שמש צדקה ומרפא״. השמש נקראת ״שמש צדקה״, וזו ״צדקה״ לעניים.',
'8b:7:2': 'עוד שבח ליום הגשמים: ביום הגשמים אפילו הפרוטה שבכיס מתברכת. הגשם מביא ברכה לא רק לשדות, אלא גם לפרנסה ולכסף.',
'8b:7:3': 'הראיה: ״לתת מטר ארצך בעתו, ולברך את כל מעשה ידך״. הגשם בא יחד עם ברכה לכל מעשה הידיים, גם לכסף שבכיס.',
'8b:8:0': 'ר׳ יצחק: ברכה נמצאת רק בדבר ״הסמוי מן העין״, במה שאינו גלוי ואינו נספר. הראיה: ״יצו ה׳ אתך את הברכה באסמיך״. ״אסמיך״ נדרש מלשון ״סמוי״, נסתר: האסם הוא מחסן סגור שלא רואים מה בתוכו.',
'8b:8:1': 'גם בבית המדרש של ר׳ ישמעאל לימדו כך, באותו פסוק: הברכה שורה בדבר ״שאין העין שולטת בו״. אולי הכוונה גם לעין הרע: מה שגלוי לעין, נפגע מהעין.',
'8b:8:2': 'ברייתא שמראה את הדין למעשה: מי שבא למדוד כמה תבואה יש לו בגורן, מתפלל לפני שמתחיל: ״יהי רצון... שתשלח ברכה במעשה ידינו״. עדיין לא מדד, הכמות עוד ״סמויה מן העין״, ולכן יש מקום לברכה.',
'8b:8:3': 'כשהתחיל למדוד, הוא אומר ״ברוך השולח ברכה בכרי הזה״. עדיין לא יודע את הכמות הסופית, ולכן אפשר עוד לבקש ולהודות על ברכה.',
'8b:8:4': 'אבל אם כבר מדד ורק אחר כך מבקש ברכה, זו ״תפלת שוא״, תפילה לשווא. ברגע שהכמות נשקלה, נמדדה או נספרה, היא ידועה, ואין בה מקום לברכה. הברכה שורה רק במה שעדיין ״סמוי מן העין״.',
'8b:9:0': 'הגמרא נותנת ״סימן״: רשימה קצרה של מילים שעוזרת לזכור את סדר הדברים הבאים, כי פעם לומדים בעל פה. ״קיבוץ״ = קיבוץ גלויות, ״גייסות״ = גייסות פוסקות, ״צדקה״ = פוסקי צדקה, ״פרנס״ = מימרה על פרנס בדף ט.',
'8b:9:1': 'ר׳ יוחנן מוסיף שבח ליום הגשמים: הוא גדול כמו יום קיבוץ גלויות, כשכל ישראל יחזרו לארצם. הראיה מתהלים: ״שובה ה׳ את שביתנו כאפיקים בנגב״, קיבוץ הגלויות מושווה ל״אפיקים״.',
'8b:9:2': 'ומניין ש״אפיקים״ זה גשם? מהפסוק ״ויראו אפיקי ים״ (בשירת דוד המלך), שם ״אפיקים״ הם מקורות המים. אם קיבוץ הגלויות נמשל לאפיקים, כלומר לגשם, הם שקולים.',
'8b:9:3': 'עוד שבח: ביום הגשמים אפילו ״גייסות״, חיילות שיוצאים לבזוז ולהילחם, ״פוסקות״, נעצרות. הראיה: ״תלמיה רוה, נחת גדודיה״: כשהתלמים רווים, ״גדודיה״ נחים. רש״י: הגשם עוצר את היציאה למלחמה.',
'8b:9:4': 'עוד סיבה לעצירת גשמים: אנשים שמבטיחים צדקה בפומבי, כדי שיכבדו אותם, ואחר כך לא נותנים. הראיה ממשלי: ״נשיאים ורוח וגשם אין, איש מתהלל במתת שקר״. יש עננים (״נשיאים״) ורוח, אבל גשם אין, בגלל מי ש״מתהלל במתת שקר״, מתפאר במתנה שלא נתן. מידה כנגד מידה: הבטחה בלי מעשה, ועננים בלי גשם.',
'8b:9:5': 'הדף נגמר כשר׳ יוחנן מתחיל לדרוש פסוק חדש. מילת הקישור בתחתית הדף, ״עשר״, מראה שזה ״עשר תעשר״ — עשר בשביל שתתעשר, והדרשה כולה בתחילת דף ט..',
'8b:10:0': 'שלוש מילים משותפות לאשה ולגשם: עצירה, לידה ופקידה. הארץ ״יולדת״ את הצמחים כשהגשם יורד, וכמו בלידה, ה׳ הוא שפוקד ופותח.',
'8b:10:1': 'מהמעשים בדף: לא מתפללים על שתי צרות יחד (״על זאת״). אם יש רעב ומגפה, מתפללים על הרעב, כי השובע מביא חיים. ואם גזרו שאסור להתענות, מקבלים את התענית ומתענים אחר כך, כי ״מן היום הראשון... נשמעו דבריך״.',
'8b:10:2': 'ר׳ יצחק והברייתא: ברכה שורה במה שעוד לא נמדד. לכן מתפללים לפני שמודדים את הגורן, ואחרי המדידה — תפילת שווא.',
'8a:0:0': 'זו הדרשה של ריש לקיש, שהתחילה בסוף דף ז: ״אם ראית תלמיד״. ר׳ אמי דרש ״אם קהה הברזל״ על רקיע, וריש לקיש דורש אותו על תלמיד: אם הלימוד קשה עליו ״כברזל״, הסיבה היא שהמשנה שלמד לא ״סדורה״ אצלו, הוא לא חזר עליה מספיק כדי שתהיה שגורה בפיו.',
'8a:0:1': 'הראיה מהמשך הפסוק: ״והוא לא פנים קלקל״. ריש לקיש קורא את ״קלקל״ מלשון ליטוש וסידור: התלמיד לא ״ליטש״ את פני המשנה, לא סידר אותה.',
'8a:0:2': 'הגמרא שואלת: אם הלימוד קשה לתלמיד בגלל שהמשנה לא סדורה אצלו, מה התיקון שלו?',
'8a:0:3': 'התשובה מהמשך הפסוק: ״וחילים יגבר״, יגביר כוחות. כלומר, ירבה לשבת בבית המדרש וללמוד, יחזור שוב ושוב על המשנה, עד שתהיה סדורה.',
'8a:0:4': 'סוף הפסוק: ״ויתרון הכשיר חכמה״. ריש לקיש דורש: יותר טוב מלהתאמץ אחר כך הוא שהמשנה תהיה סדורה כבר מההתחלה. מיד הגמרא מביאה איך ריש לקיש עצמו עשה את זה.',
'8a:1:0': 'דוגמה ל״משנתו סדורה לו מעיקרא״: ריש לקיש חזר על כל משנה ארבעים פעמים, כנגד ארבעים הימים שמשה היה בהר סיני כשניתנה התורה, ורק אז נכנס ללמוד לפני רבו ר׳ יוחנן. כך המשנה הייתה סדורה אצלו לגמרי.',
'8a:1:1': 'עוד דוגמה: רב אדא בר אהבה חזר על משנתו עשרים וארבע פעמים, כנגד עשרים וארבעה הספרים של תורה, נביאים וכתובים, ואז נכנס לפני רבא. שניהם מראים איך ״מסדרים״ משנה לפני שבאים לרב.',
'8a:2:0': 'רבא דורש את אותו פסוק אחרת מריש לקיש. לדעתו הלימוד קשה לתלמיד כי רבו ״אינו מסביר לו פנים״, כלומר כועס עליו ולא מסביר לו בסבר פנים יפות. ״לא פנים קלקל״ מתפרש על הפנים של הרב: הן ״מקולקלות״, זועפות כלפי התלמיד.',
'8a:2:1': 'שוב השאלה: אם הבעיה היא שהרב לא מסביר לו פנים, מה יעשה התלמיד?',
'8a:2:2': 'התשובה של רבא מאותו ״וחילים יגבר״: ירבה ״רעים״, חברים, שיבקשו מהרב עבורו ויפייסו אותו. ״חילים״ כאן הם החברים שמגבירים את כוחו.',
'8a:2:3': 'וסוף הפסוק: ״ויתרון הכשיר חכמה״. רבא דורש: עוד יותר טוב אם התלמיד יתנהג כראוי לפני רבו מלכתחילה, ואז הרב לא יכעס עליו בכלל. אותו מבנה כמו אצל ר׳ אמי וריש לקיש: ״כל שכן מעיקרא״.',
'8a:3:0': 'ר׳ אמי ממשיך לפסוק הבא בקהלת: ״אם ישוך הנחש בלא לחש, ואין יתרון לבעל הלשון״. בפשט: נחש שנושך כשאין מי שלוחש עליו לחש. ר׳ אמי דורש גם אותו על גשם.',
'8a:3:1': 'הדרשה: ״הנחש״ מתפרש מלשון ״נחושת״: השמים קשים כנחושת ולא מורידים טל ומטר. ו״בלא לחש״: כי אין בדור ״לוחשי לחישות״, אנשים שמתפללים בלחש ובכוונה. בלי תפילה, השמים ״נושכים״.',
'8a:3:2': 'הגמרא שואלת: אם אין בדור מי שיודע להתפלל, מה התיקון?',
'8a:3:3': 'התיקון: ילכו אל מי שיודע ״ללחוש״, להתפלל, ויבקשו שיתפלל עליהם. הראיה מאיוב: ״יגיד עליו רעו״, חברו מדבר בשבילו לפני ה׳.',
'8a:3:4': 'סוף הפסוק: ״ואין יתרון לבעל הלשון״. מי שיש לו ״לשון״, שיודע להתפלל ויכול להועיל, ולא מתפלל, אין לו שום תועלת מזה. זו גם ביקורת על מי שיכול לעזור לדור ולא עושה זאת.',
'8a:4:0': 'שאלה נוספת: ומה אם אדם התפלל, ״לחש״, ותפילתו לא נענתה? מה התיקון שלו?',
'8a:4:1': 'התשובה: ילך אל החסיד שבדור, והחסיד ירבה להתפלל עליו. הראיה, כמו בדף ז:, מ״ויצו עליה במפגיע״: ה׳ מצווה על הגשם בזכות ״מפגיע״, תפילה.',
'8a:4:2': 'הראיה ש״מפגיע״ הוא תפילה: בירמיה ה׳ אומר לנביא ״אל תתפלל בעד העם הזה, ואל תשא בעדם רנה ותפלה, ואל תפגע בי״. ״תפגע״ בא יחד עם ״תתפלל״, ולכן פגיעה היא תפילה.',
'8a:4:3': 'ומה אם התפלל והצליח, אבל ״מגים דעתו עליו״, התגאה שתפילתו נענתה? אז הוא ״מביא אף לעולם״, מעורר כעס של ה׳. הראיה מהמשך הפסוק באיוב: ״מקנה אף על עולה״, ה׳ ״מקנא אף״ על מי ש״עולה״, מתרומם בדעתו.',
'8a:4:4': 'רבא דורש אחרת את ״מקנה אף על עולה״: שני תלמידי חכמים שגרים באותה עיר ולא ״נוחים״ זה לזה, מתקוטטים בהלכה במקום ללמוד יחד, ״מתקנאין באף״: מעוררים כעס של ה׳, ״ומעלין אותו״, מעלים אותו כלפי מעלה. זה ההפך מ״שני תלמידי חכמים מחדדין זה את זה״ שבדף ז.',
'8a:5:0': 'ריש לקיש דורש את הפסוק ״אם ישוך הנחש בלא לחש, ואין יתרון לבעל הלשון״ בדרך אחרת לגמרי: על הנחש עצמו, ועל ״בעל הלשון״ שמדבר לשון הרע.',
'8a:5:1': 'משל: לעתיד לבוא כל החיות יתאספו אצל הנחש וישאלו אותו: האריה דורס כדי לאכול, הזאב טורף כדי לאכול, אבל אתה נושך ממית ולא אוכל את הטרף. מה ההנאה שלך מזה?',
'8a:5:2': 'הנחש עונה בסוף הפסוק: ״ואין יתרון לבעל הלשון״. כלומר: ומה מרוויח מי שמספר לשון הרע? גם הוא פוגע בלי שום תועלת לעצמו. אם אתם לא שואלים אותו, למה אתם שואלים אותי?',
'8a:6:0': 'ר׳ אמי מדבר עכשיו על התפילה עצמה: היא נשמעת רק כשאדם ״משים נפשו בכפו״, מוסר את עצמו לגמרי, והלב והידיים אחד. הראיה מאיכה: ״נשא לבבנו אל כפים״, הלב יחד עם הכפיים שנשאות לתפילה.',
'8a:6:1': 'הגמרא מקשה מדרשה של שמואל, שהעמיד מתורגמן (״אמורא״) ודרש ברבים: בתהלים כתוב שבני ישראל ״פיתו״ את ה׳ בפיהם, שיקרו בלשונם, ולבם לא היה נכון עמו. ובכל זאת, בפסוק הבא: ״והוא רחום יכפר עון״. אם כן, גם תפילה בלי לב שלם נענית, בניגוד לר׳ אמי.',
'8a:6:2': 'התירוץ: ר׳ אמי מדבר על יחיד שמתפלל: תפילתו נשמעת רק אם הוא ״משים נפשו בכפו״. ״ויפתוהו בפיהם״ מדבר על ציבור, כלל ישראל: תפילת הציבור נשמעת אפילו כשהלב לא שלם, כי ה׳ ״רחום יכפר עון״.',
'8a:7:0': 'ר׳ אמי אומר עוד: גשם יורד בזכות ״בעלי אמנה״, אנשים נאמנים ומאמינים. הראיה: ״אמת מארץ תצמח, וצדק משמים נשקף״. כשיש ״אמת״ בארץ, מהשמים יורד ״צדק״, ברכה וגשם.',
'8a:7:1': 'ר׳ אמי מוסיף: בוא וראה כמה גדולים בעלי אמונה, ולומדים את זה מהמעשה של ״חולדה ובור״. רש״י מספר: בחור הבטיח לנערה שישא אותה, והם בחרו חולדה ובור שהיו שם כעדים. הוא הפר את ההבטחה ונשא אחרת. שני בניו נפטרו, אחד מנשיכת חולדה ואחד בנפילה לבור. כשאשתו שמעה על כך, עזבה אותו, והוא חזר אל הנערה שחיכתה לו באמונה.',
'8a:7:2': 'הקל וחומר: הנערה האמינה בחולדה ובבור, עדים חסרי משמעות, ובכל זאת אמונתה התקיימה. אז מי שמאמין בקדוש ברוך הוא, על אחת כמה וכמה שאמונתו מביאה ישועה, וגם גשם.',
'8a:8:0': 'ר׳ יוחנן דורש אחרת את הפסוק שר׳ אמי הביא. ״המצדיק את עצמו מלמטה״: מי שמדקדק במעשיו ומחמיר עם עצמו (או, לפי פירוש אחר, מצדיק את עצמו בעיני אחרים). ״מצדיקין עליו הדין מלמעלה״: גם בשמים דנים אותו במדת הדין המדויקת. ״אמת מארץ תצמח״ (מלמטה), ״וצדק משמים נשקף״ (מלמעלה).',
'8a:8:1': 'ר׳ חייא בר אבין לומד את אותו רעיון מפסוק אחר בתהלים: ״וכיראתך עברתך״. לפי מידת היראה של האדם, כך מידת ״עברתך״, הדין המדויק שה׳ מנהיג איתו. מי שירא מאוד ומדקדק בעצמו, גם ה׳ מדקדק איתו.',
'8a:8:2': 'ריש לקיש מביא ראיה שלישית מישעיה: ״פגעת את שש ועושה צדק״. ה׳ ״פוגע״, דן בדיוק, את מי ששש ועושה צדק. כלומר, הצדיק שמדקדק בעצמו מקבל דין מדויק. הפסוק ממשיך ״בהם עולם ונושע״, ומכאן ריב״ל דורש.',
'8a:8:3': 'ריב״ל דורש את המשך אותו פסוק: ״פגעת את שש״ — ה׳ פוגע ביסורים במי ש״שש״, שמח בהם. ״בהם עולם ונושע״: בזכות אנשים כאלה, כל העולם נושע. מי שמקבל את היסורים בשמחה מביא ישועה לעולם.',
'8a:9:0': 'ריש לקיש דורש את הלשון ״ועצר את השמים״. כשהשמים נעצרים ולא מורידים גשם, הם דומים לאשה ״שמחבלת״, שיש לה צירי לידה, ״ואינה יולדת״. העננים ״מנסים״ להוריד גשם, אבל לא מצליחים. מיד מובא המקור למשל.',
'8a:9:1': 'הגמרא מחברת למה שריש לקיש אמר בשם בר קפרא: המילה ״עצירה״ נאמרה גם בגשמים (״ועצר את השמים״) וגם באשה (״כי עצור עצר ה׳ בעד כל רחם״). הדף נגמר באמצע: ״נאמרה...״, וההמשך, עם עוד דמיון בין גשם ללידה, בדף ח:.',
'8a:10:0': 'ר׳ אמי (בדף ז:), ריש לקיש ורבא דורשים את ״אם קהה הברזל והוא לא פנים קלקל, וחילים יגבר, ויתרון הכשיר חכמה״. לכל אחד ״ברזל״ אחר: רקיע, משנה, רב. לכל אחד תיקון: רחמים, ישיבה, רעים. וכולם אומרים: עדיף מלכתחילה.',
'8a:10:1': 'ר׳ אמי קורא ״לחש״ כתפילה בלחש: השמים כנחושת כשאין מתפללים. ריש לקיש קורא ״בעל הלשון״ כמספר לשון הרע: כמו הנחש, הוא פוגע בלי לקבל שום תועלת.',
'8a:10:2': 'בדף ז: נמנו החטאים שעוצרים גשם. כאן ר׳ אמי מדגיש מה מביא אותו: תפילה של מי שיודע להתפלל, בעלי אמונה, ואמת. ובסוף ריב״ל: מי ששמח ביסורים מביא ישועה לכל העולם.',
'7b:0:0': 'זו התשובה של ר׳ יהושע לקושיה של הקיסר מסוף דף ז.: ״והא איכא שפירי דגמירי״, הרי יש יפים שהם חכמים. ר׳ יהושע עונה: נכון, אבל אילו הם היו מכוערים, הם היו חכמים עוד יותר. היופי גורם לגאווה ומסיח את הדעת מהלימוד, וזה בדיוק מה שר׳ אושעיא אמר: התורה נשמרת במי שדעתו שפלה.',
'7b:0:1': 'פירוש נוסף למשל של ר׳ אושעיא על מים, יין וחלב (בדף ז.). מים, יין וחלב נפסלים רק ״בהיסח הדעת״: כשמשאירים אותם בלי השגחה, נכנס בהם משהו או שהם מתקלקלים. כך גם דברי תורה: הם נשכחים רק כשמפסיקים לחזור עליהם ולחשוב עליהם. מי ששומר על התורה בדעתו, היא לא נשכחת.',
'7b:1:0': 'עוד שבח ליום הגשמים, אחרי השבחים בדף ז. (גדול מתחיית המתים, כמתן תורה). ר׳ חמא בר׳ חנינא, אותו אמורא שדרש בדף ז. ״ברזל בברזל״, אומר שיום הגשמים גדול כמו היום שבו נבראו השמים והארץ. הוא מביא פסוק מישעיה.',
'7b:1:1': 'הפסוק בישעיה מתאר את השמים ״מרעיפים״, מורידים טיפות, ואת הארץ נפתחת ומצמיחה. ובסופו: ״אני ה׳ בראתיו״. הגמרא מיד מדייקת במילה האחרונה.',
'7b:1:2': 'הדיוק: הפסוק מזכיר שמים וארץ, ולכן היה צריך לכתוב ״בראתים״, בראתי אותם. אבל כתוב ״בראתיו״, בלשון יחיד. ר׳ חמא לומד מכאן שהיום שבו השמים מרעיפים והארץ מצמיחה, יום הגשמים, הוא כמו יום הבריאה עצמו.',
'7b:1:3': 'ר׳ אושעיא (שבדף ז. דרש על מים, יין וחלב) מוסיף שבח: ביום הגשמים אפילו ״ישועה״ פרה ורבה. כלומר, הגשם מביא איתו לא רק תבואה, אלא גם הצלחה וישועה שמתרבות.',
'7b:1:4': 'ר׳ אושעיא לומד מאותו פסוק שר׳ חמא הביא. ״תפתח ארץ ויפרו ישע״: כשהארץ נפתחת בזכות הגשם, הישועה ״פרה״, גדלה ומתרבה, כמו פרי.',
'7b:2:0': 'מכאן הגמרא עוברת לקשר בין גשם לחטא. ר׳ תנחום בר חנילאי אומר שגשם יורד רק אחרי שהעוונות של ישראל נמחלו. כלומר, הגשם הוא סימן לסליחה.',
'7b:2:1': 'הראיה: בתהלים, ״רצית ה׳ ארצך״, ה׳ מרצה את הארץ בגשם, בא יחד עם ״נשאת עון עמך, כסית כל חטאתם״. הארץ מקבלת גשם אחרי שהעוון נמחל.',
'7b:2:2': 'זעירי מהעיר דיהבת אומר לרבינא: אתם (בישיבה שלכם) מביאים ראיה מהפסוק בתהלים, ואנחנו לומדים את אותו דבר מתפילת שלמה בחנוכת המקדש: ״ואתה תשמע השמים וסלחת לחטאת עבדיך... ונתתה מטר על ארצך״. שם הסליחה באה לפני הגשם.',
'7b:2:3': 'הצד השני: ר׳ תנחום בן ר׳ חייא, מכפר עכו, אומר שהגשמים נעצרים רק כשישראל (בלשון נקייה: ״שונאיהן של ישראל״) נתחייבו ״כליה״, כיליון. כלומר, עצירת גשמים היא סימן לחטא חמור מאוד.',
'7b:2:4': 'הראיה מאיוב: ״ציה גם חום יגזלו מימי שלג, שאול חטאו״. היובש והחום לוקחים את המים, והפסוק מסמיך לזה את ״שאול״, הקבר, למי שחטאו. כלומר, עצירת הגשם קשורה לחיוב כליה.',
'7b:2:5': 'שוב זעירי אומר לרבינא שהם לומדים את הדין מפסוק אחר: בפרשה השנייה של קריאת שמע כתוב ״ועצר את השמים ולא יהיה מטר... ואבדתם מהרה״. עצירת הגשם באה יחד עם ״ואבדתם״, כיליון.',
'7b:3:0': 'מתחילה רשימה של חטאים שבגללם הגשמים נעצרים. רב חסדא אומר: בגלל שלא נותנים תרומות ומעשרות מהיבול. הוא מביא את אותו פסוק מאיוב שר׳ תנחום הביא.',
'7b:3:1': 'רב חסדא לומד מאותו פסוק באיוב, ״ציה גם חום יגזלו מימי שלג״, אבל מבין אותו אחרת: לא ״כליה״, אלא תרומות ומעשרות. הגמרא מיד שואלת איך הפסוק מראה את זה.',
'7b:3:2': 'הגמרא שואלת: בפסוק כתוב רק ״ציה גם חום יגזלו מימי שלג״. איך רואים בו שמדובר דווקא בתרומות ומעשרות?',
'7b:3:3': 'התשובה מבית המדרש של ר׳ ישמעאל: ״ציה גם חום״ רומז לקיץ, ימי החום, שבהם קוצרים ואוספים ושם צריך להפריש תרומות ומעשרות. מי שלא עשה את מה שנצטווה בקיץ, ״יגזלו״ ממנו את ״מימי שלג״, הגשמים, בחורף. מידה כנגד מידה.',
'7b:3:4': 'סיבה נוספת: ר׳ שמעון בן פזי אומר שהגשמים נעצרים בגלל אלה שמספרים לשון הרע. הוא מביא פסוק ממשלי.',
'7b:3:5': 'הפסוק במשלי: ״רוח צפון תחולל גשם״, רוח הצפון מבריחה את הגשם. ובסופו: ״ופנים נזעמים לשון סתר״. ר׳ שמעון דורש: הגשם נעצר, וה׳ ״זועם״, בגלל לשון סתר, כלומר לשון הרע שאומרים בסתר.',
'7b:4:0': 'עוד סיבה: רב סלא בשם רב המנונא אומר שהגשמים נעצרים בגלל ״עזי פנים״, אנשים חצופים שלא מתביישים לחטוא.',
'7b:4:1': 'הפסוק בירמיה: ״וימנעו רביבים ומלקוש לא היה״, הגשם נעצר. ומיד: ״ומצח אשה זונה היה לך״. ״מצח״ הוא סמל לעזות פנים, כמו אשה זונה שלא מתביישת. כלומר, הגשם נעצר בגלל החוצפה.',
'7b:4:2': 'עוד דבר של רב סלא בשם רב המנונא, מאותו פסוק: מי שיש לו עזות פנים, בסוף ייכשל בעבירה. החוצפה מסירה את הבושה ששומרת על האדם מלחטוא.',
'7b:4:3': 'הראיה מאותו פסוק: ״ומצח אשה זונה היה לך״. ה״מצח״, עזות הפנים, מוביל ל״זונה״, כלומר לעבירה.',
'7b:4:4': 'רב נחמן מחמיר יותר מרב המנונא. רב המנונא אמר ״סוף נכשל״, בעתיד. רב נחמן אומר שמי שיש לו עזות פנים, בוודאי כבר נכשל בעבירה. הראיה: בפסוק כתוב ״היה לך״, בלשון עבר, ולא ״יהיה לך״.',
'7b:4:5': 'רבה בר רב הונא מוסיף: את מי שיש לו עזות פנים מותר לכנות ״רשע״, למרות שבדרך כלל אסור לכנות אדם בשם גנאי. הראיה ממשלי: ״העז איש רשע בפניו״, מי שמעיז פנים הוא ״איש רשע״.',
'7b:4:6': 'רב נחמן בר יצחק אומר יותר: מותר לשנוא את מי שיש לו עזות פנים. הוא דורש פסוק בקהלת, ״ועז פניו ישונא״ (פירושו הפשוט: עוז פניו ישתנה), ומשנה את הקריאה: אל תקרא ״ישונא״ אלא ״ישנא״, יהיה שנוא.',
'7b:5:0': 'עוד סיבה: רב קטינא אומר שהגשמים נעצרים בגלל ״ביטול תורה״, כשישראל לא עוסקים בתורה.',
'7b:5:1': 'הפסוק בקהלת: ״בעצלתים ימך המקרה״. בפשט: מי שמתעצל לתקן את הבית, התקרה (״המקרה״) מתמוטטת. רב קטינא מיד דורש כל מילה בפסוק.',
'7b:5:2': 'הדרשה של רב קטינא: ״בעצלתים״, בגלל העצלות של ישראל שלא עסקו בתורה, ״ימך המקרה״. ״מך״ פירושו עני (כמו ״ואם מך הוא מערכך״). ו״המקרה״ הוא הקב״ה, ״המקרה במים עליותיו״, שהמים, הגשמים, הם תחת שליטתו. ״שונאו של הקב״ה״ הוא לשון נקייה: כביכול הקב״ה נעשה ״עני״, בלי גשם לתת לעולם.',
'7b:5:3': 'רב יוסף מסכים שהגשמים נעצרים בגלל ביטול תורה, אבל לומד את זה מפסוק אחר באיוב: ״ועתה לא ראו אור, בהיר הוא בשחקים, ורוח עברה ותטהרם״. ״בהיר״ פירושו שמים נקיים, בלי עננים וגשם. הגמרא מסבירה מיד מה ה״אור״.',
'7b:5:4': 'הדרשה: ״אור״ הוא תורה, כמו ״כי נר מצוה ותורה אור״. אז ״לא ראו אור״ פירושו שלא עסקו בתורה, ובגלל זה ״בהיר הוא בשחקים״: השמים בהירים ואין גשם.',
'7b:5:5': 'בית המדרש של ר׳ ישמעאל מפרש את סוף הפסוק: גם כשהרקיע כבר מלא ״בהורין״, כתמים של עננים שמוכנים להוריד טל ומטר, ״רוח עברה ותטהרם״: רוח באה, מנקה את השמים, ואין גשם. כך קורה כשלא עוסקים בתורה.',
'7b:6:0': 'הסיבה האחרונה ברשימה: ר׳ אמי אומר שהגשמים נעצרים בגלל עוון גזל, כשאנשים לוקחים מה שלא שלהם.',
'7b:6:1': 'ר׳ אמי מביא פסוק מאיוב: ״על כפים כסה אור״. הגמרא מיד מפרשת כל מילה בו.',
'7b:6:2': 'הדרשה: ״על כפים״ פירושו בגלל עוון הכפיים. ״כפים״ הם חמס, גזל, כמו בנינוה: ״ומן החמס אשר בכפיהם״. ו״אור״ הוא מטר, כמו ״יפיץ ענן אורו״, הענן מפזר את ה״אור״ שלו, את הגשם. כלומר: בגלל הגזל, ה׳ מכסה את הגשם.',
'7b:6:3': 'הגמרא שואלת: אם הגשם נעצר בגלל גזל, מה התיקון? מה אפשר לעשות כדי שהגשם ירד?',
'7b:6:4': 'התשובה: להרבות בתפילה. הראיה מהמשך אותו פסוק באיוב: ״ויצו עליה במפגיע״, ה׳ מצווה על הגשם לרדת בזכות ״מפגיע״. ו״פגיעה״ היא תפילה, כמו בירמיה: ״ואתה אל תתפלל בעד העם הזה... ואל תפגע בי״, שם ״תתפלל״ ו״תפגע״ באים יחד.',
'7b:7:0': 'ר׳ אמי ממשיך בעניין הגשם. בקהלת כתוב ״אם קהה הברזל והוא לא פנים קלקל, וחילים יגבר, ויתרון הכשיר חכמה״. בפשט מדובר בגרזן שהתקהה. ר׳ אמי דורש את זה על השמים.',
'7b:7:1': 'הדרשה: ״קהה הברזל״ הוא הרקיע, שהתקשה כמו ברזל ולא מוריד טל ומטר. ולמה? ״והוא לא פנים קלקל״: בגלל שהדור (״פנים״, פני הדור) קלקל את מעשיו. הגמרא מיד שואלת מה עושים.',
'7b:7:2': 'הגמרא שואלת: אם הרקיע ״קהה״ בגלל מעשי הדור, מה התיקון שלהם?',
'7b:7:3': 'התשובה מהמשך הפסוק: ״וחילים יגבר״, יגבירו כוחות. כלומר, יתגברו בתפילה ובבקשת רחמים, וכך ישברו את ״הברזל״ של הרקיע.',
'7b:7:4': 'סוף הפסוק, ״ויתרון הכשיר חכמה״, מלמד שיש משהו טוב יותר מתפילה: אם הדור יתקן את מעשיו מלכתחילה, כל שכן שהגשם ירד, ולא יצטרכו להתגבר ברחמים.',
'7b:7:5': 'ריש לקיש דורש את אותו פסוק, ״אם קהה הברזל״, על לימוד תורה: ״אם ראית תלמיד שלמודו קשה עליו כברזל״. הדף נגמר באמצע המשפט, וההמשך שלו נמצא בתחילת דף ח.',
'7b:8:0': 'הדף מונה סיבות רבות לעצירת גשמים. אלה לא מחלוקות של ״או זה או זה״: כל אחד מהחטאים יכול לעצור את הגשם. המשותף לרובם: חטאים בין אדם לחברו (לשון הרע, גזל, חוצפה) ובין אדם למקום (תרומות, תורה).',
'7b:8:1': 'בכמה מהדרשות העונש דומה לחטא: מי שלא נתן תרומות ומעשרות בקיץ, ״יגזלו״ ממנו את הגשם בחורף. ומי שגזל בכפיו, ה׳ ״על כפים כסה אור״. זה מראה שהגשם תלוי ישירות במעשים.',
'7b:8:2': 'ר׳ אמי נותן את התיקון פעמיים: ״ירבה בתפלה״ (״במפגיע״), ו״יתגברו ברחמים״ (״וחילים יגבר״). אבל הוא מוסיף ״כל שכן אם הוכשרו מעשיהן מעיקרא״: עדיף לא להגיע לשם בכלל. זה מכין את פרק ב׳ של המסכת, שבו מתפללים ומתענים על הגשם.',
'7a:0:0': 'זה סוף הדיון מדף ו: על הברכה שמברכים כשיורד גשם. ר׳ יוחנן חתם ״רוב ההודאות״, והקשו שזה נשמע כאילו לא כל ההודאות. רבא אמר לומר ״האל ההודאות״. רב פפא מכריע שלא בוחרים ביניהם: אומרים את שתי הלשונות. זו ההלכה.',
'7a:0:1': 'אחרי הברכה על הגשם באים דברי שבח על יום הגשמים. ר׳ אבהו אומר משפט מפתיע: יום שיורד בו גשם גדול יותר מתחיית המתים. הוא מיד מסביר למה.',
'7a:0:2': 'הטעם של ר׳ אבהו: תחיית המתים היא שכר רק לצדיקים. הגשם, לעומת זאת, יורד לכולם, גם לרשעים. ברכה שמגיעה לכל העולם גדולה יותר מברכה שמגיעה רק לחלק ממנו.',
'7a:0:3': 'הגמרא מציינת שדברי ר׳ אבהו לא מתאימים לדברי רב יוסף. ר׳ אבהו אמר שהגשם גדול יותר מתחיית המתים. מיד נראה שרב יוסף אומר שהם רק שקולים.',
'7a:0:4': 'רב יוסף מסביר למה ״משיב הרוח ומוריד הגשם״ נאמר דווקא בברכה השנייה של שמונה עשרה, ״מחיה המתים״ (המשנה בדף ב.). לדעתו הגשם שקול לתחיית המתים, ולכן שמו אותם יחד. ר׳ אבהו אמר ״גדול״, ורב יוסף רק ״שקולה״. זו המחלוקת שהגמרא ציינה.',
'7a:1:0': 'עוד שבח ליום הגשמים. ר׳ אבהו השווה אותו לתחיית המתים, ורב יהודה משווה אותו ליום שבו ניתנה התורה בהר סיני. הוא מביא מיד ראיה מפסוק.',
'7a:1:1': 'הראיה של רב יהודה: בשירת ״האזינו״ משה רבינו אומר ״יערף כמטר לקחי״, שהלימוד שלו ירד כמו מטר. ומניין ש״לקח״ פירושו תורה? מהפסוק במשלי ״כי לקח טוב נתתי לכם, תורתי אל תעזובו״, שבו ״לקח״ ו״תורתי״ באים יחד. אם התורה נמשלה למטר, הם שווים.',
'7a:1:2': 'רבא לא מסכים עם רב יהודה שהם רק שווים. לדעתו יום הגשמים גדול יותר מיום מתן תורה, והוא לומד את זה מאותו פסוק עצמו, ״יערף כמטר לקחי״.',
'7a:1:3': 'רבא מביא את אותו פסוק שהביא רב יהודה: ״יערף כמטר לקחי״. אבל הוא שם לב למשהו נוסף: בפסוק התורה משולה למטר, ולא המטר לתורה. מיד הוא שואל מה זה מלמד.',
'7a:1:4': 'רבא שואל: כשמשווים שני דברים במשל, איזה מהם ״נתלה״ בשני? בפסוק ״יערף כמטר לקחי״ התורה (״לקחי״) מושווה למטר. השאלה היא מה זה אומר על מי מהם גדול יותר.',
'7a:1:5': 'התשובה של רבא: במשל משווים תמיד את הדבר הקטן לדבר הגדול, כדי להסביר אותו. בפסוק התורה מושווית למטר, ולכן המטר הוא ״הגדול״. מכאן שיום הגשמים גדול אפילו מיום מתן תורה, כמו שרבא אמר.',
'7a:2:0': 'רבא מקשה בין שני חלקים של אותו פסוק ב״האזינו״. בחלק הראשון התורה נמשלת למטר, שהוא גשם חזק. בחלק השני היא נמשלת לטל, שיורד בשקט ובעדינות. אז איך התורה, כמו מטר או כמו טל?',
'7a:2:1': 'התשובה של רבא: הכל תלוי בתלמיד. אצל תלמיד חכם הגון התורה נכנסת בנחת, כמו טל. ואם הוא לא הגון, ״יערף״ מתפרש מלשון עריפה: התורה פוגעת בו כמו מטר חזק. עוד רגע ר׳ בנאה ילמד מאותה מילה ״יערף״ שהתורה שלא לשמה היא ״סם המות״.',
'7a:3:0': 'ברייתא שממשיכה את הרעיון של רבא, שהתורה יכולה להיות טל או מטר. ר׳ בנאה אומר שמי שלומד תורה ״לשמה״, כלומר בשביל התורה עצמה ולא בשביל כבוד או רווח, התורה שלו הופכת ל״סם חיים״, תרופה שנותנת חיים. מיד הוא מביא שלושה פסוקים.',
'7a:3:1': 'הראיות של ר׳ בנאה: שלושה פסוקים מספר משלי. ״עץ חיים היא למחזיקים בה״, ״רפאות תהי לשרך״ (רפואה לגוף), ו״כי מוצאי מצא חיים״. כולם מדברים על התורה כמקור חיים ובריאות, וזה ה״סם חיים״.',
'7a:3:2': 'החצי השני של דברי ר׳ בנאה: מי שלומד תורה ״שלא לשמה״, למשל כדי להתגאות או לנצח אחרים, אותה תורה עצמה נעשית לו ״סם המות״. זה כמו הסתירה של רבא: התורה אותה תורה, אבל התוצאה תלויה בלומד.',
'7a:3:3': 'מאיפה ר׳ בנאה לומד ש״שלא לשמה״ זה ״סם המות״? מהמילה ״יערף״ בפסוק ״יערף כמטר לקחי״. ״עריפה״ בתורה פירושה הריגה, כמו בעגלה ערופה: ״וערפו שם את העגלה בנחל״. זה מתאים לתשובה של רבא, שאצל מי שאינו הגון ״עורפהו כמטר״.',
'7a:4:0': 'מעשה קצר שמוביל לעוד דרשה על תלמידי חכמים. ר׳ ירמיה, תלמיד של ר׳ זירא, מבקש ממנו לבוא ולומר שמועה, כלומר ללמד הלכה.',
'7a:4:1': 'ר׳ זירא מסרב: הוא מרגיש חלש, ואין לו כוח לעיון בהלכה, שדורש ריכוז ומאמץ.',
'7a:4:2': 'ר׳ ירמיה לא מוותר: אם אין כוח להלכה, שיאמר ר׳ זירא דבר אגדה, שמושך את הלב ואינו מעייף. ר׳ זירא מסכים ומביא דרשה של ר׳ יוחנן.',
'7a:4:3': 'זו האגדה שר׳ זירא אומר בשם ר׳ יוחנן. בתורה, בדין עצי פרי במלחמה, כתוב ״כי האדם עץ השדה״. ר׳ יוחנן שואל: האם אדם הוא עץ? הפסוק נראה מוזר, ולכן הוא דורש אותו על תלמידי חכמים.',
'7a:4:4': 'ר׳ יוחנן מסביר: ״כי האדם עץ השדה״ בא ליישב שני פסוקים סמוכים. בפסוק אחד: ״כי ממנו תאכל ואותו לא תכרת״, אסור לכרות את העץ. ובפסוק שאחריו: ״אותו תשחית וכרת״, כן כורתים. בפשט זה עץ פרי מול עץ סרק, אבל ר׳ יוחנן דורש את זה על אדם.',
'7a:4:5': 'היישוב של ר׳ יוחנן: ״האדם״ הוא תלמיד חכם. אם הוא הגון, ״ממנו תאכל״, כלומר לומדים ממנו תורה, ואסור להתרחק ממנו. ואם הוא לא הגון, ״אותו תשחית וכרת״: מתרחקים ממנו ולא לומדים ממנו. זה אותו רעיון של רבא (טל או מטר): הכל תלוי אם התלמיד חכם הגון.',
'7a:5:0': 'אחרי הדרשות על תלמיד הגון, באה שורה של משלים לתורה ולומדיה. ר׳ חמא בר׳ חנינא (בדפוס: ״(אמר רבי)״ בסוגריים, כלומר מחיקה) דורש את הפסוק במשלי ״ברזל בברזל יחד״, שבו ברזל מחדד ברזל.',
'7a:5:1': 'הפשט: כמו שמשחיזים כלי ברזל בעזרת ברזל אחר, כך שני תלמידי חכמים שלומדים יחד מחדדים זה את זה. השאלות והקושיות של כל אחד משחיזות את ההבנה של חבירו. זה השבח של לימוד בחברותא.',
'7a:5:2': 'רבה בר בר חנה מביא משל אחר. בספר ירמיה כתוב ״הלא כה דברי כאש נאם ה׳״. הוא שואל מה בדיוק דומה בין דברי תורה לאש.',
'7a:5:3': 'התשובה: אש לא דולקת טוב בעץ אחד לבד, צריך כמה עצים יחד. כך גם התורה לא ״מתקיימת״, לא נשמרת ולא מובנת נכון, אצל מי שלומד לבד. זה ההמשך של המשל של ר׳ חמא על הברזל: צריך ללמוד עם עוד אנשים. ר׳ יוסי בר חנינא מיד מוסיף מה קורה למי שלומד לבד.',
'7a:6:0': 'הגמרא אומרת ״והיינו״: הרעיון של רבה בר בר חנה, שהתורה לא מתקיימת ביחידי, הוא מה שר׳ יוסי בר חנינא דרש בפסוק בירמיה: ״חרב אל הבדים ונואלו״. ״בדים״ נדרש מלשון ״בד בבד״, אחד לבד.',
'7a:6:1': 'הדרשה: ״חרב אל הבדים״, חרב תבוא על תלמידי חכמים שלומדים ״בד בבד״, כל אחד לבד. הגמרא אומרת ״שונאיהן של תלמידי חכמים״ בלשון נקייה, כדי לא לומר קללה ישר על תלמידי חכמים.',
'7a:6:2': 'המשך הדרשה: לא רק עונש, אלא גם הלימוד עצמו מתקלקל. ״ונואלו״ פירושו נעשו טיפשים. בלי מישהו שיתקן אותו, הלומד לבד מגיע למסקנות שגויות.',
'7a:6:3': 'ועוד יותר: מי שלומד לבד בא לידי חטא, כי הוא פוסק בטעות. הראיה בגזירה שווה: ״ונואלו״ כאן, ובמקום אחר (אהרן אומר למשה) ״אשר נואלנו ואשר חטאנו״, שם ״נואלנו״ בא יחד עם ״חטאנו״.',
'7a:6:4': 'ראיה אחרת לאותו דבר: בישעיה כתוב ״נואלו שרי צוען... התעו את מצרים״. השרים ״נואלו״, ובגלל זה הטעו אחרים, כלומר הטיפשות הובילה לטעות ולחטא.',
'7a:7:0': 'עוד משל לתורה. רב נחמן בר יצחק מביא את הפסוק ״עץ חיים היא למחזיקים בה״ (שגם ר׳ בנאה הביא), ושואל מה דומה בין התורה לעץ.',
'7a:7:1': 'התשובה: מדליקים עץ גדול בעזרת עצים קטנים, כמו זרדים. כך גם תלמידים צעירים, בשאלות שלהם, מחדדים את החכמים הגדולים. זה ממשיך את המשל של הברזל והאש: לימוד עם אחרים, כולל קטנים, מחדד.',
'7a:7:2': 'הגמרא מחברת: זה מה שאמר ר׳ חנינא. הוא למד הרבה מרבותיו, יותר מהם מחבריו (כמו ״ברזל בברזל״), ויותר מכולם מתלמידיו (כמו ״עץ קטן מדליק את הגדול״). השאלות של התלמידים מכריחות את הרב להבין לעומק.',
'7a:8:0': 'ר׳ חנינא בר פפא מקשה בין שני פסוקים בישעיה, ושניהם נדרשים על תורה (״מים״). בפסוק אחד: ״לקראת צמא התיו מים״, מביאים את המים אל הצמא. ובפסוק השני: ״הוי כל צמא לכו למים״, הצמא צריך ללכת אל המים. אז מי הולך אל מי, הרב אל התלמיד או התלמיד אל הרב?',
'7a:8:1': 'היישוב: אם התלמיד הגון, הרב הולך אליו ומביא לו את ה״מים״, את התורה. ואם הוא לא הגון, לא רודפים אחריו: שיבוא בעצמו אל המים. זה שוב אותו רעיון של הדף, ״אם הגון הוא״.',
'7a:8:2': 'עוד סתירה מאותו סוג. ר׳ חנינא בר חמא מקשה בין שני פסוקים סמוכים במשלי. ״יפוצו מעינותיך חוצה״: שהתורה שלך תצא החוצה, תלמד אותה לאחרים. ו״יהיו לך לבדך״: שתשאיר אותה לעצמך. אז מלמדים לכולם או לא?',
'7a:8:3': 'אותו יישוב: לתלמיד הגון מלמדים, ״יפוצו מעינותיך חוצה״. ואם הוא לא הגון, לא מלמדים אותו, ״יהיו לך לבדך״. כך גם ר׳ יוחנן אמר ״אותו תשחית וכרת״: לא כל אחד ראוי שילמדו אותו.',
'7a:9:0': 'עוד משל, על אותו פסוק ״הוי כל צמא לכו למים״ שהופיע בסתירה הקודמת. ר׳ חנינא בר אידי שואל מה דומה בין התורה למים.',
'7a:9:1': 'התשובה: מים לא נשארים על מקום גבוה, הם זורמים ונאספים במקום נמוך. כך התורה לא נשארת אצל אדם גאוותן, ״גבוה״, אלא רק אצל מי שדעתו שפלה, צנוע. ר׳ אושעיא ממשיך את אותו רעיון עם שלושה משקים.',
'7a:9:2': 'ר׳ אושעיא מוסיף: באותו פרק בישעיה התורה נמשלת לא רק למים, אלא גם ליין ולחלב: ״לכו שברו... בלא כסף ובלא מחיר יין וחלב״. הוא שואל מה משותף לשלושת המשקים האלה.',
'7a:9:3': 'התשובה: מים, יין וחלב נשמרים טוב דווקא בכלים הפשוטים, כלי חרס, ולא בכלי זהב וכסף (שם הם מתקלקלים). כך גם התורה נשמרת אצל מי שדעתו שפלה. הגמרא מביאה מיד מעשה שמראה את זה: בת הקיסר ור׳ יהושע בן חנניה.',
'7a:10:0': 'המעשה מראה את דברי ר׳ אושעיא, שהתורה נשמרת ״בפחות שבכלים״. ר׳ יהושע בן חנניה היה חכם גדול, אבל מראהו היה מכוער. בת הקיסר הרומי אמרה לו בלעג: חבל, חכמה מפוארה כזאת נמצאת ב״כלי״ מכוער כזה, כלומר בגוף שלו.',
'7a:10:1': 'ר׳ יהושע לא נעלב. הוא שואל אותה (או מעיר): אביך הקיסר שם את היין שלו בכלי חרס פשוטים. גם המלך, העשיר מכולם, שומר את היין בכלים הכי פשוטים.',
'7a:10:2': 'בת הקיסר לא מבינה מה הבעיה. היא שואלת: אם לא בכלי חרס, במה כבר אפשר לשמור את היין?',
'7a:10:3': 'ר׳ יהושע עונה, בכוונה: אתם, משפחת המלוכה החשובה, ראוי שתשימו את היין בכלי זהב וכסף, ולא בחרס כמו כולם. הוא יודע מה יקרה ליין.',
'7a:10:4': 'בת הקיסר הלכה ואמרה לאביה. שמו את היין בכלי זהב וכסף, והיין ״תקיף״, החמיץ. מתכות יקרות לא שומרות על היין כמו חרס.',
'7a:10:5': 'המשרתים באו וסיפרו לקיסר שהיין החמיץ. הקיסר שאל את בתו מי אמר לה לעשות את זה, והיא ענתה: ר׳ יהושע בן חנניה.',
'7a:10:6': 'קראו לר׳ יהושע אל הקיסר. הקיסר שאל אותו למה נתן לבתו עצה שקלקלה את היין.',
'7a:10:7': 'ר׳ יהושע מסביר: כמו שהיא אמרה לי (״חכמה מפוארה בכלי מכוער״), כך עניתי לה. הוא רצה להראות לה שבדיוק כמו יין, גם החכמה נשמרת טוב דווקא ב״כלי״ פשוט. זה מה שר׳ אושעיא אמר: התורה נשמרת במי שדעתו שפלה.',
'7a:10:8': 'הקיסר (או בתו) מקשה: הרי יש גם אנשים יפים שהם תלמידי חכמים! אז לא נכון שהחכמה נשמרת רק במכוערים. התשובה של ר׳ יהושע נמצאת בתחילת דף ז: ״אי הוו סנו, הוו גמירי טפי״: אילו היו מכוערים, היו חכמים עוד יותר.',
'7a:11:0': 'רבא (מטר או טל), ר׳ יוחנן (ממנו תאכל או אותו תשחית), ר׳ חנינא בר פפא (מי הולך אל מי) ור׳ חנינא בר חמא (חוצה או לבדך): כל אחד מצא שני פסוקים שנראים סותרים, וכולם יישבו באותה דרך. התורה אותה תורה, אבל איך היא פועלת תלויה במי שמקבל אותה.',
'7a:11:1': 'ברזל: שני תלמידים מחדדים זה את זה. אש: עץ אחד לא דולק, ותורה ביחידי לא מתקיימת, ומי שלומד ״בד בבד״ מטפש וחוטא. עץ: הקטנים מדליקים את הגדולים, ולכן ר׳ חנינא למד הכי הרבה מתלמידיו.',
'7a:11:2': 'ר׳ חנינא בר אידי ור׳ אושעיא: כמו שמים זורמים למקום נמוך, ויין וחלב נשמרים בכלי פשוט, כך התורה נשמרת אצל אדם צנוע. ר׳ יהושע בן חנניה הראה את זה לבת הקיסר בעזרת היין של אביה.',
'7a:11:3': 'הקישור בין חלקי הדף הוא הפסוק ״יערף כמטר לקחי״. רב יהודה ורבא למדו ממנו כמה גדול יום הגשמים, ומשם הגמרא עברה למה שהפסוק מלמד על התורה: שהיא כמו גשם, ברכה גדולה למי שמקבל אותה כראוי.',
'6b:0:0': 'זו ההמשך של תשובת ר׳ זירא מסוף דף ו. לשאלה ״רביעה שנייה למאי?״: היא חשובה לנדרים. המשנה במסכת נדרים אומרת שמי שנדר ״עד הגשמים״, הנדר שלו נמשך עד שיורדת הרביעה השנייה. כך אנשים מבינים ״הגשמים״: לא הטיפות הראשונות, אלא הגשם האמיתי של החורף.',
'6b:0:1': 'רב זביד נותן תשובה נוספת לשאלה ״רביעה שנייה למאי״: לזיתים. כלומר, יש דין בזיתים שתלוי ברביעה השנייה. הוא מביא מיד משנה (במסכת פאה) שמראה את זה.',
'6b:0:2': 'זו המשנה שרב זביד מביא. לקט, שכחה ופאה הם מתנות שהתורה נותנת לעניים. אבל אחרי זמן מסוים העניים מתייאשים, ואז גם עשירים מותרים לקחת מה שנשאר. בשדה — ״משילכו הנמושות״ (שיתבאר בקטע הבא). בכרם — אחרי שהעניים הלכו וחזרו פעם שנייה. ובזיתים — אחרי הרביעה השנייה, כי עד אז כבר ליקטו הכל (רש״י).',
'6b:1:0': 'המשנה אמרה שבשדה כל אדם מותר בלקט ״משילכו הנמושות״. הגמרא שואלת: מה פירוש המילה ״נמושות״? מי הם האנשים האלה, שאחריהם כבר אין מה לחכות?',
'6b:1:1': 'התשובה הראשונה לשאלה ״מאי נמושות״: ר׳ יוחנן אומר שהם ״סבי דאזלי אתיגרא״, זקנים שהולכים נשענים על מקל. רש״י: הם הולכים בנחת ומחפשים בעיון, ולכן הם האחרונים שמלקטים. אחרי שגם הם עברו, שאר העניים מתייאשים.',
'6b:1:2': 'התשובה השנייה לשאלה ״מאי נמושות״: ריש לקיש אומר ״לקוטי בתר לקוטי״, מלקטים שבאים אחרי מלקטים. רש״י: עני שמוליך את בנו אחריו ללקט אחריו. מכאן ואילך שאר העניים מפסיקים ללקט.',
'6b:2:0': 'תשובה שלישית לשאלה ״רביעה שנייה למאי״: רב פפא אומר שהיא קובעת עד מתי מותר לעבור בשבילים שבתוך שדות פרטיים. רש״י: עוברי דרכים רשאים לקצר את הדרך דרך השדות, אבל אחרי הרביעה השנייה התבואה גדלה, ודריכה מזיקה לה.',
'6b:2:1': 'המקור לדברי רב פפא: ״דאמר מר״, שמועה (רש״י: בפרק מרובה, מן התנאים שהתנה יהושע כשחילק את הארץ) שמותר לכל אדם ללכת בשבילים שבשדות של אחרים עד שתרד הרביעה השנייה. אחר כך כבר אסור, כי זה מזיק לצמחים.',
'6b:2:2': 'תשובה רביעית לשאלה ״רביעה שנייה למאי״: רב נחמן בר יצחק אומר שהיא קובעת את זמן הביעור של פירות שביעית. פירות שגדלו בשנת השמיטה מותרים רק כל זמן שיש מאותו מין בשדה. כשהם כלים מהשדה, צריך לבער אותם גם מהבית.',
'6b:2:3': 'זו המשנה שרב נחמן בר יצחק מביא: אפשר ליהנות ולשרוף תבן וקש של שנת השמיטה רק עד הרביעה השנייה. רש״י: מכאן ואילך אין עוד תבן וקש בשדות, כי הגשמים הופכים אותם לזבל. ולכן גם בבית צריך לבער.',
'6b:2:4': 'הגמרא שואלת על המשנה של שביעית: מה הטעם? למה הזמן שבו צריך לבער את התבן מהבית תלוי ברביעה השנייה, כלומר במה שקורה בשדה?',
'6b:2:5': 'התשובה לשאלה ״מאי טעמא״: הפסוק בפרשת שמיטה אומר ״ולבהמתך ולחיה אשר בארצך תהיה כל תבואתה לאכול״. מכאן לומדים: כל זמן שהחיה מוצאת אוכל בשדה, מותר להאכיל את הבהמה בבית מפירות השמיטה. כשהאוכל כלה לחיה מהשדה (אחרי הרביעה השנייה), צריך לכלות גם את מה שבבית.',
'6b:3:0': 'אחרי שהגמרא דיברה כל הזמן על ״רביעה ראשונה״ ו״רביעה שנייה״, ר׳ אבהו שואל: מה פירוש המילה ״רביעה״? למה הגשם הזה נקרא כך?',
'6b:3:1': 'התשובה של ר׳ אבהו לשאלה ״מאי לשון רביעה״: ״דבר שרובע את הקרקע״. ״רביעה״ היא לשון זיווג. הגשם מפרה את האדמה כמו שבעל מפרה את אשתו, ומשם הצמחים ״נולדים״.',
'6b:3:2': 'ר׳ אבהו מבסס את הפירוש שלו על דברי רב יהודה: ״מיטרא בעלה דארעא הוא״, הגשם הוא הבעל של האדמה. ולכן מתאים לקרוא לירידת הגשם ״רביעה״.',
'6b:3:3': 'הראיה של רב יהודה מהפסוק בישעיהו: ״כי כאשר ירד הגשם... כי אם הרוה את הארץ והולידה והצמיחה״. הפסוק אומר שהגשם ״מוליד״ את הארץ. רש״י: כאדם שמוליד. כך רואים שהגשם הוא כמו בעל.',
'6b:3:4': 'ר׳ אבהו מגדיר עכשיו כמה גשם נחשב ״רביעה״. הרביעה הראשונה היא גשם שיורד לתוך האדמה לעומק טפח (בערך 8 ס״מ).',
'6b:3:5': 'והרביעה השנייה, לפי ר׳ אבהו, היא כמות גשם שהאדמה נעשית ממנה בוץ, שאפשר לסתום בו פתח של חבית בלי להוסיף מים (רש״י).',
'6b:4:0': 'רב חסדא אומר: אם ירד גשם בכמות שמספיקה לבוץ שאפשר לסתום בו פי חבית (הרביעה השנייה), אין כאן הקללה של ״ועצר את השמים״ שבפרשת קריאת שמע. גם אם לא ירד יותר, השמים לא נחשבים ״עצורים״.',
'6b:4:1': 'עוד דין של רב חסדא: גשם שירד לפני שמגיעים בקריאת שמע לפסוק ״ועצר את השמים ולא יהיה מטר״ — אין בו קללה. רש״י: כלומר לפני זמן קריאת שמע, אפילו אם לא ירד הרבה.',
'6b:4:2': 'אביי מסביר את דברי רב חסדא: זה נאמר רק על גשם שירד לפני ״ועצר״ של קריאת שמע של ערבית, כלומר בלילה. אבל גשם שירד בבוקר, לפני קריאת שמע של שחרית, כן נחשב קללה. רש״י: כי הגשם לא ירד ביום, ואינו מועיל.',
'6b:4:3': 'הראיה לדברי אביי: רב יהודה בר יצחק אמר ״הני ענני דצפרא לית בהו מששא״, עננים של בוקר אין בהם ממש. הם נעלמים מהר ולא מביאים גשם של ברכה. ולכן גם גשם של בוקר אינו נחשב ברכה.',
'6b:4:4': 'המקור של רב יהודה בר יצחק: הנביא הושע אומר לישראל ״וחסדכם כענן בקר״, החסד שלכם חולף כמו ענן של בוקר. משמע שענן בוקר הוא סמל לדבר שעובר ואין בו ממש.',
'6b:4:5': 'רב פפא מקשה על אביי (שאמר שגשם של בוקר הוא קללה): הרי יש פתגם עממי: ״כשנפתחים שערי הבוקר ויורד גשם — בעל החמור (הסוחר בתבואה), קפל את השק שלך ולך לישון״. כלומר גשם בבוקר מבשר שנה של שפע, והסוחר לא ירוויח. משמע שגשם של בוקר הוא ברכה!',
'6b:4:6': 'התשובה לקושיה של רב פפא: ״לא קשיא״. הפתגם מדבר על בוקר שבו השמים מכוסים ב״עיבא״, עננים עבים וכבדים, ואז הגשם אמיתי וטוב. אביי מדבר על ״עננא״, עננים דקים, שאין בהם ממש.',
'6b:5:0': 'רב יהודה אומר פתגם על הגשמים: ״טבא לשתא דטבת ארמלתא״, טובה השנה שחודש טבת שלה הוא ״אלמנה״. הגשם הוא ״הבעל״ של האדמה (כמו שראינו), ולכן חודש בלי גשם נקרא ״אלמנה״. הגמרא תשאל מה בדיוק טוב בזה.',
'6b:5:1': 'פירוש ראשון למה טבת יבש הוא טוב: ״דלא ביירי תרביצי״, הגינות לא נשארות ריקות (תוספות: שאין הגינות ריקות מזרעים). כשהגשם לא שוטף, אפשר לזרוע והצמחים לא נהרסים.',
'6b:5:2': 'פירוש שני למה טבת יבש הוא טוב: ״דלא שקיל שודפנא״, התבואה לא נפגעת משדפון, מחלה של התבואה שבאה מלחות מרובה.',
'6b:5:3': 'הגמרא מקשה על רב יהודה: האמנם? הרי רב חסדא אמר ההפך: ״טבא לשתא דטבת מנוולתא״, טובה השנה שחודש טבת שלה ״מנוול״, מלא בוץ וגשם. אז טבת יבש טוב או טבת גשום טוב?',
'6b:5:4': 'התשובה לסתירה בין רב יהודה לרב חסדא: ״לא קשיא״. רב יהודה מדבר על שנה שכבר ירד בה גשם לפני טבת, ואז טוב שטבת יהיה יבש. רב חסדא מדבר על שנה שלא ירד בה גשם קודם, ואז טוב שלפחות בטבת יירד הרבה.',
'6b:6:0': 'עוד דין של רב חסדא: אם במקום אחד ירד גשם ובמקום אחר לא, זה לא נחשב הקללה של ״ועצר את השמים״, כי השמים לא נעצרו לגמרי.',
'6b:6:1': 'הגמרא מקשה על רב חסדא: האמנם? הרי הנביא עמוס אומר בשם ה׳: ״והמטרתי על עיר אחת ועל עיר אחת לא אמטיר, חלקה אחת תמטר״, ומתאר את זה כחלק מהעונשים לישראל. משמע שגשם רק במקום אחד כן קללה.',
'6b:6:2': 'הקושיה מתחזקת: רב יהודה אמר בשם רב שבפסוק של עמוס ״שתיהן לקללה״. לא רק העיר שלא ירד בה גשם מקוללת, אלא גם העיר שירד בה. אז איך רב חסדא אומר שזה לא ״ועצר״?',
'6b:6:3': 'התשובה לקושיה מעמוס: ״לא קשיא״. בפסוק מדובר בגשם שירד ״טובא״, הרבה מדי, ולכן גם העיר שירד בה מקוללת (שיטפונות). רב חסדא מדבר על גשם שירד ״כדמבעי ליה״, בכמות הנכונה, ואז זו לא קללה.',
'6b:6:4': 'רב אשי מוסיף ראיה לתשובה: ״דיקא נמי״, הלשון של הפסוק מדויקת. כתוב ״תמטר״, ומשמע שהמקום ייעשה ״מקום מטר״, הכל מלא מים. כלומר מדובר בגשם מוגזם, ולכן גם הוא קללה. ״שמע מינה״: כך מוכח.',
'6b:7:0': 'ר׳ אבהו פותח נושא חדש: יש ברכה מיוחדת כשיורד גשם. ממתי מברכים אותה? מהטיפה הראשונה, או רק כשיורד גשם של ממש?',
'6b:7:1': 'התשובה של ר׳ אבהו: ״משיצא חתן לקראת כלה״. כשיורד גשם חזק, המים שעל הארץ ״קופצים״ לקראת הטיפות שיורדות, כמו חתן שיוצא לקראת הכלה. רק אז, כשהגשם כבר ממשי, מברכים.',
'6b:7:2': 'אחרי שהגמרא קבעה מתי מברכים על הגשם, היא שואלת: מה אומרים? מה נוסח הברכה?',
'6b:7:3': 'התשובה לשאלה ״מאי מברך״: רב יהודה אומר בשם רב שהברכה היא ״מודים אנחנו לך ה׳ אלהינו על כל טפה וטפה שהורדת לנו״. מודים על כל טיפה בנפרד.',
'6b:7:4': 'ר׳ יוחנן מוסיף לברכה של רב סיום ארוך: ״אילו פינו מלא שירה כים, ולשוננו רנה כהמון גליו...״, הקטע שאנחנו אומרים בתפילת ״נשמת כל חי״, עד ״אל יעזבונו רחמיך ה׳ אלהינו״. ואז הוא חותם: ״ברוך... רוב ההודאות״.',
'6b:7:5': 'הגמרא מקשה על החתימה של ר׳ יוחנן: ״רוב ההודאות״ נשמע כאילו מודים לה׳ רק ״רוב״ ההודאות, ולא ״כל״ ההודאות. אין זה מתאים לשבח של ה׳.',
'6b:7:6': 'התשובה לקושיה ״ולא כל ההודאות?!״: רבא אומר לשנות את הנוסח: לא ״רוב ההודאות״ אלא ״האל ההודאות״, כלומר ה׳ הוא בעל כל ההודאות.',
'6b:7:7': 'רב פפא מכריע: ״הלכך נימרינהו לתרוייהו״, לכן נאמר את שני הנוסחים יחד: ״רוב ההודאות והאל ההודאות״. כך אנחנו אומרים גם היום בסוף ״נשמת״. המילה ״נימרינהו״ בתחתית העמוד היא ההתחלה של העמוד הבא (ז.).',
'6b:8:0': 'כמעט כל הדף עוסק בשאלה אחת: מתי הגשם הוא ברכה ומתי לא. הרביעה השנייה קובעת דינים בשדה. גשם בבוקר לפני קריאת שמע — קללה, בלילה — לא. טבת יבש או גשום — תלוי במה שקדם. גשם במקום אחד — תלוי בכמות.',
'6b:8:1': 'אביי: גשם לפני קריאת שמע של ערבית אינו קללה, אבל לפני של שחרית — קללה, כי ענני בוקר אין בהם ממש. וגם בטבת: הכל תלוי אם ירד גשם קודם.',
'6b:8:2': 'רב חסדא: גשם שמספיק לבוץ כבר מסיר את הקללה של ״ועצר״. ומאידך, בפסוק בעמוס ״חלקה אחת תמטר״ — גשם מוגזם במקום אחד גם הוא קללה (רב אשי: ״תהא מקום מטר״).',
'6b:8:3': 'הדף נגמר בברכה: כשיורד גשם של ברכה (״משיצא חתן לקראת כלה״) מודים ״על כל טפה וטפה״, ומסיימים, לפי רב פפא, גם ״רוב ההודאות״ וגם ״האל ההודאות״.',
'2b:0:0': 'זה סוף הפסוק שהתחיל בדף ב.: ״ויזכר אלהים את רחל וישמע אליה אלהים ויפתח את רחמה״ (בראשית ל, כב). ר׳ יוחנן מביא אותו כמקור ל״מפתח של חיה״: הלידה נמסרה רק לה׳, והפסוק אומר שה׳ עצמו ״פתח״.',
'2b:0:1': 'המפתח השלישי של ר׳ יוחנן הוא תחיית המתים. המקור הוא מיחזקאל (לז, יג), בנבואת העצמות היבשות: ״וידעתם כי אני ה׳ בפתחי את קברותיכם״. גם כאן מופיע לשון ״פתיחה״, וה׳ אומר ״אני״: אין שליח.',
'2b:0:2': '״במערבא״ פירושו החכמים בארץ ישראל (שנמצאת מערבית לבבל). הם מונים גם מפתח רביעי: הפרנסה. המקור הוא תהלים (קמה, טז): ״פותח את ידך ומשביע לכל חי רצון״. גם כאן לשון ״פתיחה״, וה׳ עצמו פותח את ידו.',
'2b:0:3': 'אם יש פסוק שאומר שה׳ ״פותח את ידו״ לפרנסה, למה ר׳ יוחנן מנה רק שלושה מפתחות (גשמים, חיה, תחיית המתים), ולא את המפתח של הפרנסה שמונים במערבא?',
'2b:0:4': 'התשובה לשאלה למה ר׳ יוחנן לא מנה את הפרנסה: לדעתו היא לא מפתח נפרד. הגשם הוא מה שמצמיח את התבואה, ולכן ״מפתח של גשמים״ הוא כבר ״מפתח של פרנסה״. אין מחלוקת אמיתית, רק דרך שונה למנות.',
'2b:1:0': 'הגמרא חוזרת עכשיו למשנה בדף ב.: ״מאימתי מזכירין גבורות גשמים? ר׳ אליעזר אומר: מיום טוב הראשון של חג״. היא רוצה להבין מאיפה ר׳ אליעזר למד שההזכרה מתחילה דווקא בתחילת סוכות.',
'2b:1:1': 'שני דברים מתחילים ביום הראשון של סוכות וקשורים למים: נטילת הלולב (ארבעת המינים ״באים לרצות על המים״) וניסוך המים על המזבח. הגמרא שואלת: ר׳ אליעזר, שאומר להתחיל להזכיר גשם ביום טוב הראשון, ממי מהם הוא למד? יש לזה השלכה מעשית, כמו שמיד יתברר.',
'2b:1:2': 'הצד הראשון: אם ר׳ אליעזר למד מהלולב, צריך ללמוד ממנו גם את השעה. את הלולב נוטלים רק ביום (״ולקחתם לכם ביום הראשון״), ולכן גם ההזכרה מתחילה רק ביום: בתפילת שחרית של יום טוב הראשון, ולא בערבית של הלילה שלפניו. (רש״י: אין מזכירים בליל יו״ט הראשון עד למחר.)',
'2b:1:3': 'הצד השני: אולי ר׳ אליעזר למד מניסוך המים. את ניסוך המים אפשר לעשות כבר ״מאורתא״, מהלילה, ולכן אם ממנו למד, ההזכרה תתחיל כבר בלילה. (רש״י מזכיר את מסכת סוכה, שם מבואר שממלאים את המים לניסוך עוד בלילה.)',
'2b:1:4': 'כדי להראות שניסוך אפשר כבר בלילה, הגמרא מביאה דרשה (״דאמר מר״): על הפסוק ״ומנחתם ונסכיהם״ (במדבר כט) דרשו שהמנחות והנסכים יכולים לבוא ״אפילו בלילה״, ולא רק ביום כמו הקרבנות עצמם. תוספות מסבירים: בדרך כלל אפשר להביא בלילה נסכים של קרבן שהוקרב ביום, ולגבי ניסוך המים זה עשוי להיות כבר מהלילה הראשונה.',
'2b:1:5': 'סוף הצד השני: אם ר׳ אליעזר למד מניסוך המים, שאפשר כבר בלילה, אז ״אף הזכרה מאורתא״: מתחילים לומר ״משיב הרוח״ כבר בתפילת ערבית של ליל יום טוב הראשון. זו כל נפקא המינה של השאלה: ערבית או שחרית.',
'2b:2:0': 'התשובה לשאלה ״מלולב או מניסוך״: ר׳ אבהו אמר במפורש ״לא למדה ר׳ אליעזר אלא מלולב״. לפי זה, כמו שהלולב רק ביום, גם ההזכרה מתחילה ביום, בשחרית של יום טוב הראשון, ולא בערבית.',
'2b:2:1': 'מאיפה ר׳ אבהו יודע ממה למד ר׳ אליעזר? יש שתי גרסאות. לפי הראשונה, ״גמרא גמיר לה״: זו מסורת שקיבל מרבותיו, שמועה בעל פה, בלי מקור כתוב.',
'2b:2:2': 'לפי הגרסה השנייה, ר׳ אבהו לא אמר מסברה או ממסורת, אלא ״מתניתא שמיע ליה״: הוא הכיר ברייתא שבה ר׳ אליעזר עצמו מדבר על הלולב. הגמרא שואלת ״מאי היא?״, איזו ברייתא, ומביאה אותה מיד (״דתניא״).',
'2b:3:0': 'זו הברייתא שר׳ אבהו ״שמע״ (לפי הגרסה השנייה). היא פותחת באותה שאלה כמו המשנה בדף ב.: ממתי מתחילים להזכיר גשם בתפילה? אבל כאן התשובות מנוסחות לפי הלולב.',
'2b:3:1': 'ר׳ אליעזר אומר בברייתא בפירוש: ״משעת נטילת לולב״, כלומר מתחילת סוכות, כשנוטלים את ארבעת המינים בפעם הראשונה (תוספות: תחילת יום ראשון של סוכות). כאן רואים שהוא תולה את ההזכרה בלולב, וזה המקור של ר׳ אבהו.',
'2b:3:2': 'ר׳ יהושע אומר ״משעת הנחתו״: כשמפסיקים ליטול את הלולב, כלומר בסוף החג. רש״י: מהיום שמברכים עליו בפעם האחרונה. תוספות: מהערב של מוצאי היום השביעי, שבו מניחים את הלולב. זו בעצם דעתו במשנה: ״מיום טוב האחרון״.',
'2b:3:3': 'ר׳ אליעזר מסביר למה דווקא הלולב קובע: ארבעת המינים (לולב, אתרוג, הדס וערבה) באים ״לרצות על המים״, לבקש מה׳ את מי השנה. הם צמחים שלא יכולים לגדול בלי מים, וכך גם העולם כולו לא יכול להתקיים בלי מים. לכן ברגע שנוטלים אותם, זה הזמן להתחיל לשבח את ה׳ על הגשם.',
'2b:4:0': 'ר׳ יהושע מקשה על ר׳ אליעזר, שאמר להזכיר גשם כבר מתחילת סוכות: גשם בחג הוא ״סימן קללה״, כי הוא מגרש את האנשים מהסוכה (המשל במסכת סוכה: עבד שמזג לרבו, והרב שפך את הכוס על פניו). איך אפשר לפתוח דווקא אז בגשם? זו אותה קושיה שהופיעה במשנה בדף ב.',
'2b:4:1': 'התשובה של ר׳ אליעזר לקושיה ״גשמים בחג סימן קללה״: הוא מבחין בין שאלה (בקשה, ״ותן טל ומטר״) להזכרה (שבח, ״משיב הרוח ומוריד הגשם״). בחג אף אחד לא מבקש גשם. מה שאומרים הוא רק שבח לכוח של ה׳, ואין בזה בקשה שירד גשם עכשיו.',
'2b:4:2': 'ר׳ אליעזר מוכיח שהזכרה היא רק שבח: בברכה ״מחיה המתים״ אנחנו מזכירים את תחיית המתים כל השנה, למרות שהיא תקרה רק ״בזמנה״, בעתיד. אף אחד לא חושב שזו בקשה שהמתים יקומו עכשיו. כך גם ״גבורות גשמים״: אפשר לשבח את ה׳ על הגשם כל השנה, למרות שהגשם עצמו יורד רק ״בזמנו״, בחורף.',
'2b:4:3': 'המסקנה של ר׳ אליעזר מהמשל של תחיית המתים: אם ההזכרה היא שבח בלבד, אין בה שום בעיה גם בקיץ. מי שרוצה להזכיר ״משיב הרוח״ כל השנה, רשאי. (תוספות בדף ב. כבר הביאו את הברייתא הזו.)',
'2b:5:0': 'רבי חולק על ״אם בא להזכיר כל השנה מזכיר״ של ר׳ אליעזר. לדעתו ההזכרה קשורה לבקשה: בפסח, כשמפסיקים לומר ״ותן טל ומטר״, מפסיקים גם לומר ״משיב הרוח״. רש״י: לכן אי אפשר להזכיר כל השנה. בקיץ לא מזכירים, כי זה לא זמן הגשם, וגם בחג לא, כי שם הגשם אינו סימן ברכה.',
'2b:5:1': 'שיטה שלישית: ר׳ יהודה בן בתירה (ריב״ב) אומר שמתחילים להזכיר גשם ביום השני של סוכות. זה לא הראשון (כמו ר׳ אליעזר) ולא האחרון (כמו ר׳ יהושע). הגמרא תסביר את הטעם בהמשך: הרמז לניסוך המים בתורה מתחיל ביום השני.',
'2b:5:2': 'שיטה רביעית: ר׳ עקיבא אומר שמתחילים ביום השישי של סוכות. גם את הטעם שלו הגמרא תסביר בהמשך: ביום השישי כתוב ״ונסכיה״, לשון רבים, ומשם לומדים על ניסוך המים.',
'2b:5:3': 'שיטה חמישית: ר׳ יהודה בשם ר׳ יהושע. זו אותה לשון כמו במשנה בדף ב.: בשמיני עצרת ״האחרון מזכיר״, כלומר החזן של מוסף מתחיל, ו״הראשון אינו מזכיר״, החזן של שחרית עוד לא. (תוספות מביאים את הירושלמי: למה לא מתחילים כבר בערבית? כי לא כל העם נמצא שם, ומי שלא שמע עלול לטעות.)',
'2b:5:4': 'וזה הסוף של החורף לפי ר׳ יהודה: ביום הראשון של פסח, החזן של שחרית (״הראשון״) עוד מזכיר, והחזן של מוסף (״האחרון״) כבר לא. כך ההזכרה מתחילה ונגמרת באותה תפילה, מוסף. בדף ג. הגמרא תשאל: מי הוא ״ר׳ יהושע״ שבשמו ר׳ יהודה אומר את זה.',
'2b:6:0': 'הגמרא מתרשמת מהמשל של ר׳ אליעזר: כמו שמזכירים תחיית המתים כל השנה, אפשר לשבח על הגשם גם כשזה לא זמנו. זה נשמע נכון (״שפיר קאמר״), ואז מה ר׳ יהושע יענה? למה הוא עדיין אומר שאין להזכיר גשם בחג?',
'2b:6:1': 'התשובה של ר׳ יהושע לקושיה ״שפיר קאמר״: המשל לא דומה. תחיית המתים רצויה בכל יום שתבוא, ״דכולי יומא זמניה הוא״, ולכן אפשר לשבח עליה תמיד. אבל גשם לא רצוי בכל זמן. רש״י: כיון שבחג זה לא הזמן שלו, אין מזכירים.',
'2b:6:2': 'ראיה לר׳ יהושע שגשם לא תמיד רצוי: משנה (בהמשך המסכת) אומרת ״יצא ניסן וירדו גשמים, סימן קללה הם״. המקור הוא שמואל (שמואל א יב, יז), שקרא לה׳ להוריד גשם בזמן קציר החיטים כדי להראות לעם שחטאו. אם יש זמן שבו הגשם הוא קללה, הוא לא כמו תחיית המתים.',
'2b:7:0': 'הגמרא חוזרת לשיטות שבברייתא, ומתחילה בר׳ יהודה בן בתירה, שאמר להתחיל להזכיר ביום השני של סוכות. השאלה המתבקשת: למה דווקא ביום השני?',
'2b:7:1': 'הגמרא שואלת מה הטעם של ר׳ יהודה בן בתירה: למה דווקא ביום השני של סוכות? מה מיוחד בו?',
'2b:7:2': 'התשובה לשאלה ״מאי טעמא דריב״ב״: בפרשת קרבנות סוכות (במדבר כט) כל יום כתוב בלשון ״ונסכה... כמשפט״. אבל ביום השני כתוב ״ונסכיהם״, עם מ׳ נוספת. ביום השישי ״ונסכיה״, עם י׳ נוספת. ביום השביעי ״כמשפטם״, עם ם׳ נוספת. שלוש האותיות האלה יוצרות את המילה ״מים״.',
'2b:7:3': 'המסקנה של ריב״ב מהאותיות ״מים״: ניסוך המים בסוכות, שלא כתוב בפירוש בתורה, רמוז בה. וכיון שהרמז מתחיל ביום השני (האות מ׳ הראשונה), משם מתחילים גם להזכיר את הגשם.',
'2b:8:0': 'הרמז ״מים״ מפוזר על שלושה ימים: השני, השישי והשביעי. אז למה ריב״ב אומר להתחיל להזכיר דווקא ביום השני, ולא, למשל, ביום השביעי, שבו המילה ״מים״ נשלמת?',
'2b:8:1': 'התשובה לשאלה ״מאי שנא בשני״: כשהתורה מתחילה לרמוז על המים, היא מתחילה ביום השני (האות מ׳ של ״ונסכיהם״). רש״י: כיון שבשני כבר יש מ׳ יתרה לדרשה, מתחילים להזכיר בשני. ההזכרה הולכת אחרי הרמז הראשון לניסוך.',
'2b:9:0': 'הגמרא עוברת לשיטה הבאה בברייתא, של ר׳ עקיבא: מתחילים להזכיר ביום השישי של סוכות. מה הטעם שלו?',
'2b:9:1': 'הטעם של ר׳ עקיבא: ביום השישי כתוב ״ונסכיה״, לשון רבים, למרות שמדובר בקרבן אחד (שעיר החטאת), שיש לו ניסוך אחד. מכאן שהפסוק מדבר על שני ניסוכים: ניסוך היין הרגיל, וניסוך המים. רש״י: ״ונסכיהם״ ביום השני לא מוכיח, כי שם מדובר בקרבנות רבים.',
'2b:9:2': 'הגמרא מקשה על ר׳ עקיבא: מ״ונסכיה״ לומדים רק שיש שני ניסוכים. אבל אולי שניהם של יין? מאיפה ר׳ עקיבא יודע שאחד מהם הוא של מים?',
'2b:9:3': 'התשובה לקושיה ״ואימא תרוייהו דחמרא״: ר׳ עקיבא מסכים עם ר׳ יהודה בן בתירה שבפסוקים רמוזים ״מים״ (מ׳ י׳ ם׳). לכן כשהוא מוצא ״שני ניסוכים״ ביום השישי, הוא יודע שהשני הוא של מים.',
'2b:9:4': 'המילה האחרונה בעמוד, ״אי״, פותחת את הקושיה שממשיכה בדף ג.: ״אי סבר לה כר׳ יהודה בן בתירה, לימא כוותיה!״ אם ר׳ עקיבא מקבל את הרמז של ריב״ב, שיתחיל להזכיר ביום השני כמוהו. בדף ג. התשובה: לדעת ר׳ עקיבא, הניסוך ״היתר״ כתוב רק ביום השישי.',
'2b:10:0': 'הדף מביא שש שיטות, ובכל אחת ההזכרה תלויה במשהו אחר. ר׳ אליעזר תולה אותה בלולב, שבא ״לרצות על המים״. ריב״ב ור׳ עקיבא תולים אותה בניסוך המים, ובמקום שבו הוא רמוז בתורה. רבי תולה אותה בבקשה. ור׳ יהושע תולה אותה בזמן שהגשם באמת רצוי.',
'2b:10:1': 'לר׳ אליעזר ההזכרה היא שבח לכוח של ה׳, כמו ״מחיה המתים״, ואין בה בקשה. לכן אין בעיה להזכיר גשם בחג, ואפילו כל השנה. רק את ההתחלה הרשמית הוא קושר ללולב.',
'2b:10:2': 'ר׳ יהושע ורבי חושבים שאי אפשר לשבח על גשם בזמן שהוא קללה. ר׳ יהושע מוכיח מ״יצא ניסן וירדו גשמים — סימן קללה״. רבי אומר שההזכרה הולכת עם הבקשה: כשמפסיקים לבקש, מפסיקים גם לשבח.',
'2b:10:3': 'ריב״ב מוצא את האותיות מ׳ י׳ ם׳ בימים השני, השישי והשביעי, ולכן מתחיל מהשני. ר׳ עקיבא מקבל את הרמז, אבל לומד את ניסוך המים מ״ונסכיה״ ביום השישי, ולכן מתחיל אז. בדף ג. הגמרא תשאל למה הוא לא מתחיל כמו ריב״ב.',
'3b:0:0': 'המילים הראשונות בעמוד הן סוף המשפט שהתחיל בדף ג.: ״מאי טעמא [ה׳ לא החזיר את הטל]? משום דלא מיעצר״, כי הטל בכלל לא נעצר.',
'3b:0:1': 'אם הטל לא נעצר (כמו שלמדנו בדף ג.), השבועה של אליהו הנביא ״אם יהיה השנים האלה טל ומטר״ לא הייתה יכולה להתקיים לגבי טל. אז למה הוא כלל אותו בשבועה?',
'3b:0:2': 'התשובה לשאלה ״אליהו אשתבועי למה ליה״: אליהו הנביא לא נשבע על טל רגיל, שבאמת לא נעצר, אלא על ״טל דברכה״, הטל המיוחד שמביא ברכה לתבואה. את זה אפשר לעצור.',
'3b:0:3': 'אם אליהו הנביא עצר ״טל דברכה״, הוא גם היה צריך להחזיר אותו. אבל ה׳ אמר לו רק ״ואתנה מטר״, ולא ״טל״. למה לא הוחזר גם הטל של ברכה?',
'3b:0:4': 'התשובה לשאלה ״ולהדריה לטל דברכה״: רש״י: הטל קיים כל הזמן, ולכן אם הטל של ברכה היה חוזר, אף אחד לא היה מרגיש בזה, ולא היה ניכר שהבצורת נגמרה בזכות אליהו הנביא. רק חזרת הגשם ניכרת.',
'3b:1:0': 'בדף ג. ר׳ חנינא אמר שגם טל וגם רוחות ״אין נעצרין״. על הטל ראינו ראיה מאליהו. עכשיו הגמרא שואלת: ומאיפה יודעים שגם הרוחות לא נעצרות?',
'3b:1:1': 'התשובה לשאלה ״רוחות מנא לן דלא מיעצרי״: ר׳ יהושע בן לוי מביא פסוק מזכריה, ״כי כארבע רוחות השמים פרשתי אתכם נאם ה׳״. הגמרא תשאל מיד איך לומדים מכאן שרוחות לא נעצרות.',
'3b:1:2': 'הגמרא שואלת על הפסוק של ריב״ל (״כארבע רוחות השמים פרשתי אתכם״): מה בעצם ה׳ אומר לישראל בפסוק הזה?',
'3b:1:3': 'הצעה ראשונה לשאלה ״מאי קאמר להו״: אולי ה׳ אומר לישראל ״בדרתינכו בארבע רוחי דעלמא״, פיזרתי אתכם בגלות לכל ארבע רוחות העולם. אם כך, אין בפסוק שום דבר על כך שרוחות לא נעצרות.',
'3b:1:4': 'הגמרא דוחה את ההצעה ״דבדרתינכו בארבע רוחי דעלמא״: אם ה׳ מדבר על פיזור בגלות, היה צריך לכתוב ״בארבע רוחות״, לתוך ארבע הרוחות. אבל כתוב ״כארבע״, כמו ארבע הרוחות, כלומר השוואה.',
'3b:1:5': 'מכיוון שנדחתה ההצעה ״בדרתינכו״, הגמרא מפרשת: ״כארבע רוחות״ הוא השוואה. כשם שהעולם לא יכול להתקיים בלי רוחות (רש״י: מרוב חום והבל), כך הוא לא יכול להתקיים בלי ישראל. ואם העולם לא יכול בלי רוחות, ה׳ אף פעם לא עוצר אותן.',
'3b:2:0': 'ר׳ חנינא מסיק דין מכך שרוחות לא נעצרות: ״הלכך״. מי שטעה בקיץ ואמר ״משיב הרוח״, לא מחזירים אותו לתחילת התפילה, כי הרוח נושבת גם בקיץ, ואין נזק בשבח עליה.',
'3b:2:1': 'ההמשך של ר׳ חנינא (על ימות החמה): מי שאמר בקיץ ״מוריד הגשם״ חוזר לתחילת התפילה. רש״י: גשם בקיץ הוא סימן קללה, ולכן אסור לבקש אותו.',
'3b:2:2': 'ר׳ חנינא עובר לחורף: מי ששכח לומר ״משיב הרוח״ לא חוזר, כי הרוח לא נעצרת בכל מקרה, וההזכרה עליה לא חובה.',
'3b:2:3': 'ההמשך של ר׳ חנינא (על ימות הגשמים): מי ששכח בחורף לומר ״מוריד הגשם״ חוזר לתחילת התפילה, כי הגשם יכול להיעצר, ולכן חובה להזכיר אותו.',
'3b:2:4': 'ר׳ חנינא מוסיף: אפילו מי שאמר ״מעביר הרוח ומפריח הטל״, כאילו ביקש שה׳ יסלק את הרוח והטל, לא חוזר. רש״י: כי ממילא הם לא נעצרים, והתפילה שלו לא משנה כלום.',
'3b:3:0': 'ברייתא נוספת, דומה לזו שבדף ג. (על טל ורוחות): גם על עבים ורוחות חכמים לא חייבו להזכיר בתפילה, ומי שרוצה להזכיר, רשאי.',
'3b:3:1': 'הגמרא שואלת על הברייתא (״בעבים וברוחות לא חייבו להזכיר״): למה לא חייבו?',
'3b:3:2': 'התשובה לשאלה ״מאי טעמא״: כמו בטל, גם עבים ורוחות לא נעצרים, ולכן אין חובה להזכיר אותם.',
'3b:3:3': 'הגמרא מקשה על ״משום דלא מיעצרי״: רב יוסף שנה ברייתא על הפסוק ״ועצר את השמים ולא יהיה מטר״. ״ולא יהיה מטר״ כבר מדבר על הגשם, ולכן ״ועצר את השמים״ צריך ללמד משהו אחר: שה׳ עוצר גם את העבים והרוחות. אז הם כן נעצרים!',
'3b:3:4': 'הגמרא מסכמת את הקושיה של רב יוסף: יש סתירה כפולה בין הברייתות. לגבי רוחות: באחת לא נעצרות, ובשנייה נעצרות. ולגבי עבים: אותו דבר. מיד היא מתרצת כל אחת לחוד.',
'3b:3:5': 'התירוץ לסתירה ״עבים אעבים״: רש״י: ״חרפי״ הם העבים הבכירים, שבאים לפני הגשם, והם לא נעצרים. ״אפלי״ הם העבים המאוחרים, שבאים עם הגשם, ואותם ה׳ עוצר יחד עם הגשם.',
'3b:3:6': 'התירוץ לסתירה ״רוחות ארוחות״: רוח רגילה (״מצויה״) לא נעצרת אף פעם. רוח חזקה ונדירה (״שאינה מצויה״) ה׳ יכול לעצור.',
'3b:3:7': 'הגמרא מקשה על ״הא ברוח שאינה מצויה״: גם רוח חזקה היא ברכה, כי היא נחוצה בגורן (״בי דרי״), כדי לזרות את התבואה ולהפריד בין המוץ לגרעינים. אז למה לעצור אותה?',
'3b:3:8': 'התשובה ל״חזיא לבי דרי״: אפשר להסתדר בלי הרוח החזקה, ולנפות את התבואה בכלי, ״נפוותא״ (רש״י: נפה וכברה). לכן העצירה של רוח כזו לא מזיקה, והיא יכולה להיות עונש.',
'3b:4:0': 'ברייתא חדשה: ״העבים והרוחות שניות למטר״. רש״י: הם מועילים כמעט כמו הגשם עצמו.',
'3b:4:1': 'הגמרא שואלת על הברייתא ״העבים והרוחות שניות למטר״: אילו עבים ורוחות? באיזה מצב הם מועילים כמו גשם?',
'3b:4:2': 'התשובה לשאלה ״היכי דמי״: עולא (ויש אומרים: ר׳ יהודה) אומר: העבים והרוחות שבאים אחרי הגשם. הם עוזרים לאדמה לספוג את המים.',
'3b:4:3': 'הגמרא מקשה על ״דבתר מיטרא״: האם רוח אחרי הגשם היא ברכה? הרי בקללות כתוב ״יתן ה׳ את מטר ארצך אבק ועפר״, ועולא (או רב יהודה) עצמו פירש שזו ״זיקא דבתר מטרא״, רוח אחרי הגשם, שמעלה אבק. אותו אמורא אומר פעם שזו ברכה ופעם שזו קללה!',
'3b:4:4': 'התירוץ לסתירה בדברי עולא: יש שני סוגים של רוח אחרי הגשם. רוח שבאה ״ניחא״, בנחת, מועילה. רוח שבאה ״רויא״, בחוזקה, מזיקה, והיא ה״אבק ועפר״.',
'3b:4:5': 'תירוץ שני לסתירה בדברי עולא: ההבדל הוא באבק. רוח אחרי הגשם שמעלה אבק היא הקללה (״אבק ועפר״). רוח שלא מעלה אבק מועילה, והיא ״שניות למטר״.',
'3b:5:0': 'רב יהודה ממשיך בנושא של מה שבא אחרי הגשם: רוח (״זיקא״) וענן (״עיבא״) אחרי גשם מועילים כמו גשם נוסף. ושמש (״שימשא״) אחרי גשם מועילה כמו שני גשמים, כי היא מחממת את האדמה הרטובה.',
'3b:5:1': 'הגמרא שואלת על דברי רב יהודה (״שימשא דבתר מיטרא כתרי מטרי״): הוא דייק ״דבתר מיטרא״. איזו שמש או איזה מצב הוא בא להוציא?',
'3b:5:2': 'התשובה לשאלה ״למעוטי מאי״: רב יהודה בא להוציא ״גילהי דליליא״, שמיים שמתבהרים בלילה אחרי הגשם, ו״שמשא דביני קרחי״, שמש שמציצה בין העננים. אלה לא מועילים, ואף מזיקים לצמחים.',
'3b:5:3': 'רבא מוסיף: שלג (״תלגא״) על ההרים מועיל כמו חמישה גשמים לאדמה במישור, כי הוא נמס לאט וספוג עמוק באדמה.',
'3b:5:4': 'הראיה של רבא (״תלגא לטורי כחמשה מטרי״): ״כי לשלג יאמר הוא ארץ, וגשם מטר וגשם מטרות עזו״. רבנו חננאל: בפסוק יש ״גשם״, ״מטר״, ״גשם״ ו״מטרות״ (שניים), כלומר חמישה, וכולם נאמרו כנגד השלג.',
'3b:5:5': 'עוד מימרא של רבא: לכל סוג של מים יש תפקיד. שלג טוב להרים, גשם חזק טוב לעצים, וגשם עדין טוב לפירות. המשפט ממשיך בתחילת דף ד.: ״עורפילא — אפילו לפרצידא דתותי קלא מהניא ליה״, הערפל מועיל אפילו לזרע הקבור.',
'3b:6:0': 'זה סיכום של העמוד. הכלל שמאחורי כל הסוגיה: מזכירים ומבקשים בתפילה רק דבר שה׳ יכול לעצור. לכן חובה להזכיר גשם, ולא טל, רוח או עבים, שלא נעצרים.',
'3b:6:1': 'הדברים שלא נעצרים: טל רגיל (ראינו מאליהו), רוח רגילה (״כארבע רוחות השמים״: העולם לא יכול בלעדיהן), ועבים מוקדמים שלפני הגשם.',
'3b:6:2': 'הדברים שכן נעצרים: גשם, ״טל דברכה״ (שאליהו עצר), רוח חזקה (״שאינה מצויה״) ועבים מאוחרים (״אפלי״). זה ״ועצר את השמים״ של רב יוסף.',
'3b:6:3': 'ר׳ חנינא מסיק מכאן את הדין: מי שטעה ברוח או בטל לא חוזר, כי הם לא נעצרים והתפילה עליהם לא משנה. מי שטעה בגשם (הזכיר בקיץ או שכח בחורף) חוזר.',
'4a:0:0': 'זה סוף הרשימה של רבא (שמתחילה בדף ג:) על סוגי הגשם ומה כל אחד מועיל. ״עורפילא״, ערפל או גשם דק מאוד, מגיע ״אפילו לפרצידא דתותי קלא״, לגרעין שקבור מתחת לגוש עפר. רש״י: הגרעין שמתחת לגוש הקשה של הקרקע.',
'4a:0:1': 'הגמרא שואלת על המילה שרבא השתמש בה, ״עורפילא״: מה המשמעות שלה? (בהמשך היא תפרק את המילה לשתיים.)',
'4a:0:2': 'התשובה לשאלה ״מאי עורפילא״: המילה מחולקת לשתיים, ״עורו פילי״, כלומר ״התעוררו, סדקים״. רש״י: הגרעינים שעומדים בסדקי הקרקע. הערפל ״מעורר״ אותם, כך שהם נובטים.',
'4a:0:3': 'מתוך הדימוי של הגרעין הקבור, רבא אומר משהו על ״צורבא מרבנן״, תלמיד חכם צעיר: הוא דומה לגרעין שמתחת לגוש עפר. רש״י: הגרעין מתחיל לאט, אבל ״כיון דנבט — נבט״, ברגע שהוא נובט הוא עולה ומתגדל. כך גם תלמיד החכם: אחרי שהוא ״נובט״, שמו הולך וגדל.',
'4a:0:4': 'עוד מימרא של רבא על ״צורבא מרבנן״: אם הוא ״רותח״, כועס או מתלהט, צריך להבין שזו התורה שבו שמרתיחה אותו. רש״י: יש לו רוחב לב מתוך תורתו, והוא מתלהט יותר משאר בני אדם, ולכן צריך לדון אותו לכף זכות.',
'4a:0:5': 'הראיה לדברי רבא (״אורייתא הוא דקא מרתחא ליה״): בירמיהו כתוב ״הלא כה דברי כאש נאם ה׳״. התורה היא כמו אש, ולכן מי שהיא בתוכו ״מתחמם״ ממנה.',
'4a:1:0': 'רב אשי ממשיך את הקו של רבא (שתלמיד חכם ״רותח״ מתוך התורה): כל תלמיד חכם שאינו קשה כברזל, כלומר תקיף בדעתו ובתורתו ולא מתקפל, אינו תלמיד חכם. רש״י: ״קשה״ — קפדן ותקיף בדבריו.',
'4a:1:1': 'הראיה של רב אשי היא מהמשך אותו פסוק בירמיהו (״הלא כה דברי כאש נאם ה׳״): ״וכפטיש יפוצץ סלע״. דבר ה׳ הוא כמו פטיש שמנפץ סלע, ולכן מי שהתורה בתוכו צריך להיות חזק כמוה.',
'4a:1:2': 'ר׳ אבא מסכים עם רב אשי (שתלמיד חכם צריך להיות קשה כברזל), ומביא מקור אחר: ״אתון מהתם״, אתם בבבל לומדים את זה מ״כפטיש יפוצץ סלע״, ״אנן מהכא״, אנחנו לומדים מ״ארץ אשר אבניה ברזל״. אל תקרא ״אבניה״ אלא ״בוניה״: הבונים של הארץ, תלמידי החכמים (רש״י: שמקיימים את העולם בבנייתו), הם ״ברזל״.',
'4a:1:3': 'רבינא מגביל את מה שנאמר עד עכשיו (רבא: ״אורייתא דקא מרתחא ליה״; רב אשי: ״קשה כברזל״). ״אפילו הכי״, גם אם זה נכון, אדם צריך ״למילף נפשיה בניחותא״, ללמד ולהרגיל את עצמו לדבר ולהתנהג בנחת.',
'4a:1:4': 'הראיה של רבינא (״למילף נפשיה בניחותא״): בקהלת כתוב ״והסר כעס מלבך״. גם תלמיד חכם, שהתורה ״מרתיחה״ אותו, צריך לעבוד על עצמו ולהסיר את הכעס.',
'4a:2:0': 'עכשיו הגמרא מביאה אגדה. אולי היא מובאת כאן כי הדף עוסק ב״שאלה״, בקשה (״שואלין את הגשמים״). ר׳ שמואל בר נחמני אומר בשם ר׳ יונתן: שלושה אנשים ״שאלו שלא כהוגן״, ביקשו או התנו תנאי בלי לחשוב שהוא יכול להתממש בצורה רעה.',
'4a:2:1': 'ההמשך של דברי ר׳ יונתן (״שלשה שאלו שלא כהוגן״): לשניים מהם ה׳ ״השיבום כהוגן״, דאג שהבקשה תתקיים בצורה טובה. ולאחד ״השיבוהו שלא כהוגן״, והבקשה שלו התקיימה בצורה רעה.',
'4a:2:2': 'ר׳ יונתן מונה את השלושה ש״שאלו שלא כהוגן״: אליעזר עבד אברהם אבינו (כשחיפש אישה ליצחק), שאול בן קיש (כשהבטיח את בתו למי שינצח את גלית), ויפתח הגלעדי (כשנדר להקריב את מה שיצא ראשון מביתו). מיד הגמרא מסבירה כל אחד.',
'4a:3:0': 'הראשון מבין השלושה ש״שאלו שלא כהוגן״: אליעזר עבד אברהם אבינו. הוא קבע סימן: הנערה שאומר לה ״הטי נא כדך״ ותשקה גם את הגמלים, היא האישה שה׳ בחר ליצחק.',
'4a:3:1': 'למה הבקשה של אליעזר (״הטי נא כדך״) נקראת ״שלא כהוגן״? כי הסימן שלו היה יכול להתקיים גם בנערה פגועה, צולעת או עיוורת, והוא כבר התחייב לקחת אותה ליצחק. תוספות: לא שהנערה הייתה בהכרח פסולה, אלא שאליעזר לא התנה שתהיה ראויה.',
'4a:3:2': 'התשובה לשאלה ״יכול אפילו חיגרת, אפילו סומא?״: ה׳ ״השיבו כהוגן״. מבחינת התנאי, הייתה יכולה להגיע כל נערה, אבל ה׳ זימן לאליעזר את רבקה, האישה הראויה ליצחק.',
'4a:3:3': 'השני מבין השלושה: שאול המלך. במלחמה בגלית הוא הכריז שמי שיכה את גלית יקבל עושר גדול ואת בתו לאישה, בלי לבדוק מי עלול לנצח.',
'4a:3:4': 'למה ההבטחה של שאול (״ואת בתו יתן לו״) נקראת ״שלא כהוגן״? כי המנצח היה יכול להיות עבד או ממזר, שאסור לו להתחתן עם בת המלך.',
'4a:3:5': 'התשובה לשאלה ״יכול אפילו עבד, אפילו ממזר?״: גם כאן ה׳ ״השיבו כהוגן״. מי שניצח את גלית היה דוד המלך, שהתחתן עם מיכל בת שאול.',
'4a:4:0': 'השלישי מבין השלושה: יפתח הגלעדי. לפני המלחמה בעמון הוא נדר: אם ינצח, ״והיה היוצא אשר יצא מדלתי ביתי לקראתי... והעליתיהו עולה״, את מה שיצא ראשון מהבית שלו יקריב לקרבן.',
'4a:4:1': 'למה הנדר של יפתח (״והיה היוצא אשר יצא מדלתי ביתי״) נקרא ״שלא כהוגן״? כי מה שיצא ראשון היה יכול להיות בעל חיים טמא, כמו כלב או חזיר, שאסור להקריב.',
'4a:4:2': 'התשובה לשאלה ״יכול אפילו דבר טמא?״: אצל יפתח ה׳ ״השיבו שלא כהוגן״. מה שיצא ראשון מהבית היה בתו היחידה, שיצאה לקראתו בתופים ובמחולות.',
'4a:4:3': 'הגמרא מוסיפה: על זה אמר הנביא לישראל ״הצרי אין בגלעד, אם רופא אין שם?״. ״גלעד״ רומז ליפתח הגלעדי. רש״י: פנחס היה שם, והיה יכול להתיר את הנדר, אבל יפתח לא הלך אליו ופנחס לא בא אליו, וכל אחד חיכה שהשני יבוא. ה״צרי״, התרופה, הייתה זמינה.',
'4a:4:4': 'עוד פסוק שקשור ליפתח: בירמיהו ה׳ אומר על שריפת בנים לקרבן ״אשר לא צויתי ולא דברתי ולא עלתה על לבי״. הגמרא מיד מפרשת כל אחד משלושת החלקים על אדם אחר.',
'4a:4:5': 'הפירוש של ״אשר לא צויתי״: זה מישע מלך מואב, שבמלחמה נגד ישראל לקח את בנו הבכור והעלה אותו לעולה על החומה. ה׳ אומר: את זה ״לא ציוויתי״.',
'4a:4:6': 'הפירוש של ״ולא דברתי״: זה יפתח. ה׳ לא אמר לו לנדור כך, וגם לא להקריב את בתו.',
'4a:4:7': 'הפירוש של ״ולא עלתה על לבי״: זה יצחק בן אברהם אבינו. רש״י: אף על פי שה׳ ציווה את אברהם אבינו לעקוד אותו, מעולם לא עלה על ליבו שאברהם ישחט את בנו. זה היה ניסיון בלבד.',
'4a:5:0': 'ר׳ ברכיה מוסיף עוד אחד לרשימה של ר׳ יונתן (״שלשה שאלו שלא כהוגן״): גם כנסת ישראל, עם ישראל כולו, ביקשה בקשה ״שלא כהוגן״, וה׳ ״השיבה כהוגן״, ענה לה בצורה טובה.',
'4a:5:1': 'הבקשה של כנסת ישראל: ״ויבוא כגשם לנו״, שה׳ יבוא אליהם כמו גשם. למה זה ״שלא כהוגן״? הגמרא מיד מסבירה.',
'4a:5:2': 'התשובה של ה׳ לבקשה ״ויבוא כגשם לנו״: ״בתי, את שואלת דבר שפעמים מתבקש ופעמים אינו מתבקש״. גשם לא תמיד רצוי (למשל בקציר או בסוכות). ״אבל אני אהיה לך דבר המתבקש לעולם״, משהו שתמיד רוצים בו.',
'4a:5:3': 'הראיה לתשובה של ה׳ (״אני אהיה לך דבר המתבקש לעולם״): ״אהיה כטל לישראל״. טל, בניגוד לגשם, תמיד רצוי ולא מזיק (וכמו שלמדנו בדף ג., הוא גם לא נעצר).',
'4a:5:4': 'עוד בקשה של כנסת ישראל ״שלא כהוגן״: ״שימני כחותם על לבך כחותם על זרועך״, שה׳ ישים אותה כמו חותם (טבעת) על ליבו ועל זרועו.',
'4a:5:5': 'התשובה של ה׳ לבקשה ״שימני כחותם״: חותם על הלב או על הזרוע לפעמים נראה ולפעמים מכוסה בבגד. ״אבל אני אעשה לך דבר שנראה לעולם״, משהו שתמיד גלוי.',
'4a:5:6': 'הראיה לתשובה של ה׳ (״דבר שנראה לעולם״): ״הן על כפים חקותיך״. ה׳ חקק את ישראל על כפות ידיו, ואת הכפיים תמיד רואים.',
'4a:6:0': 'הגמרא חוזרת למשנה בדף ב.: ״אין שואלין את הגשמים אלא סמוך לגשמים״, את הבקשה ״ותן טל ומטר״ אומרים רק קרוב לזמן שבאמת צריך גשם.',
'4a:6:1': 'בבית המדרש הבינו בהתחלה (״סברוה״) שהמשנה הזו מניחה ש״שאלה והזכרה חדא מילתא היא״: השבח (״משיב הרוח״) והבקשה (״ותן טל ומטר״) הם דבר אחד, ומתחילים את שניהם יחד.',
'4a:6:2': 'אם שאלה והזכרה הן דבר אחד, והמשנה אומרת שמבקשים רק סמוך לגשמים, אז גם השבח מתחיל רק אז. איזה תנא סובר כך? (ר׳ אליעזר הרי מזכיר כבר מתחילת החג.)',
'4a:6:3': 'התשובה של רבא לשאלה ״מאן תנא״: זו שיטת ר׳ יהושע, שאמר (בברייתא) שמתחילים להזכיר ״משעת הנחתו״, מהשעה שמניחים את הלולב, בסוף החג. אצלו גם ההזכרה מתחילה מאוחר, ולכן אפשר לומר שאצלו שאלה והזכרה יחד.',
'4a:6:4': 'אביי חולק על רבא: ״אפילו תימא ר׳ אליעזר״, המשנה יכולה להיות גם של ר׳ אליעזר, שמזכיר מתחילת החג. כי ״שאלה לחוד והזכרה לחוד״: את השבח מתחילים מוקדם, ואת הבקשה רק סמוך לגשמים. כך גם אמר ר׳ אליעזר במשנה: ״לא אמרתי לשאול אלא להזכיר״.',
'4a:6:5': '״ואיכא דאמרי״, יש מי שמוסר את הדיון בנוסח אחר: ״לימא ר׳ יהושע היא...״, אולי המשנה היא של ר׳ יהושע? ורבא (ולא אביי) עונה ״אפילו תימא ר׳ אליעזר״. ההמשך נמצא בתחילת דף ד:, שכבר נמצא באתר.',
'4a:7:0': 'זה סיכום של הדף. כל השלושה (ועוד כנסת ישראל) ביקשו בקשה שהייתה יכולה להתממש בצורה רעה: נערה פגועה, חתן פסול, קרבן טמא, גשם שמזיק. ההבדל ביניהם הוא רק איך ה׳ ענה.',
'4a:7:1': 'אצל אליעזר, שאול וכנסת ישראל, ה׳ ״השיב כהוגן״: הבקשה התקיימה בצורה הטובה ביותר. אצל כנסת ישראל ה׳ אפילו נתן משהו טוב יותר ממה שביקשה: טל במקום גשם, וחקיקה על הכפיים במקום חותם.',
'4a:7:2': 'רק אצל יפתח הבקשה התקיימה בצורה הגרועה ביותר: יצאה בתו. והנביא מוסיף ״הצרי אין בגלעד״: פנחס היה יכול להתיר את הנדר, וכל אחד חיכה שהשני יבוא.',
'4a:7:3': 'רש״י אומר שהאגדה הובאה כאן מתוך ש״שאלת גשמים״ היא בקשה. וכמו ש״ויבוא כגשם לנו״ היא בקשה שלא תמיד רצויה, גם את הגשם מבקשים רק בזמן הנכון: ״אין שואלין את הגשמים אלא סמוך לגשמים״.',
'3a:6:0': 'זה סיכום של העמוד. ניסוך המים לא כתוב בתורה במפורש. כל תנא מוצא לו רמז אחר בפסוקים, ולפי הרמז קובע ממתי להזכיר גשם. אבל בסוף הגמרא אומרת שהדין עצמו, לנסך כל שבעה, הוא ״הלכה למשה מסיני״, מסורת בעל פה.',
'3a:6:1': 'שלושה תנאים מוצאים רמז לניסוך המים: ר׳ יהודה בן בתירה מצרף שלוש אותיות מיותרות ל״מים״, החל מהיום השני. ר׳ עקיבא רואה רמז רק ב״ונסכיה״ של היום השישי. ור׳ נתן לומד מ״הסך נסך״ בקרבן התמיד שיש שני ניסוכים, מים ויין.',
'3a:6:2': 'אף רמז לא מגיע לשבעה ימים: יום אחד, שניים או שישה. לכן הגמרא מסיקה שהדין המלא, לנסך מים כל שבעת ימי החג, ידוע ממסורת: ״עשר נטיעות, ערבה וניסוך המים: הלכה למשה מסיני״.',
'3a:6:3': 'חצי מהעמוד עוסק בזיהוי שמות. ״ר׳ יהושע״ בברייתא הוא לא ״ר׳ יהושע״ של המשנה, כי יש מסורת אחרת בשמו (״משעת הנחתו״). ו״בן בתירה״ הוא לא ר׳ יהודה בן בתירה, אלא ר׳ יהושע בן בתירה, שלפני שנסמך קראו לו בשם אביו.',
'2a:6:0': 'זה סיכום של העמוד. מאחורי המחלוקת בין ר׳ אליעזר לר׳ יהושע עומדת שאלה אחת: מה זו ״הזכרה״? אם היא רק שבח לה׳ על הגשם, אפשר לומר אותה כבר בחג. אם היא קשורה לבקשה, אומרים אותה רק כשבאמת רוצים גשם.',
'2a:6:1': 'לפי ר׳ אליעזר ההזכרה היא שבח עצמאי, ולא בקשה: מספרים בגבורתו של ה׳ שמוריד גשם ״בעונתו״. לכן היא לא סותרת את העובדה שגשם בחג הוא סימן קללה, ואפשר להתחיל כבר ביום הראשון של סוכות.',
'2a:6:2': 'ר׳ יהושע טוען: אם ההזכרה הייתה רק שבח, היו אומרים אותה כל השנה. מכך שיש לה עונה, רואים שהיא קשורה לזמן שבו רוצים גשם, ולכן מתחילים רק ביום טוב האחרון, כשהחג נגמר.',
'2a:6:3': 'הגמרא בהמשך מחזקת את הצד של השבח: הגשם נקרא ״גבורות״, כי הוא יורד בגבורה כמו בריאת העולם (״חקר״ ״חקר״), והוא אחד משלושה ״מפתחות״ שה׳ לא מסר לשליח, יחד עם תחיית המתים. לכן מזכירים אותו בברכה השנייה, ״אתה גבור... מחיה מתים״.',
'2a:0:0': 'זו הפתיחה של מסכת תענית. ״גבורות גשמים״ הן המילים ״משיב הרוח ומוריד הגשם״, שאומרים בברכה השנייה של העמידה, ברכת ״אתה גבור... מחיה מתים״. המשנה שואלת ״מאימתי״, מאיזה יום מתחילים לומר אותן, כאילו כבר ידוע שאומרים אותן. בגמרא (קטע 3) נראה מאיפה זה ידוע.',
'2a:0:1': 'התשובה הראשונה לשאלת המשנה ״מאימתי מזכירין״: ר׳ אליעזר אומר שמתחילים כבר ביום טוב הראשון של סוכות. בעמוד הבא (ב:) הגמרא מבררת מאיפה הוא לומד את זה.',
'2a:0:2': 'התשובה השנייה לשאלת המשנה ״מאימתי מזכירין״: ר׳ יהושע חולק על ר׳ אליעזר. לא מתחילים בתחילת סוכות, אלא ביום טוב האחרון, שמיני עצרת. מיד אחר כך המשנה מביאה את הוויכוח ביניהם: ר׳ יהושע שואל למה להזכיר גשם בתוך החג.',
'2a:0:3': 'ר׳ יהושע מקשה על ר׳ אליעזר, שמתחיל להזכיר כבר ביום הראשון של סוכות. גשם בחג הוא ״סימן קללה״: הוא מכריח לצאת מהסוכה (במשנה במסכת סוכה זה נמשל לעבד שבא למזוג כוס לרבו, ורבו שפך לו את הקיתון על פניו). אז איך אפשר להזכיר גשם בתפילה בדיוק בימים שבהם הוא לא רצוי?',
'2a:0:4': 'התשובה של ר׳ אליעזר לקושיה ״גשם בחג הוא קללה״: יש הבדל בין ״לשאול״, לבקש גשם (״ותן טל ומטר״), לבין ״להזכיר״, לשבח את ה׳ על כוחו להוריד גשם. בחג הוא לא מבקש גשם, הוא רק משבח את ה׳ שמוריד גשם ״בעונתו״, בזמן הנכון. ההבדל הזה בין הזכרה לשאלה מלווה את כל המסכת.',
'2a:0:5': 'ר׳ יהושע דוחה את התשובה של ר׳ אליעזר (״לא אמרתי לשאול אלא להזכיר״): אם ההזכרה היא רק שבח לה׳, ולא בקשה, היה אפשר להזכיר אותה כל השנה! אם קובעים לה זמן, סימן שהיא קשורה לזמן שבו רוצים גשם. ולכן לדעתו מתחילים רק בסוף החג. המשנה לא מביאה תשובה של ר׳ אליעזר.',
'2a:1:0': 'המשנה ממשיכה את ההבדל שר׳ אליעזר עשה בין הזכרה לשאלה. גם מי שמזכיר את הגשם כבר בחג, את הבקשה עצמה, ״ותן טל ומטר״, אומרים רק ״סמוך לגשמים״, בזמן שבאמת צריך גשם. בדף ד: הגמרא תשאל מי אמר את זה, ורבא יענה ״שאלה לחוד והזכרה לחוד״.',
'2a:1:1': 'ר׳ יהודה מדייק את הזמן לפי שני החזנים של יום טוב: ״הראשון״ מתפלל שחרית, ו״האחרון״ מתפלל מוסף. בשמיני עצרת החזן של שחרית עוד לא מזכיר, והחזן של מוסף כבר מזכיר. כלומר מתחילים במוסף. בדף ג. נראה שאת אותם דברים ר׳ יהודה אומר ״משום ר׳ יהושע״.',
'2a:1:2': 'אותו כלל של ר׳ יהודה, הפעם בסוף החורף: ביום הראשון של פסח החזן של שחרית עוד מזכיר ״משיב הרוח״, והחזן של מוסף כבר לא. כלומר מפסיקים במוסף. בדף ד: הגמרא תקשה על זה ממשנה אחרת, שבה ר׳ יהודה אומר ששואלים ״עד שיעבור הפסח״.',
'2a:2:0': 'הגמרא מתחילה בשאלה על המילה הראשונה במשנה: ״מאימתי מזכירין״. שאלה כזו מניחה שכבר ידוע שמזכירים גבורות גשמים, ורק לא ידוע ממתי. איפה זה נאמר קודם? ״תנא היכא קאי״: על איזו משנה התנא ״עומד״, וממנה הוא ממשיך?',
'2a:2:1': 'התשובה הראשונה לשאלה ״תנא היכא קאי״: התנא ממשיך מהמשנה במסכת ברכות (לג.), שם נאמר ״מזכירין גבורות גשמים בתחיית המתים״, כלומר אומרים ״משיב הרוח״ בברכת מחיה המתים, ושואלים ״ותן טל ומטר״ בברכת השנים. שם נאמר שמזכירים, וכאן ממשיכים ושואלים: ממתי?',
'2a:2:2': 'הגמרא דוחה את התשובה ״תנא התם קאי״ (המשך של משנת ברכות): אם המשנה שלנו היא המשך של המשנה בברכות, היה צריך לשאול ״מאימתי מזכירין״ שם, מיד אחריה! למה התנא השאיר את זה עד מסכת תענית?',
'2a:2:3': 'מכיוון שנדחתה התשובה ״תנא התם קאי״ (ברכות), הגמרא עונה אחרת: התנא ״מראש השנה סליק״, כלומר ממשיך את מסכת ראש השנה, שבאה לפני תענית בסדר מועד. שם (ראש השנה טז.) נאמר ״ובחג נידונין על המים״: בסוכות נקבע כמה גשם ירד בשנה. ומתוך שהזכיר שבחג נידונים על המים, המשיך כאן ושאל ממתי מזכירים את הגשם.',
'2a:3:0': 'הגמרא עוברת למילים הבאות במשנה. היה אפשר לכתוב בפשטות ״מאימתי מזכירין על הגשמים״. למה המשנה כותבת ״גבורות גשמים״? מה הקשר בין גשם לגבורה?',
'2a:3:1': 'התשובה לשאלה ״מאי גבורות גשמים״: ר׳ יוחנן אומר שהגשמים יורדים ״בגבורה״, בכוחו הגדול של ה׳. ולכן קוראים להזכרה שלהם ״גבורות גשמים״, ומזכירים אותם בברכת ״אתה גבור״.',
'2a:3:2': 'הראיה של ר׳ יוחנן לכך שהגשם יורד ״בגבורה״: בספר איוב כתוב ״עושה גדולות עד אין חקר״, ובפסוק אחר ״הנותן מטר על פני ארץ״. כלומר נתינת הגשם היא מה״גדולות״ של ה׳, שאין להן ״חקר״, אי אפשר להבין אותן עד הסוף. אבל המילה ״גבורה״ עצמה לא כתובה כאן, ולכן הגמרא תשאל ״מאי משמע?״.',
'2a:3:3': 'הגמרא שואלת על הראיה של ר׳ יוחנן: הפסוקים מדברים על ״גדולות״ ועל ״אין חקר״, אבל לא כתוב בהם ״גבורה״. מאיפה משמע שהגשם יורד דווקא ״בגבורה״?',
'2a:3:4': 'התשובה לשאלה ״מאי משמע״: רבה בר שילא אומר שלומדים בגזירה שווה, ״חקר״ ״חקר״. המילה ״חקר״ מופיעה גם בפסוק על הגשם (״עד אין חקר״) וגם בפסוק על בריאת העולם (״אין חקר לתבונתו״). ובבריאת העולם כתובה ״גבורה״ במפורש, כמו שמיד יראה.',
'2a:3:5': 'זו הגזירה השווה של רבה בר שילא בפירוט: על הגשם כתוב ״עושה גדולות עד אין חקר״. על בריאת העולם כתוב ״בורא קצות הארץ... אין חקר לתבונתו״, ועל הבריאה כתוב גם ״מכין הרים בכחו נאזר בגבורה״. מכיוון שהמילה ״חקר״ משותפת, מה שנאמר בבריאה (״גבורה״) נאמר גם על הגשם. ולכן ״גבורות גשמים״.',
'2a:4:0': 'הגמרא שואלת שאלה חדשה: המשנה בברכות אמרה שמזכירים גשמים בברכת מחיה המתים, כלומר בתפילת העמידה. מאיפה לומדים שהמקום של הגשם הוא דווקא בתפילה?',
'2a:4:1': 'התשובה לשאלה ״ומנא לן דבתפלה״, שלב ראשון: ברייתא דורשת את הפסוק בפרשת ״והיה אם שמוע״: ״לאהבה את ה׳ אלהיכם ולעבדו בכל לבבכם״. איזו עבודה נעשית ״בלב״? לא הקרבת קרבנות, אלא תפילה. מכאן הביטוי ״עבודה שבלב״.',
'2a:4:2': 'השלב השני של התשובה ״ומנא לן דבתפלה״: אחרי ״ולעבדו בכל לבבכם״, שהיא תפילה, הפסוק הבא אומר ״ונתתי מטר ארצכם בעתו יורה ומלקוש״. הסמיכות מלמדת שהגשם קשור לתפילה, ולכן מזכירים אותו בתוך תפילת העמידה.',
'2a:5:0': 'הגמרא מביאה עוד מימרא של ר׳ יוחנן על הגשם. יש שלושה ״מפתחות״ שה׳ לא מסר לשום שליח, ופותח אותם רק בעצמו: גשמים, ״חיה״ (יולדת, פתיחת הרחם) ותחיית המתים. כך מתחבר הגשם לתחיית המתים. במסכת ברכות (לג.) אמרו שהגשם ״שקול כתחיית המתים״, ולכן מזכירים אותו בברכה הזו.',
'2a:5:1': 'הראיה למפתח הראשון, הגשם: ״יפתח ה׳ לך את אוצרו הטוב את השמים לתת מטר ארצך בעתו״. כתוב ״יפתח ה׳״: ה׳ בעצמו פותח את אוצר הגשם, ולא שליח.',
'2a:5:2': 'הראיה למפתח השני, ״חיה״ (לידה): אצל רחל אמנו כתוב ״ויזכר אלהים את רחל וישמע אליה אלהים ויפתח את רחמה״. אלהים עצמו פותח את הרחם. הפסוק נקטע בסוף העמוד, והמשך הרשימה (המפתח של תחיית המתים) נמצא בדף ב:.',
'3a:0:0': 'בעמוד הקודם (ב:) נאמר שר׳ יהודה בן בתירה מוצא רמז לניסוך המים כבר ביום השני של סוכות (״ונסכיהם״, מ׳ נוספת), ולכן הוא מזכיר גשם מהיום השני. ר׳ עקיבא מתחיל מאוחר יותר. הגמרא שואלת: אם ר׳ עקיבא מקבל את הרמז של ר׳ יהודה בן בתירה, שיתחיל כמוהו, מהיום השני!',
'3a:0:1': 'התשובה לשאלה ״אי סבר לה כר׳ יהודה בן בתירה, נימא כוותיה״: ר׳ עקיבא לא מקבל את הרמז מהיום השני. לדעתו ״ניסוך יתירא״, הניסוך הנוסף שרמוז בפסוק, כתוב רק ביום השישי: ״ונסכיה״, בלשון רבים, כלומר שני ניסוכים, יין ומים. ולכן אצלו הרמז לניסוך המים מתחיל ביום השישי.',
'3a:1:0': 'עוד מקור לניסוך המים, בברייתא: ר׳ נתן דורש את הפסוק בקרבן התמיד, ״בקדש הסך נסך שכר לה׳״. יש כאן שתי מילים של ניסוך, ״הסך״ ו״נסך״, ולכן מדובר בשני ניסוכים: אחד של מים ואחד של יין.',
'3a:1:1': 'הגמרא מקשה על הדרשה של ר׳ נתן (״הסך נסך״ = מים ויין): מניין שאחד מהם של מים? אולי הפסוק מדבר על שני ניסוכים, ושניהם של יין?',
'3a:1:2': 'התשובה לקושיה ״אימא תרוייהו דחמרא״: אם שני הניסוכים היו של יין, הפסוק היה חוזר על אותה מילה, ״הסך הסך״ או ״נסך נסך״. מכך שכתוב ״הסך נסך״, שתי מילים שונות, לומדים ששני הניסוכים שונים: אחד של מים ואחד של יין.',
'3a:2:0': 'הגמרא שואלת על המשנה במסכת סוכה: ״ניסוך המים כל שבעה״, מנסכים מים בכל שבעת ימי החג. אבל אף אחת מהדעות שראינו לא מגיעה לשבעה: לפי ר׳ יהושע הרמז הוא ביום אחד, לפי ר׳ עקיבא בשני ימים (השישי והשביעי), ולפי ר׳ יהודה בן בתירה בשישה ימים (מהשני עד השביעי). אז של מי המשנה?',
'3a:2:1': 'התשובה לשאלה ״מני״: המשנה היא של ר׳ יהודה בן בתירה. הוא סובר כמו ר׳ יהודה במשנה בסוכה, שמנסכים מים ״כל שמונה״, כולל שמיני עצרת. ר׳ יהודה בן בתירה ״מוציא את הראשון״, כי אצלו הרמז מתחיל ביום השני, ו״מכניס את השמיני״. מהשני עד השמיני: שבעה ימים.',
'3a:2:2': 'הגמרא דוחה את התשובה (ר׳ יהודה בן בתירה, ״מפיק ראשון ומעייל שמיני״): למה לא מנסכים ביום הראשון? כי הרמז למים מתחיל ביום השני. אבל באותה מידה, הרמז נגמר ביום השביעי (״כמשפטם״), ושמיני עצרת בכלל לא בתוך הרמז. אז אי אפשר להוסיף את השמיני ולהוציא את הראשון.',
'3a:2:3': 'מכיוון שנדחתה התשובה ״ר׳ יהודה בן בתירה״, הגמרא עונה אחרת: המשנה ״ניסוך המים כל שבעה״ היא של ר׳ יהושע. את הרמז בתורה הוא מוצא רק ביום אחד, אבל את הדין, לנסך מים כל שבעה, לומדים ממסורת: ״הלכתא גמירי לה״, הלכה שקיבלו בעל פה.',
'3a:2:4': 'הראיה לכך שניסוך המים ״הלכתא גמירי לה״: ר׳ אמי מביא בשם ר׳ יוחנן, בשם ר׳ נחוניא, שלושה דינים שהם ״הלכה למשה מסיני״, מסורת בעל פה בלי מקור בפסוק: עשר נטיעות (דין בשנה השביעית), הערבה במקדש, וניסוך המים. לכן מנסכים מים כל שבעה, גם אם הרמז בתורה הוא רק ביום אחד.',
'3a:3:0': 'הגמרא מביאה ברייתא: ר׳ יהודה אומר ״משום ר׳ יהושע״, בשם ר׳ יהושע, בדיוק את מה שהוא אמר במשנה בדף ב.: בשמיני עצרת החזן של שחרית (״הראשון״) עוד לא מזכיר, והחזן של מוסף (״האחרון״) כבר מזכיר. ובפסח להפך. כלומר ר׳ יהודה לא אמר את זה מעצמו, אלא בשם ר׳ יהושע.',
'3a:3:1': 'הגמרא שואלת על הברייתא ״ר׳ יהודה משום ר׳ יהושע״: לאיזו דעה של ר׳ יהושע הוא מתכוון? אם לר׳ יהושע של המשנה בדף ב., הוא אמר ״מיום טוב האחרון של חג״, משמע מתחילת היום, כבר בשחרית. ואילו ר׳ יהודה אומר בשמו ״הראשון (שחרית) אינו מזכיר״. זו לא אותה דעה!',
'3a:3:2': 'התשובה לשאלה ״הי ר׳ יהושע״: לא ר׳ יהושע של המשנה, אלא ר׳ יהושע של ברייתא אחרת, שאמר שמתחילים להזכיר ״משעת הנחתו״, מהשעה שמניחים את הלולב. לפי הברייתא ההזכרה קשורה להנחת הלולב, ולא לתחילת היום, ולכן ר׳ יהודה מבין שהיא מתחילה רק במוסף: ״האחרון מזכיר, הראשון אינו מזכיר״.',
'3a:4:0': 'ועוד שאלה מאותו סוג: בברייתא אחרת ר׳ יהודה אומר את אותו דין (״האחרון מזכיר״ בשמיני עצרת), אבל הפעם ״משום בן בתירה״, בשם בן בתירה. מי זה ״בן בתירה״?',
'3a:4:1': 'הגמרא שואלת על ״ר׳ יהודה משום בן בתירה״: מי זה ״בן בתירה״? אם הכוונה לר׳ יהודה בן בתירה, הרי הוא אמר (בדף ב:) שמזכירים כבר ביום השני של החג, כי שם מתחיל אצלו הרמז לניסוך המים. זה לא מתאים ל״האחרון מזכיר״ בשמיני עצרת.',
'3a:4:2': 'התשובה לשאלה ״הי בן בתירה״: רב נחמן בר יצחק אומר שלא מדובר בר׳ יהודה בן בתירה, אלא בחכם אחר ממשפחת בתירה, ר׳ יהושע בן בתירה. הוא זה שאומר ״האחרון מזכיר״.',
'3a:4:3': 'רב נחמן בר יצחק מסביר למה אותו חכם מופיע בשני שמות: לפני שנסמך לרב, קראו לו על שם אביו, ״בן בתירה״; ואחרי שנסמך, קראו לו בשמו, ״ר׳ יהושע בן בתירה״. כך הברייתא ״משום בן בתירה״ היא מלפני הסמיכה, ושתיהן של אותו ר׳ יהושע בן בתירה.',
'3a:5:0': 'הגמרא עוברת לנושא חדש: ברייתא אומרת שעל הטל ועל הרוחות חכמים לא חייבו להזכיר בתפילה, אבל מי שרוצה להזכיר, רשאי. זה בניגוד לגשם, שחייבים להזכיר.',
'3a:5:1': 'הגמרא שואלת על הברייתא (״בטל וברוחות לא חייבו להזכיר״): מה ההבדל בין טל ורוחות לבין גשם? למה על גשם חובה, ועליהם לא?',
'3a:5:2': 'התשובה לשאלה ״מאי טעמא״: ר׳ חנינא אומר שטל ורוחות ״אין נעצרין״, ה׳ אף פעם לא עוצר אותם לגמרי. גשם יכול להיעצר, ולכן חייבים להזכיר אותו. טל ורוח קיימים תמיד, ולכן אין חובה.',
'3a:5:3': 'הגמרא מבקשת מקור לדברי ר׳ חנינא (״לפי שאין נעצרין״): מאיפה יודעים שהטל לא נעצר אף פעם? (על הרוחות הגמרא שואלת בהמשך, בדף ג:.)',
'3a:5:4': 'המקור לכך שהטל לא נעצר: אליהו הנביא נשבע לאחאב שלא יהיה ״טל ומטר״ אלא לפי דבריו. אבל כשה׳ שלח אותו בסוף הבצורת, אמר לו רק ״ואתנה מטר על פני האדמה״, ועל הטל לא אמר כלום. למה לא הבטיח להחזיר גם את הטל? הגמרא מיד תסביר.',
'3a:5:5': 'אליהו הנביא נשבע ״אם יהיה... טל ומטר״, אבל כשה׳ החזיר את הגשם הוא אמר רק ״ואתנה מטר על פני האדמה״, ועל הטל לא נאמר כלום. הגמרא שואלת: מה הטעם? למה הטל לא הוחזר?',
'3a:5:6': 'התשובה לשאלה ״מאי טעמא״: ה׳ לא אמר לאליהו ״ואתנה טל״, כי הטל בכלל לא נעצר, גם בזמן הבצורת. כך מוכח שטל ״לא מיעצר״, ולכן לא חובה להזכיר אותו. המילה האחרונה, ״מיעצר״, נמצאת כבר בעמוד הבא (ג:), ושם הגמרא ממשיכה: אם כך, על מה אליהו הנביא נשבע?',
// ---------- ד׳ ע״ב ----------
'4b:0:0': 'במשנה בדף ב. נאמר ״אין שואלין את הגשמים אלא סמוך לגשמים״, כלומר מבקשים גשם רק קרוב לזמן שהוא באמת צריך לרדת. הגמרא שואלת: איזה תנא אמר את זה? היא מציעה שזה ר׳ יהושע, כי במשנה בדף ב. ר׳ יהושע אמר שמתחילים להזכיר רק ״משעת הנחתו״ של הלולב, כלומר ביום האחרון של החג, ולא בתחילתו. מי שמאחר את ההזכרה, כנראה מאחר גם את הבקשה. אם זה נכון, המשנה היא לא כמו ר׳ אליעזר, שמזכיר כבר מתחילת סוכות.',
'4b:0:1': 'רבא עונה על השאלה ״של מי המשנה״: אין צורך לומר שזו דעת ר׳ יהושע בלבד. אפשר לומר שגם ר׳ אליעזר, שמשבח כבר מהיום הראשון של סוכות, מסכים ש״אין שואלין אלא סמוך לגשמים״. למה? כי ״שאלה לחוד והזכרה לחוד״: לשבח את ה׳ על הגשם אפשר מוקדם, כי אין בזה בקשה. אבל לבקש גשם בפועל מבקשים רק כשהוא באמת צריך לרדת. זה הדבר הראשון שהדף מלמד: שבח ובקשה יכולים להיות בזמנים שונים.',
'4b:0:2': 'זה סיכום של דברי רבא: גם לפי ר׳ אליעזר, שמתחיל לשבח ״משיב הרוח״ כבר בתחילת סוכות, הבקשה ״ותן טל ומטר״ מתחילה רק סמוך לחורף. לכן המשנה ״אין שואלין אלא סמוך לגשמים״ מתאימה לכל התנאים, ולא רק לר׳ יהושע.',
'4b:1:0': 'עכשיו הגמרא עוברת לחלק הבא של המשנה בדף ב., ובו דעת ר׳ יהודה. כדי להבין אותה צריך מונח אחד: ביום טוב מתפללים שחרית ומוסף, ולכל תפילה יש חזן. ״הראשון״ הוא החזן של שחרית, ו״האחרון״ הוא החזן של מוסף. כל השאלה היא באיזו משתי התפילות מתחילים או מפסיקים.',
'4b:1:1': 'זו דעת ר׳ יהודה לגבי תחילת החורף. בשמיני עצרת, החזן של שחרית (״הראשון״) עוד לא אומר ״משיב הרוח״, והחזן של מוסף (״האחרון״) כבר אומר. כלומר: מתחילים לשבח על הגשם בתפילת מוסף של שמיני עצרת. זה המנהג שלנו עד היום.',
'4b:1:2': 'וזו דעת ר׳ יהודה לגבי סוף החורף. ביום הראשון של פסח, החזן של שחרית עוד אומר ״משיב הרוח״, והחזן של מוסף כבר לא אומר. כלומר: מפסיקים לשבח על הגשם בתפילת מוסף של יום ראשון של פסח. שימו לב לנקודה הזאת, כי מיד תבוא עליה סתירה.',
'4b:2:0': 'הגמרא מביאה משנה אחרת, שבמלואה מופיעה בדף ה.: ״עד מתי שואלין את הגשמים? ר׳ יהודה אומר: עד שיעבור הפסח, ר׳ מאיר אומר: עד שיעבור ניסן״. כלומר לפי המשנה הזאת, ר׳ יהודה אומר שממשיכים עד סוף כל חג הפסח. ״ורמינהו״ פירושו ״ומקשים מזה״: הגמרא מעמידה את שתי המשניות זו מול זו.',
'4b:2:1': 'וזו הסתירה עצמה. במשנה בדף ב. אמר ר׳ יהודה שביום הראשון של פסח, כבר במוסף, מפסיקים. במשנה בדף ה. אמר אותו ר׳ יהודה שממשיכים ״עד שיעבור הפסח״, כלומר עד סוף החג. אותו תנא, שני זמנים שונים. מה באמת דעתו? מכאן והלאה, כל קטע בדף הוא ניסיון אחר ליישב את הסתירה הזאת.',
'4b:3:0': 'התירוץ הראשון לסתירה בדברי ר׳ יהודה הוא של רב חסדא: ״כאן לשאול, כאן להזכיר״. המשנה בדף ה., שאומרת ״עד שיעבור הפסח״, מדברת על השאלה, כלומר על הבקשה ״ותן טל ומטר״. את הבקשה ממשיכים עד סוף פסח.',
'4b:3:1': 'החלק השני של תירוץ רב חסדא: המשנה בדף ב., שאומרת ״הראשון מזכיר, האחרון אינו מזכיר״, מדברת על ההזכרה, כלומר על השבח ״משיב הרוח״. את השבח מפסיקים כבר במוסף של יום ראשון של פסח. כך אין סתירה, כי כל משנה מדברת על דבר אחר. אבל יוצא דבר מוזר: בימי חול המועד מבקשים גשם, ולא משבחים עליו. על זה בדיוק יקשה עולא בקטע הבא.',
'4b:4:0': 'עולא דוחה את התירוץ של רב חסדא (״כאן לשאול, כאן להזכיר״) במילים חריפות: ״קשיא כחומץ לשינים וכעשן לעינים״, כלומר זה מכאיב כמו חומץ על השיניים ועשן בעיניים. הוא לא רק לא מסכים, הוא טוען שהתירוץ לא הגיוני בכלל. מיד הוא מסביר למה.',
'4b:4:1': 'עולא בונה קל וחומר נגד רב חסדא. שלב ראשון: תסתכלו על שמיני עצרת. ביום הזה לא מבקשים גשם (כי זה יום טוב, ובקשות לא אומרים ביום טוב), ובכל זאת משבחים ״משיב הרוח״. כלומר: שבח יכול לבוא גם בלי בקשה.',
'4b:4:2': 'שלב שני של הקל וחומר של עולא: אם בשמיני עצרת, שאין בו בקשה, משבחים, אז בחול המועד פסח, שלפי רב חסדא כן מבקשים בו, בוודאי צריך גם לשבח! אי אפשר שיהיה זמן שבו מבקשים גשם אבל לא משבחים עליו. לכן התירוץ של רב חסדא, שבחול המועד מבקשים ולא משבחים, נופל.',
'4b:4:3': 'אחרי שדחה את רב חסדא, עולא נותן תירוץ משלו לסתירה בדברי ר׳ יהודה: ״תרי תנאי אליבא דר׳ יהודה״. כלומר: באמת יש כאן סתירה, ולא צריך ליישב אותה. שני תלמידים של ר׳ יהודה מסרו את דעתו בשתי צורות שונות. אחד אמר בשמו שמפסיקים ביום הראשון של פסח (המשנה בדף ב.), והשני אמר בשמו שממשיכים עד סוף פסח (המשנה בדף ה.).',
'4b:5:0': 'רב יוסף מנסה תירוץ אחר לסתירה בדברי ר׳ יהודה, בלי לומר שיש שתי מסורות. לדבריו, ״עד שיעבור הפסח״ (המשנה בדף ה.) לא פירושו סוף החג, אלא ״עד שיעבור שליח ציבור ראשון של יום טוב ראשון״, כלומר עד שהחזן של שחרית ביום הראשון של פסח יסיים. אם כך, שתי המשניות אומרות אותו דבר: מפסיקים אחרי שחרית של יום ראשון.',
'4b:5:1': 'אביי מקשה על התירוץ של רב יוסף. רב יוסף אמר ש״שואלין״ (מבקשים) עד שחרית של יום טוב ראשון של פסח. אבל ביום טוב בכלל לא אומרים בקשות בתפילה, ואין ״ותן טל ומטר״! אז איזו ״שאלה״ יש בשחרית של יום טוב? אם אין שם בקשה, אי אפשר לומר שהבקשה נמשכת עד אז.',
'4b:5:2': 'רב יוסף עונה לאביי: ״אין, שואל מתורגמן״. כן, יש בקשה ביום טוב, אבל לא בתוך התפילה. המתורגמן, שמסביר לציבור את הדרשה ביום טוב, מבקש בה גם על הגשם. לכן אפשר לומר שהבקשה נמשכת עד שחרית של יום ראשון של פסח.',
'4b:5:3': 'אביי דוחה גם את התשובה הזאת של רב יוסף: ״וכי מתורגמן שואל דבר שאינו צריך לציבור?״. בפסח כבר לא צריך גשם, כי זה זמן הקציר והגשם רק מזיק. ולמה שהמתורגמן יבקש בשם הציבור משהו שהציבור לא צריך? לכן אי אפשר לומר שיש בקשה על גשם ביום טוב של פסח, והתירוץ של רב יוסף נופל.',
'4b:5:4': 'המסקנה אחרי הוויכוח בין רב יוסף לאביי: ״מחוורתא כדעולא״, כלומר הדרך הברורה היא כמו עולא. התירוץ של רב יוסף נדחה, ונשארים עם מה שאמר עולא בקטע הקודם: יש שתי מסורות שונות של דעת ר׳ יהודה (״תרי תנאי״), והסתירה בין המשניות אמיתית.',
'4b:6:0': 'רבה מנסה עוד תירוץ לסתירה בדברי ר׳ יהודה. לדבריו, ״עד שיעבור הפסח״ פירושו ״עד שיעבור זמן שחיטת הפסח״, כלומר עד ערב פסח, כשמקריבים את קרבן הפסח. עד אז מבקשים גשם, ומפסח עצמו כבר לא. כך הבקשה לא נמשכת לתוך החג.',
'4b:6:1': 'החלק השני של תירוץ רבה: ״כתחילתו כן סופו״. ביום הראשון של פסח משבחים (״משיב הרוח״ בשחרית) ולא מבקשים, בדיוק כמו בשמיני עצרת בתחילת החורף, שגם בו משבחים ולא מבקשים. כך שתי המשניות מתיישבות: הבקשה מסתיימת בערב פסח (המשנה בדף ה.), והשבח מסתיים במוסף של יום ראשון (המשנה בדף ב.).',
'4b:6:2': 'אביי מקשה על ״כתחילתו כן סופו״ של רבה. הוא אומר: בתחילת החורף זה מובן. בשמיני עצרת משבחים בלי לבקש, כי השבח הוא ״ריצוי שאלה״, כלומר הכנה וריצוי לפני הבקשה שתבוא מיד אחר כך, בחורף.',
'4b:6:3': 'המשך הקושיה של אביי: בסוף החורף, בפסח, אחרי השבח לא תבוא שום בקשה, כי מפסיקים לבקש. אם השבח הוא הכנה לבקשה, מה הוא מכין? ״סופו מאי ריצוי איכא?״. לכן אין דמיון בין תחילת החורף לסופו, והתירוץ של רבה נופל.',
'4b:7:0': 'עד כאן הגמרא ניסתה להבין את דעת ר׳ יהודה. עכשיו היא עוברת לפסק ההלכה. ר׳ יוחנן פוסק כר׳ יהודה (המשנה בדף ב.): מתחילים לשבח ״משיב הרוח״ כבר בשמיני עצרת. זה פותח דיון חדש: האם הפסק הזה מתיישב עם פסקים אחרים.',
'4b:7:1': 'ר׳ זירא מקשה על הפסק של ר׳ יוחנן. במשנה בדף י. אמר רבן גמליאל שמבקשים גשם רק בז׳ במרחשון, ור׳ אלעזר פסק כמותו. אז איך ר׳ יוחנן פוסק כר׳ יהודה, שמתחילים כבר בשמיני עצרת? נראה ששני פסקים סותרים.',
'4b:7:2': 'התשובה הראשונה לקושיה של ר׳ זירא, מאת ר׳ אסי: ״גברא אגברא קא רמית?״, כלומר אתה מקשה מאדם אחד על אדם אחר? ר׳ יוחנן פסק כר׳ יהודה, ור׳ אלעזר פסק כרבן גמליאל. הם שני אמוראים שונים, ומותר להם לחלוק. אין כאן סתירה, אלא מחלוקת.',
'4b:7:3': 'התשובה השנייה לקושיה של ר׳ זירא, ״איבעית אימא״ (ואם תרצה, אמור): אין בכלל מחלוקת בין הפסקים. ר׳ יהודה (שר׳ יוחנן פסק כמותו) מדבר על ההזכרה, השבח שמתחיל בשמיני עצרת. ורבן גמליאל (שר׳ אלעזר פסק כמותו) מדבר על השאלה, הבקשה שמתחילה בז׳ במרחשון. כלומר, זה שוב ״כאן לשאול, כאן להזכיר״.',
'4b:7:4': 'הגמרא מקשה על התשובה השנייה (״כאן לשאול, כאן להזכיר״). הרי ר׳ יוחנן עצמו אמר ״במקום ששואל — מזכיר״, כלומר כל זמן שמבקשים גשם גם משבחים, והשבח והבקשה הולכים יחד. ואם כך, איך אפשר לומר שר׳ יוחנן פסק להתחיל לשבח בשמיני עצרת, ולבקש רק בז׳ במרחשון?',
'4b:7:5': 'התירוץ לקושיה ״במקום ששואל — מזכיר״: ״ההוא להפסקה איתמר״. הכלל הזה של ר׳ יוחנן נאמר רק על סוף החורף, על ההפסקה: כל זמן שעוד מבקשים גשם, לא מפסיקים לשבח. על תחילת החורף הוא לא אמר כלום, ולכן אפשר להתחיל לשבח בשמיני עצרת ולבקש רק בז׳ במרחשון.',
'4b:7:6': 'הגמרא מקשה קושיה חזקה יותר. ר׳ יוחנן אמר במפורש גם על תחילת החורף: ״התחיל להזכיר — מתחיל לשאול״, כלומר מי שהתחיל לשבח מתחיל באותו זמן גם לבקש. אם כך, לפי ר׳ יוחנן אי אפשר לשבח משמיני עצרת ולבקש רק מז׳ במרחשון. התשובה ״כאן לשאול, כאן להזכיר״ נופלת.',
'4b:7:7': 'התירוץ לקושיה: ״הא לן, הא להו״, כלומר זה לנו וזה להם. ר׳ יוחנן, שאמר שמתחילים יחד ומוקדם (כר׳ יהודה), דיבר על ארץ ישראל. ורבן גמליאל, שאמר לבקש רק בז׳ במרחשון, דיבר על בבל (״להו״). כך אין סתירה: בכל מקום משבחים ומבקשים יחד, אבל בכל מקום בזמן אחר.',
'4b:7:8': 'הגמרא מקשה על ״הא לן, הא להו״. מבינים למה בבבל מאחרים: ״דאית לן פירי בדברא״, הפירות עוד בשדה בתחילת החורף, וגשם יזיק להם. אבל גם בארץ ישראל יש סיבה לאחר: עולי הרגלים, שחזרו מירושלים אחרי סוכות. צריך לחכות שהאחרון שבהם, שגר ליד נהר פרת, יגיע לביתו בלי גשם בדרך. זו בדיוק הסיבה של רבן גמליאל לחכות עד ז׳ במרחשון.',
'4b:7:9': 'התירוץ האחרון: ר׳ יוחנן, שפסק להתחיל מיד בשמיני עצרת, דיבר על ״בזמן שאין בית המקדש קיים״. כשאין מקדש אין עולי רגלים, ואין סיבה לחכות. ורבן גמליאל, שאמר לחכות עד ז׳ במרחשון, דיבר על זמן המקדש. כך כל הקושיות של ר׳ זירא מתיישבות: המחלוקת היא לפי הזמן, ולא באמת מחלוקת.',
'4b:8:0': 'עכשיו הגמרא שואלת שאלה מעשית על חוץ לארץ (״ואנן״, ואנחנו בבבל). בגולה עושים שני ימים טובים, כי לא תמיד ידעו מתי קבעו את החודש. לכן היום הראשון של שמיני עצרת הוא אולי בעצם היום השביעי של סוכות. אם מתחילים בו לשבח ״משיב הרוח״, אולי משבחים על הגשם עוד בסוכות. אז מה עושים?',
'4b:8:1': 'רב עונה על שאלת שני הימים בחוץ לארץ: מתחילים לשבח במוסף של היום הראשון, כי אולי הוא שמיני עצרת. מפסיקים במנחה, בערבית ובשחרית, כי אולי היום הראשון היה בעצם סוכות. וחוזרים לשבח במוסף של היום השני, ומשם ממשיכים.',
'4b:8:2': 'שמואל צוחק על השיטה של רב: ״אחר שעשיתו קודש תעשהו חול?!״. כלומר: במוסף התנהגת כאילו היום הוא שמיני עצרת (״קודש״, וזמן השבח), ובמנחה של אותו יום תתנהג כאילו הוא עוד סוכות (״חול״, בלי שבח)? אי אפשר להחליט שני דברים סותרים על אותו יום.',
'4b:8:3': 'השיטה של שמואל לשני הימים בחוץ לארץ: מתחילים לשבח במוסף של היום הראשון וממשיכים גם במנחה, כי זה אותו יום ולא מתהפכים באמצעו. מפסיקים רק בערבית ובשחרית של היום השני, וחוזרים במוסף של היום השני.',
'4b:8:4': 'למה גם שמואל מפסיק בערבית ובשחרית של היום השני? כי אם היום השני הוא שמיני עצרת האמיתי, השבח צריך להתחיל בו במוסף, כמו שאמר ר׳ יהודה. ההפסקה בתפילות הלילה והבוקר יוצרת ״התחלה״ במקום הנכון. ההכרעה הסופית בשאלה הזאת תבוא בתחילת דף ה.',
'4b:9:0': 'זה סיכום (שלי) של כל הדף. מאחורי כל התירוצים עומדת שאלה אחת: מה זו ההזכרה, ״משיב הרוח״? האם היא שבח שעומד בפני עצמו, שאפשר לומר בלי בקשה? או שהיא רק הקדמה לבקשה, ולכן הולכת רק יחד איתה? כל אמורא בדף עונה על כך בדרך אחרת.',
'4b:9:1': 'רבא (בתחילת הדף) אמר ״שאלה לחוד והזכרה לחוד״. מבחינתו השבח עומד בפני עצמו: אפשר לשבח בלי לבקש, ולכן מותר להתחיל לשבח מוקדם.',
'4b:9:2': 'עולא (בדחייה של רב חסדא) אמר שבמקום שמבקשים, ודאי משבחים. מבחינתו השבח הוא המינימום: אולי אפשר לשבח בלי בקשה, אבל אי אפשר לבקש בלי לשבח.',
'4b:9:3': 'אביי (בקושיות על רב יוסף ועל רבה) ראה בשבח ״ריצוי שאלה״, כלומר הכנה לבקשה. בלי בקשה אחריו אין לו טעם. והוא גם אמר שתפילה היא רק על מה שהציבור באמת צריך.',
'4b:9:4': 'ר׳ יוחנן אמר ״התחיל להזכיר — מתחיל לשאול״ ו״במקום ששואל — מזכיר״. מבחינתו השבח והבקשה קשורים זה בזה, גם בתחילת החורף וגם בסופו.',
// ---------- ה׳ ע״א ----------
'5a:0:0': 'זה ההמשך של השאלה מסוף דף ד:, מה עושים בחוץ לארץ, שבה יש שני ימים של שמיני עצרת. רב אמר להפסיק ולחזור, ושמואל אמר להפסיק רק בערבית ושחרית. עכשיו רבא ורב ששת פוסקים אחרת משניהם: ״כיון שהתחיל — שוב אינו פוסק״. מתחילים לשבח במוסף של היום הראשון, ולא מפסיקים יותר בכלל.',
'5a:0:1': 'גם רב, שבדף ד: אמר להפסיק במנחה ולחזור, חזר בו. רב חננאל מביא שרב היה סופר 21 יום מראש השנה, כמו שעשרת הימים עד יום כיפור, ועוד 11 עד שמיני עצרת. ביום ה־21 התחיל לשבח ולא הפסיק. כלומר גם רב הגיע לשיטת ״כיון שהתחיל — שוב אינו פוסק״.',
'5a:0:2': 'למה לא חוששים שהיום הראשון הוא בעצם סוכות? רש״י מסביר: ״אנן בקיאין בקביעא דירחא״, אנחנו יודעים בדיוק מתי קבעו את החודש. היום השני בחוץ לארץ הוא רק מנהג, ולכן היום הראשון הוא באמת שמיני עצרת, ואין סיבה להפסיק.',
'5a:0:3': 'זה פסק ההלכה הסופי לשאלה שנפתחה בדף ד: על שני הימים: ״והלכתא — כיון שהתחיל, שוב אינו פוסק״. מתחילים לשבח במוסף של שמיני עצרת (היום הראשון), וממשיכים בלי הפסקה. כך נוהגים גם היום.',
'5a:1:0': 'כאן מתחילה במלואה המשנה שהגמרא הביאה כבר בדף ד: (״ורמינהו״): ״עד מתי שואלין את הגשמים?״. כלומר: עד מתי מבקשים ״ותן טל ומטר״ בסוף החורף? ר׳ יהודה אומר: עד שיעבור הפסח.',
'5a:1:1': 'ר׳ מאיר במשנה חולק על ר׳ יהודה: מבקשים עד סוף חודש ניסן. הראיה שלו מהפסוק ביואל: ״ויורד לכם גשם מורה ומלקוש בראשון״. ״בראשון״ פירושו בחודש הראשון, ניסן. כלומר גם בניסן יכול לרדת גשם טוב, ולכן ממשיכים לבקש כל החודש. על הפסוק הזה תבוא מיד קושיה.',
'5a:2:0': 'רב נחמן מקשה על הראיה של ר׳ מאיר מהפסוק ״מורה ומלקוש בראשון״. הפסוק אומר שגם ה״מורה״ (היורה, הגשם הראשון של החורף) וגם המלקוש (הגשם האחרון) יורדים בניסן. אבל היורה יורד במרחשון, בתחילת החורף, ולא בניסן! איך הפסוק אומר שגם הוא בא ״בראשון״?',
'5a:2:1': 'תוספות מחדדים את הקושיה של רב נחמן. זה שהמלקוש, הגשם האחרון, יורד בניסן מובן, כי זה סוף החורף. הקושי הוא רק על ה״מורה״, היורה, שבדרך כלל יורד במרחשון. איך הוא נכלל ב״בראשון״?',
'5a:3:0': 'ר׳ יצחק עונה על הקושיה ״יורה בניסן?!״. הפסוק לא מתאר את הסדר הרגיל של כל שנה. הוא מתאר שנה אחת מיוחדת, בימי הנביא יואל בן פתואל, שבה היו ארבה ורעב. באותה שנה באמת ירד גם היורה בניסן.',
'5a:3:1': 'כך ר׳ יצחק מתאר את אותה שנה בימי יואל. כל החורף עבר בלי גשם, ״יצא אדר ולא ירדו גשמים״. הגשם הראשון של השנה, היורה, ירד רק בא׳ בניסן. לכן הפסוק יכול לומר שהיורה ירד ״בראשון״, בניסן.',
'5a:3:2': 'אחרי הגשם הראשון בא׳ בניסן, הנביא יואל אמר לעם ״צאו וזרעו!״. למרות שכבר מאוחר מאוד בשנה, ואין הרבה תבואה, צריך לזרוע.',
'5a:3:3': 'העם עונה לנביא בשאלה קשה: ״מי שיש לו קב חיטין או שני קבין יאכלנו ויחיה, או יזרענו וימות?״. נשאר לנו מעט מאוד אוכל. אם נאכל אותו, נחיה עוד קצת. אם נזרע אותו, לא יהיה לנו מה לאכול עד שהתבואה תגדל.',
'5a:3:4': 'הנביא עונה ״אף על פי כן — צאו וזרעו!״. כלומר: גם אם זה נראה מסוכן, לכו לזרוע. זה מבחן של אמונה: לתת את האוכל האחרון לאדמה ולסמוך על ה׳.',
'5a:4:0': 'בגלל שהם זרעו באמונה, נעשה להם נס: ״נעשה להם נס ונתגלה להם מה שבכתלים ומה שבחורי נמלים״. הם מצאו תבואה שהנמלים אגרו בחורים שלהן ובכתלים. כך היה להם גם לאכול וגם לזרוע.',
'5a:4:1': 'הגמרא מפרטת את לוח הזמנים של הנס בימי יואל. הגשם הראשון ירד בא׳ בניסן, ובימים ב׳, ג׳ וד׳ בניסן הם יצאו וזרעו.',
'5a:4:2': 'בה׳ בניסן, אחרי הזריעה, ירדה ״רביעה שנייה״, כלומר גשם שני. זה המלקוש, שמשקה את מה שנזרע.',
'5a:4:3': 'בט״ז בניסן, היום השני של פסח, מקריבים את העומר מהתבואה החדשה. באותה שנה הקריבו אותו מהתבואה שנזרעה רק בב׳ עד ד׳ בניסן!',
'5a:4:4': 'זה הנס: ״נמצאת תבואה הגדלה בששה חדשים — גדלה באחד עשר יום״. תבואה שבדרך כלל צריכה חצי שנה כדי לגדול, גדלה תוך 11 יום, מהזריעה ועד הקרבת העומר.',
'5a:4:5': 'וזה מיישב את הקושיה של רב נחמן מתחילת הקטע (״יורה בניסן?!״). באותה שנה בימי יואל, היורה (הגשם הראשון) ירד בא׳ בניסן, והמלקוש ירד בה׳ בניסן. לכן הפסוק ״מורה ומלקוש בראשון״ מדויק: שניהם ירדו בניסן.',
'5a:5:0': 'הגמרא ממשיכה לספר על אותו דור של יואל, ומביאה עליו פסוק מתהלים: ״הלוך ילך ובכה נושא משך הזרע, בא יבוא ברנה נושא אלומותיו״. מי שהלך לזרוע בבכי, כי נתן את האוכל האחרון, חזר בשמחה עם אלומות תבואה.',
'5a:5:1': 'הגמרא שואלת על הפסוק ״הלוך ילך ובכה״: על מי הוא מדבר? רש״י מסביר שעל בני האדם כבר נאמר בפסוק הקודם ״הזורעים בדמעה״. אז ״הולך ובוכה״ צריך לדבר על מישהו אחר.',
'5a:5:2': 'ר׳ יהודה עונה: הפסוק מדבר על השור. בדרך לחרוש הוא הולך ובוכה, כי הוא רעב. ובדרך חזרה הוא כבר אוכל מהצמח שעלה בתלם, ״אוכל חזיז מן התלם״. כל כך מהר צמחה התבואה, עוד באותו יום. זה עוד תיאור של הנס.',
'5a:5:3': 'הגמרא ממשיכה לפרש את הפסוק ״הלוך ילך ובכה... בא יבוא ברנה נושא אלומותיו״. על החלק הראשון ענה ר׳ יהודה (השור). עכשיו היא שואלת על הסוף: מה פירוש ״נושא אלומותיו״?',
'5a:5:4': 'התשובה לשאלה ״מאי נושא אלומותיו״: רב חסדא (ויש אומרים שזו ברייתא) מסביר: ״קנה זרת, שיבולת זרתיים״. הקנה (הגבעול) היה באורך זרת, והשיבולת עצמה באורך שתי זרתות, פי שניים מהקנה. בדרך כלל זה הפוך. זה מראה שפע עצום של תבואה.',
'5a:5:5': 'תוספות מקשים על החשבון של ״11 יום״: אם התבואה צמחה כבר ביום הזריעה (השור אכל ממנה בדרך חזרה), למה סופרים 11 יום ולא 13, מא׳ בניסן? התירוץ של תוספות לא קריא בצילום, ולכן הוא לא מובא כאן.',
'5a:6:0': 'עכשיו מתחילה סדרה של שאלות שרב נחמן שאל את ר׳ יצחק על פסוקים קשים. כל תשובה היא ״הכי אמר ר׳ יוחנן״. השאלה הראשונה על הפסוק במלכים ״כי קרא ה׳ לרעב, וגם בא אל הארץ שבע שנים״: בשבע שנות הרעב, מה אנשים אכלו?',
'5a:6:1': 'ר׳ יוחנן עונה: בכל שנה של הרעב הם ירדו מדרגה במה שאכלו. בשנה הראשונה אכלו מה שבבתים, ובשנה השנייה מה שבשדות. אחר כך אכלו בשר בהמות טהורות, ואחר כך בשר בהמות טמאות. בשנה השישית אכלו שקצים ורמשים, ובשביעית ״איש בשר זרועו יאכלו״. הרעב רק החמיר, כי לא חזרו בתשובה.',
'5a:7:0': 'השאלה הבאה של רב נחמן לר׳ יצחק, על הפסוק בהושע ״בקרבך קדוש, ולא אבוא בעיר״. הפסוק נשמע לא הגיוני: וכי בגלל שה׳ נמצא בקרבנו, הוא לא יבוא לעיר? ״משום דבקרבך קדוש לא אבוא בעיר?!״',
'5a:7:1': 'ר׳ יוחנן מפרש את ״לא אבוא בעיר״: ״לא אבוא בירושלים של מעלה עד שאבוא לירושלים של מטה״. כלומר, ה׳ לא ״ייכנס״ לירושלים שבשמיים עד שתיבנה מחדש ירושלים שבארץ. ״העיר״ בפסוק היא ירושלים של מעלה.',
'5a:7:2': 'הגמרא שואלת על התשובה של ר׳ יוחנן: וכי יש בכלל ״ירושלים של מעלה״? מאיפה יודעים שיש ירושלים בשמיים?',
'5a:7:3': 'התשובה: מהפסוק בתהלים ״ירושלים הבנויה כעיר שחוברה לה יחדיו״. ירושלים בנויה ״כעיר שחוברה לה״, כלומר יש עיר אחרת שמחוברת אליה ודומה לה. זו ירושלים של מעלה.',
'5a:7:4': 'תוספות מביאים פירוש אחר לפסוק ״ולא אבוא בעיר״: המילה ״עיר״ קשורה ל״עָר״, אויב (כמו ״ערך״ בשמואל). כלומר ״לא אבוא בשנאה״: ה׳ אומר שלא יבוא אל עמו בשנאה ובכעס.',
'5a:8:0': 'השאלה הבאה של רב נחמן לר׳ יצחק, על הפסוק בירמיהו ״ובאחת יבערו ויכסלו, מוסר הבלים עץ הוא״. מה פירוש ״באחת״? מהו הדבר האחד שבגללו הרשעים ״יבערו״, כלומר יישרפו?',
'5a:8:1': 'ר׳ יוחנן עונה: ״אחת המבערת רשעים בגיהנם — זו עבודה זרה״. הדבר האחד ששורף את הרשעים הוא עבודה זרה.',
'5a:8:2': 'איך יודעים שה״אחת״ היא עבודה זרה? מגזירה שווה של המילה ״הבל״. כאן כתוב ״מוסר הבלים עץ הוא״, ובפסוק אחר בירמיהו כתוב על פסלים ״הבל המה, מעשה תעתועים״. כמו ששם ״הבל״ הוא עבודה זרה, כך גם כאן.',
'5a:9:0': 'השאלה האחרונה בדף, על הפסוק בירמיהו ״כי שתים רעות עשה עמי״. רב נחמן שואל: ״שתים רעות״? רק שתי עבירות? וכי זה כל מה שעשו?',
'5a:9:1': 'רש״י מסביר את הקושיה: ביחזקאל פרק כ״ב מונה הנביא 24 עבירות שעשה העם. אז איך ירמיהו אומר שהם עשו רק שתי רעות?',
'5a:9:2': 'התשובה של ר׳ יוחנן מתחילה בסוף הדף וממשיכה בתחילת דף ה:. הרעיון: זו לא רשימה של שתי עבירות, אלא עבירה אחת (עבודה זרה) ששקולה כשתיים.',
'5a:10:0': 'זה ביאור שלי, לא מהגמרא. כל הדרשות בסוף הדף (יואל, שבע שנות רעב, ירושלים, ״ובאחת יבערו״, ״שתים רעות״) עוסקות באותו רעיון: השפע שיורד מלמעלה, גשם, תבואה ושכינה, תלוי במה שאנחנו עושים למטה.',
'5a:10:1': 'במעשה על יואל: קודם העם זרע באמונה את האוכל האחרון, ורק אחר כך ירד הגשם והתבואה גדלה בנס.',
'5a:10:2': 'בשבע שנות הרעב: כשלא חזרו בתשובה, המצב רק הלך והתדרדר משנה לשנה.',
'5a:10:3': 'בדרשה על ירושלים: קודם צריך לבנות את ירושלים למטה, ורק אחר כך ה׳ ״בא״ לירושלים של מעלה.',
'5a:10:4': 'בדרשות ״ובאחת יבערו״ ו״שתים רעות״: מה שחוסם את השפע הוא עבודה זרה, כלומר עזיבת ה׳, ״מקור מים חיים״.',
// ---------- ה׳ ע״ב ----------
'5b:0:0': 'זו התשובה של ר׳ יוחנן לשאלה מסוף דף ה. על ״כי שתים רעות עשה עמי״: למה רק שתיים, אם ביחזקאל מנויות 24 עבירות? ר׳ יוחנן עונה: הנביא לא מונה שתי עבירות. הוא מדבר על עבירה אחת, עבודה זרה, ששקולה כשתיים.',
'5b:0:1': 'למה עבודה זרה שווה לשתיים? ההמשך של אותו פסוק מסביר: ״אותי עזבו מקור מים חיים, לחצוב להם בארות בארות נשברים״. הרעה הראשונה היא שעזבו את ה׳, ״מקור מים חיים״. והרעה השנייה היא שהחליפו אותו בבור שבור, שאין בו מים. כלומר באלילים שאין בהם ממש.',
'5b:0:2': 'ר׳ יוחנן מביא עוד פסוק מירמיהו, שמראה כמה זה חמור: ״כי עברו איי כתיים וראו, וקדר שלחו והתבוננו... ההימיר גוי אלהים, והמה לא אלהים?״. לכו לאיים של כתים ולקדר, ובדקו: האם אי פעם עם החליף את האלים שלו, אפילו אם הם לא אלים? ״ועמי המיר כבודו בלא יועיל״: רק עמי החליף את ה׳ האמיתי.',
'5b:0:3': 'ברייתא (״תנא״) מסבירה את הדוגמה בפסוק: הכתיים עובדים לאש, והקדריים עובדים למים.',
'5b:0:4': 'הנקודה של הברייתא: הקדריים, שעובדים למים, יודעים שמים מכבים אש. כלומר הם יודעים שהאל של הכתיים חלש. ובכל זאת הכתיים לא החליפו את האל שלהם. אז אם הגויים לא מחליפים אפילו אל שהם יודעים שהוא חלש, ישראל החליפו את ה׳, שהוא באמת מקור החיים! לכן זו ״אחת ששקולה כשתיים״.',
'5b:1:0': 'עוד שאלה של רב נחמן לר׳ יצחק, על הפסוק ״ויהי כאשר זקן שמואל״. לפי החשבון, שמואל הנביא נפטר בגיל 52 בלבד. איך אפשר לקרוא לגיל 52 ״זקן״?',
'5b:1:1': 'ר׳ יוחנן עונה: ״זקנה קפצה עליו״, הזקנה הגיעה אליו פתאום ומוקדם. זה קרה מהצער, מאז שה׳ אמר ״נחמתי כי המלכתי את שאול״. כך שמואל נראה זקן בגיל צעיר יחסית.',
'5b:1:2': 'תוספות מסבירים איך מגיעים לגיל 52 של שמואל, לפי ״סדר עולם״. סופרים את שנות עלי ושמואל עד המלכת שאול, ואת שנות מלכות שאול עד פטירת שמואל. יוצא ששמואל לא הגיע לגיל זקנה רגיל, ולכן צריך את ההסבר ״זקנה קפצה עליו״.',
'5b:2:0': 'הגמרא מסבירה למה ״קפצה עליו זקנה״. שמואל התפלל: ״רבונו של עולם, שקלתני כמשה ואהרן״. משה רבינו ואהרן לא ראו את מעשיהם בטלים בחייהם. אז גם אני לא אראה את מעשה ידי בטל בחיי. כלומר: שאול, שאני המלכתי, לא יודח כל עוד אני חי.',
'5b:2:1': 'אחרי תפילת שמואל, ה׳ כביכול שואל ״היכי אעביד?״: מה אעשה? כבר הוחלט שהמלכות תעבור משאול לדוד, ושמואל ביקש שזה לא יקרה בחייו. הגמרא בוחנת את האפשרויות.',
'5b:2:2': 'האפשרות הראשונה: שאול ייפטר עכשיו. אבל שמואל לא רוצה, כי אז מעשה ידיו, המלכת שאול, ייבטל בחייו. זה בדיוק מה שהוא ביקש שלא יקרה.',
'5b:2:3': 'האפשרות השנייה: שמואל ייפטר צעיר, לפני שהמלוכה תעבור לדוד. אבל אז ״ירננו אחריו״, אנשים יגידו שנפטר צעיר בגלל שחטא. זה יפגע בכבודו.',
'5b:2:4': 'האפשרות השלישית: שאף אחד מהם לא ייפטר, ושניהם ימשיכו. אבל גם זה אי אפשר. ״כבר הגיע מלכות דוד, ואין מלכות נוגעת בחברתה אפילו כמלא נימא״: הזמן של דוד המלך כבר הגיע, ושתי מלכויות לא יכולות לחפוף אפילו כרוחב שערה.',
'5b:2:5': 'הפתרון של ה׳ לשלוש האפשרויות: ״אקפיץ עליה זקנה״. שמואל יזדקן מהר. כך כשייפטר, בגיל 52, כולם יחשבו שנפטר מזקנה ולא בגלל חטא. ושאול ימשיך למלוך עד אז, כך שמעשה ידיו של שמואל לא ייבטל בחייו. זה עונה על השאלה מתחילת הקטע: למה שמואל נקרא ״זקן״ בגיל 52.',
'5b:2:6': 'הגמרא מביאה רמז בפסוק: ״ושאול יושב בגבעה... ברמה״. שאול ישב בגבעה, ולמה הפסוק מזכיר את ״הרמה״? כי שמואל הרמתי גר ברמה. כלומר, מה שהשאיר את שאול על כס המלכות עוד שנתיים וחצי היה התפילה של שמואל מהרמה.',
'5b:3:0': 'הגמרא שואלת על המעשה של שמואל ושאול: ״ומי מידחי גברא מקמי גברא?״. וכי אדם אחד נדחה, או נשאר בחיים, בגלל אדם אחר? איך יכול להיות שגורלו של שאול נקבע לפי תפילת שמואל?',
'5b:3:1': 'ר׳ יונתן עונה: כן. כתוב ״הרגתים באמרי פי״. לא כתוב ״במעשיהם״ (בגלל מעשיהם), אלא ״באמרי פי״, בגלל דברי הנביאים. כלומר, דברי הנביא יכולים להשפיע על מה שקורה לאחרים. כך תפילת שמואל השפיעה על מלכות שאול.',
'5b:4:0': 'מתחיל מעשה חדש: רב נחמן ור׳ יצחק ישבו יחד בסעודה. כאן לא מדובר בשאלה על פסוק, אלא בשיחה ביניהם.',
'5b:4:1': 'רב נחמן ביקש מר׳ יצחק: ״לימא מר מילתא״, שיגיד דבר תורה תוך כדי האוכל.',
'5b:4:2': 'ר׳ יצחק סירב לבקשה של רב נחמן ואמר בשם ר׳ יוחנן: ״אין משיחין בסעודה, שמא יקדים קנה לושט ויבא לידי סכנה״. לא מדברים בזמן האכילה, כי האוכל עלול להיכנס לקנה הנשימה במקום לוושט.',
'5b:4:3': 'אחרי שסיימו לאכול, ר׳ יצחק אמר את דבר התורה שרב נחמן ביקש: ״כך אמר ר׳ יוחנן: יעקב אבינו לא מת״.',
'5b:4:4': 'רב נחמן מקשה על ״יעקב אבינו לא מת״: ״וכי בכדי ספדו ספדנייא וחנטו חנטייא וקברו קברייא?״. הרי בתורה כתוב שהספידו את יעקב אבינו, חנטו אותו וקברו אותו! וכי עשו את כל זה לחינם?',
'5b:4:5': 'ר׳ יצחק עונה: ״מקרא אני דורש״. הפסוק אומר ״ואתה אל תירא עבדי יעקב... כי הנני מושיעך מרחוק ואת זרעך״. הפסוק משווה את יעקב אבינו לזרעו: ״מה זרעו בחיים, אף הוא בחיים״. יעקב אבינו ״חי״ דרך צאצאיו שממשיכים את דרכו, גם אם גופו נקבר.',
'5b:5:0': 'עוד דבר שר׳ יצחק אמר: ״כל האומר רחב רחב — מיד נקרי״. רחב, האישה מיריחו שהסתירה את המרגלים, הייתה מפורסמת ביופיה. מי שאומר את שמה פעמיים מיד מגיע למחשבות לא טהורות (״נקרי״).',
'5b:5:1': 'רב נחמן מקשה על ר׳ יצחק מניסיון אישי: ״אנא אמינא רחב רחב, ולא איכפת לי״. אני אומר ״רחב רחב״, ולא קורה לי כלום.',
'5b:5:2': 'ר׳ יצחק עונה לרב נחמן: ״ביודעה ובמכירה״. מה שאמרתי נכון רק במי שהכיר אותה באמת וראה אותה. מי שלא הכיר אותה, כמו רב נחמן, לא מושפע מהשם.',
'5b:6:0': 'זה ביאור שלי, לא מהגמרא. בעמוד הזה יש שלושה מעשים: שמואל, יעקב אבינו והאילן. כולם עונים על שאלה אחת: מה ממשיך לחיות אחרי האדם?',
'5b:6:1': 'אצל שמואל: הוא ביקש שמעשה ידיו, המלכת שאול, לא ייבטל בחייו. מה שהוא בנה ממשיך.',
'5b:6:2': 'אצל יעקב אבינו: ״מה זרעו בחיים, אף הוא בחיים״. הוא ממשיך לחיות דרך הצאצאים שלו.',
'5b:6:3': 'במשל האילן, בסוף העמוד: הברכה הגדולה ביותר היא שהנטיעות, הדור הבא, יהיו כמותך.',
'5b:7:0': 'רב נחמן ור׳ יצחק נפרדים בסוף הסעודה. רב נחמן מבקש: ״ליברכן מר״, שר׳ יצחק יברך אותו.',
'5b:7:1': 'ר׳ יצחק עונה לבקשה של רב נחמן בעזרת משל. אדם הולך במדבר, רעב, עייף וצמא, ומוצא אילן.',
'5b:7:2': 'באילן שבמשל יש כל מה שהאדם צריך: ״פירותיו מתוקין, וצילו נאה, ואמת המים עוברת תחתיו״. הוא אכל מהפירות, שתה מהמים ונח בצל.',
'5b:7:3': 'כשהאדם במשל רצה ללכת, הוא שאל: ״אילן אילן, במה אברכך?״. אם אברך שפירותיך יהיו מתוקים, הם כבר מתוקים. שצילך יהיה נאה, הוא כבר נאה. שתעבור תחתיך אמת מים, כבר עוברת. לאילן כבר יש הכל.',
'5b:7:4': 'אז האדם במשל מצא ברכה אחת שעוד אפשר לברך: ״יהי רצון שכל נטיעות שנוטעין ממך יהיו כמותך״. שכל השתילים שיילקחו ממך יהיו כמוך. הברכה ממשיכה בתחילת דף ו., ושם גם יבוא הנמשל.',
// ---------- ו׳ ע״א ----------
'6a:0:0': 'זה סוף המשל של ר׳ יצחק מסוף דף ה:. כשרב נחמן ביקש ברכה, ר׳ יצחק סיפר על אדם במדבר שמצא אילן שיש בו הכל. האדם בירך אותו: ״שכל נטיעות שנוטעין ממך יהיו כמותך״.',
'6a:0:1': 'עכשיו בא הנמשל, ר׳ יצחק מדבר לרב נחמן: ״אף אתה, במה אברכך?״. אם בתורה, יש לך תורה. אם בעושר, יש לך עושר. אם בבנים, יש לך בנים. כמו האילן, לרב נחמן כבר יש את כל מה שאפשר לאחל.',
'6a:0:2': 'אז ר׳ יצחק מברך את רב נחמן את הברכה היחידה שנשארה, כמו באילן: ״יהי רצון שיהיו צאצאי מעיך כמותך״, שהילדים שלך יהיו כמוך. כאן נגמר המעשה, והגמרא חוזרת לענייני הגשם.',
'6a:1:0': 'הגמרא חוזרת לנושא הגשם, לפסוק ״מורה ומלקוש״ שבו ר׳ מאיר השתמש בדף ה.. ברייתא (״תנו רבנן״) שואלת: למה הגשם הראשון של החורף נקרא ״יורה״? פירוש ראשון: כי הוא ״מורה״, מלמד את האנשים להטיח את הגגות לפני החורף, להכניס את הפירות מהשדה ולעשות כל צרכיהם.',
'6a:1:1': 'פירוש שני לשם ״יורה״: ״שמרוה את הארץ ומשקה עד התהום״. הוא משקה את האדמה לעומק, עד המים שמתחת לאדמה.',
'6a:1:2': 'פירוש שלישי לשם ״יורה״: ״שיורד בנחת ואינו יורד בזעף״, הוא יורד בעדינות ולא בסערה. רש״י מסביר שזה כמו מורה שמלמד את תלמידו בנחת.',
'6a:2:0': 'הברייתא בודקת אפשרות הפוכה: ״או אינו״, אולי לא. אולי ״יורה״ הוא דווקא גשם מזיק, שמפיל את הפירות מהעצים, שוטף את הזרעים ומשחית את האילנות? מאיפה יודעים שהיורה הוא לברכה?',
'6a:2:1': 'התשובה לשאלה ״אולי היורה מזיק״: ״תלמוד לומר מלקוש״. הפסוק מזכיר את היורה יחד עם המלקוש. ״מה מלקוש לברכה, אף יורה לברכה״: כמו שהמלקוש הוא גשם טוב, גם היורה טוב.',
'6a:2:2': 'אותה שאלה לגבי המלקוש: ״או אינו?״. אולי ״מלקוש״ הוא דווקא גשם מזיק, שמפיל בתים, משבר אילנות ומעלה ארבה?',
'6a:2:3': 'והתשובה: ״תלמוד לומר יורה״. הפסוק מזכיר את המלקוש יחד עם היורה. ״מה יורה לברכה, אף מלקוש לברכה״.',
'6a:2:4': 'הגמרא מקשה על הברייתא: ״ויורה גופיה מנלן?״. הוכחנו שהיורה לברכה מהמלקוש, ושהמלקוש לברכה מהיורה. זה מעגל! מאיפה יודעים מלכתחילה שלפחות אחד מהם לברכה?',
'6a:2:5': 'התשובה לבעיית המעגל: יש פסוק מפורש ביואל, ״ובני ציון גילו ושמחו בה׳ אלהיכם, כי נתן לכם את המורה לצדקה״. הפסוק אומר במפורש שה״מורה״, היורה, ניתן ״לצדקה״, כלומר לברכה. זה העוגן: ממנו לומדים שהיורה לברכה, ומהיורה שגם המלקוש לברכה.',
'6a:3:0': 'ברייתא נוספת על היורה והמלקוש, הפעם על הזמן שלהם: ״יורה במרחשון ומלקוש בניסן״. היורה הוא הגשם הראשון בתחילת החורף, והמלקוש הוא הגשם האחרון בסופו.',
'6a:3:1': 'הברייתא אמרה ״יורה במרחשון ומלקוש בניסן״, ועכשיו היא שואלת: אולי לא? אולי היורה בתשרי, חודש לפני, והמלקוש באייר, חודש אחרי?',
'6a:3:2': 'התשובה לשאלה ״אולי יורה בתשרי ומלקוש באייר?״: כתוב ״ונתתי מטר ארצכם בעתו״, כל גשם בזמנו הנכון. כלומר במרחשון ובניסן, ולא חודש לפני או אחרי.',
'6a:3:3': 'עכשיו הגמרא מסבירה את השם ״מלקוש״. פירוש של שמואל (״רב יהודה אמר״ בשמו): ״דבר שמל קשיותיהן של ישראל״, הגשם ש״מל״, כלומר מרכך, את הקשיות של ישראל. רש״י מסביר: כשהמלקוש לא יורד בזמן, ישראל מתעוררים וחוזרים בתשובה.',
'6a:3:4': 'פירוש אחר של ״מלקוש״, מבית מדרשו של ר׳ ישמעאל: ״דבר שממלא תבואה בקשיה״, הגשם שממלא את התבואה בגבעולים שלה. ״מל״ = ממלא, ו״קש״ = הגבעולים.',
'6a:3:5': 'פירוש שלישי של ״מלקוש״, מברייתא (״מתניתא תנא״): ״שיורד על המלילות ועל הקשין״, הגשם שיורד על השיבולים המלאות ועל הגבעולים.',
'6a:4:0': 'ברייתא נוספת שואלת על זמן היורה: הוא במרחשון, או אולי מאוחר יותר, בכסליו?',
'6a:4:1': 'התשובה לשאלה ״אולי היורה בכסליו?״: כתוב ״בעתו יורה ומלקוש״, השניים יחד. כמו שהמלקוש יורד בזמנו (בניסן), כך גם היורה יורד בזמנו, במרחשון.',
'6a:4:2': 'בדפוס יש כאן הגהה (תוספת בסוגריים): ״כיון שיצא ניסן וירדו גשמים — אינו סימן ברכה״. גשם שיורד אחרי חודש ניסן כבר לא נחשב לברכה, כי הוא מזיק לתבואה שבשדה.',
'6a:4:3': 'ברייתא אחרת (״תניא אידך״) מביאה מחלוקת על זמן היורה. ר׳ מאיר אומר שהיורה במרחשון, וחכמים אומרים שהוא בכסליו.',
'6a:4:4': 'בברייתא ״תניא אידך״ ר׳ מאיר אמר שהיורה במרחשון, ו״חכמים אומרים: יורה בכסליו״. הגמרא שואלת: מי הם ה״חכמים״ האלה?',
'6a:4:5': 'התשובה לשאלה ״מאן חכמים?״: רב חסדא אומר שזה ר׳ יוסי. והוא מביא ברייתא, ״איזו היא רביעה ראשונה?״, שבה רואים שאצל ר׳ יוסי הגשמים מאוחרים, עד ראש חודש כסליו. ״רביעה״ היא גשם שמרווה את האדמה.',
'6a:4:6': 'בברייתא על ״רביעה ראשונה״, שיטת ר׳ מאיר: יש שלוש רביעות. ״הבכירה״ (המוקדמת) בג׳ במרחשון, ״הבינונית״ בז׳ במרחשון, ו״האפילה״ (המאוחרת) בי״ז במרחשון.',
'6a:4:7': 'שיטת ר׳ יהודה באותה ברייתא: שלוש הרביעות הן בז׳, בי״ז ובכ״ג במרחשון. כלומר כל רביעה מאוחרת בשלב אחד מר׳ מאיר.',
'6a:4:8': 'שיטת ר׳ יוסי באותה ברייתא: שלוש הרביעות הן בי״ז ובכ״ג במרחשון ובראש חודש כסליו. עוד שלב אחד מאוחר יותר. לכן אצלו הרביעה האחרונה כבר בכסליו, וזה מתאים ל״חכמים״ שאמרו שהיורה בכסליו.',
'6a:4:9': 'הוכחה לשיטת ר׳ יוסי: ״וכן היה ר׳ יוסי אומר: אין היחידים מתענין עד שיגיע ראש חודש כסליו״. מי שרוצה להתענות על חוסר גשם מתחיל רק בראש חודש כסליו, כי זה זמן הרביעה השלישית שלו. רק אם גם היא לא ירדה, יש סיבה לדאגה.',
'6a:4:10': 'פסק ההלכה של רב חסדא: ״הלכה כר׳ יוסי״. כלומר הרביעות הן בי״ז במרחשון, בכ״ג במרחשון ובראש חודש כסליו.',
'6a:5:0': 'זה ביאור שלי, לא מהגמרא. לגבי ״מה יורה לברכה, אף מלקוש לברכה״ ולהפך: כשלומדים שני דברים זה מזה, צריך שלפחות אחד מהם יהיה ידוע ממקור נפרד. לכן הגמרא שאלה ״ויורה גופיה מנלן?״ וחיפשה פסוק מפורש.',
'6a:5:1': 'עוד ביאור שלי: המחלוקת על שלוש הרביעות (ר׳ מאיר, ר׳ יהודה, ר׳ יוסי) היא בעצם מחלוקת עד מתי גשם שמאחר עדיין נחשב ״בעתו״, בזמנו. ומתי זה כבר סימן לבעיה.',
'6a:5:2': 'סיכום של תפקיד כל רביעה, מתוך ההמשך (ר׳ זירא בדף ו:): ברביעה הראשונה מתחילים לבקש גשם, בשלישית מתחילים להתענות אם לא ירד, והשנייה חשובה לעניין נדרים.',
'6a:6:0': 'אמימר מביא גרסה אחרת של מה שרב חסדא פסק. לפיה רב חסדא לא פסק כר׳ יוסי, אלא ״הלכה כרבן גמליאל״, שמבקשים גשם מז׳ במרחשון (המשנה בדף י.).',
'6a:6:1': 'ברייתא בשם רבן שמעון בן גמליאל: ״גשמים שירדו שבעה ימים זה אחר זה, בלא הפסקה, מונה בהם רביעה ראשונה ושנייה ושלישית״. אם ירד גשם שבעה ימים ברצף, הוא נחשב לשלוש הרביעות יחד.',
'6a:6:2': 'הגמרא שואלת על הברייתא של רשב״ג, שגשמים של שבעה ימים רצופים נחשבים לשלוש הרביעות: ״כמאן?״, כשיטת מי זה מתאים?',
'6a:6:3': 'התשובה לשאלה ״כמאן?״: כר׳ יוסי. אצלו בין רביעה לרביעה יש בערך שבוע (י״ז, כ״ג, ר״ח כסליו), ולכן שבעה ימי גשם יכולים להיחשב לשלושתן. ורב חסדא פוסק כמותו.',
'6a:6:4': 'הגמרא שואלת: למה צריך לדעת מתי כל רביעה? ברביעה הראשונה מתחילים לבקש גשם, ובשלישית מתחילים להתענות אם לא ירד. אבל הרביעה השנייה, ״למאי?״, למה היא חשובה?',
'6a:6:5': 'ר׳ זירא עונה: הרביעה השנייה חשובה ״לנדרים״, לעניין נדרים שתלויים בזמן הגשם. ההסבר המלא מגיע בדף ו:.',
};
